SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '标题',
  `intro` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '简介',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '内容',
  `cover_img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '封面',
  `views` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '阅读量',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态0草稿1发布',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `creator_id` int NOT NULL COMMENT '创建人id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updater_id` int UNSIGNED NOT NULL DEFAULT 0 COMMENT '更新人id',
  `is_deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否删除',
  `cate_id` int NOT NULL DEFAULT 0 COMMENT '分类id',
  `tag_id` int NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 49 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of article
-- ----------------------------
INSERT INTO `article` VALUES (1, 'CSS 学习笔记', 'CSS 学习笔记，涵盖基础选择器、属性、复合选择器、显示模式、特性、布局、定位、显示隐藏等多方面内容。', '# CSS 学习笔记\n\n## 一、CSS 基础选择器\n\n1. 标签选择器\n   标签名 {属性1: 属性值1;}\n2. 类选择器\n   .类名 {属性1: 属性值1;}\n3. id 选择器\n   #id名 {属性1: 属性值1;}\n   类选择器在修改样式中用的最多，id 选择器一般用于页面唯一性的元素上，经常和 JavaScript 搭配使用\n4. 通配符选择器\n\n   `* {属性1: 属性值1;}`\n\n## 二、CSS 字体属性\n\n1. font-family: Arial,\"Microsoft Yahei\", \"微软雅黑\";\n2. font-size: 20px;\n3. font-weight: bold;\n   属性值100-900,400等同于normal，而700等同于bold，不带单位\n4. font-style: normal;	italic 斜体\n   CSS 使用 font-style 属性设置文本的风格\n   注意： 平时我们很少给文字加斜体，反而要给斜体标签（em，i）改为不倾斜字体\n5. 字体属性可以把以上文字样式综合来写, 这样可以更节约代码:\n   font: font-style font-weight font-size/line-height font-family;\n\n## 三、CSS 文本属性\n\n1. color 属性用于定义文本的颜色\n2. text-align 属性用于设置元素内文本内容的水平对齐方式\n3. text-decoration 属性规定添加到文本的修饰. 可以给文本添加下划线、删除线、上划线等\n4. text-indent 属性用来指定文本的第一行的缩进，通常是将段落的首行缩进\n5. line-height 属性用于设置行间的距离（行高）. 可以控制文字行与行之间的距离\n   css引入方式有行内样式表、内部样式表和外部样式表\n\n## 四、Emmet语法\n\n1. 生成标签 直接输入标签名 按tab键即可 比如 div 然后tab 键，就可以生成 <div></div>\n2. 如果想要生成多个相同标签 加上 * 就可以了 比如 div*3 就可以快速生成3个div\n3. 如果有父子级关系的标签，可以用 > 比如 ul > li就可以了\n4. 如果有兄弟关系的标签，用 + 就可以了 比如 div+p\n5. 如果生成带有类名或者id名字的， 直接写 .demo 或者 #two tab 键就可以了\n6. 如果生成的div 类名是有顺序的， 可以用 自增符号 $\n7. 如果想要在生成的标签内部写内容可以用 { } 表示\n\n## 五、CSS 的复合选择器\n\n1. 后代选择器 (重要）\n   元素1 元素2 { 样式声明 }\n2. 子选择器 (重要）\n   子元素选择器（子选择器）只能选择作为某元素的最近一级子元素. 简单理解就是选亲儿子元素.\n   元素1 > 元素2 { 样式声明 }\n3. 并集选择器 (重要）\n   并集选择器可以选择多组标签, 同时为他们定义相同的样式。通常用于集体声明.\n   元素1,元素2 { 样式声明 }\n4. 伪类选择器\n   伪类选择器用于向某些选择器添加特殊的效果，比如给链接添加特殊效果，或选择第1个，第n个元素。\n   伪类选择器书写最大的特点是用冒号（:）表示，比如 :hover 、 :first-child\n   链接伪类选择器\n\n- 为了确保生效，请按照 LVHA 的循顺序声明 :link－:visited－:hover－:active。\n- :focus 伪类选择器\n  :focus 伪类选择器用于选取获得焦点的表单元素。\n  input:focus { background-color:yellow;}\n\n## 六、元素显示模式\n\n定义：元素显示模式就是元素（标签）以什么方式进行显示，比如 `<div>`自己占一行，比如一行可以放多个 `<span>`。\n作用：网页的标签非常多，在不同地方会用到不同类型的标签，了解他们的特点可以更好的布局我们的网页。\nHTML 元素一般分为块元素和行内元素两种类型。\n\n### 1、块元素\n\n常见的块元素有 `<h1>~<h6>、<p>、<div>、<ul>、<ol>、<li>`等，其中 `<div> `标签是最典型的块元素。\n块级元素的特点：\n① 比较霸道，自己独占一行。\n② 高度，宽度、外边距以及内边距都可以控制。\n③ 宽度默认是容器（父级宽度）的100%。\n④ 是一个容器及盒子，里面可以放行内或者块级元素\n注意：文字类的元素内不能使用块级元素\n` <p>`标签主要用于存放文字，因此 `<p>`里面不能放块级元素，特别是不能放 `<div>`\n同理，` <h1>~<h6>`等都是文字类块级标签，里面也不能放其他块级元素\n\n### 2、行内元素\n\n常见的行内元素有 ` <a>、<strong>、<b>、<em>、<i>、<del>、<s>、<ins>、<u>、<span>`等，其中 `<span>` 标签是最典型的行内元素。有的地方也将行内元素称为内联元素。 行内元素的特点： ① 相邻行内元素在一行上，一行可以显示多个。 ② 高、宽直接设置是无效的。 ③ 默认宽度就是它本身内容的宽度。 ④ 行内元素只能容纳文本或其他行内元素。 注意：链接里面不能再放链接  特殊情况链接 `<a>`里面可以放块级元素，但是给 `<a>` 转换一下块级模式最安全\n\n### 3、行内块元素\n\n在行内元素中有几个特殊的标签 —— `<img />、<input />、<td>`，它们同时具有块元素和行内元素的特点。\n有些资料称它们为行内块元素。\n行内块元素的特点：\n① 和相邻行内元素（行内块）在一行上，但是他们之间会有空白缝隙。一行可以显示多个（行内元素特点）。\n② 默认宽度就是它本身内容的宽度（行内元素特点）。\n③ 高度，行高、外边距以及内边距都可以控制（块级元素特点）。\n\n### 4、元素显示模式转换\n\n转换为块元素：display:block;\n转换为行内元素：display:inline;\n转换为行内块：display: inline-block;\n\n## 七、CSS 的背景\n\n1. background-color 属性定义了元素的背景颜色\n   一般情况下元素背景颜色默认值是 transparent（透明），我们也可以手动指定背景颜色为透明色\n2. background-image 属性描述了元素的背景图像\n   background-image : none | url (url);\n   注意：背景图片后面的地址，千万不要忘记加 URL，同时里面的路径不要加引号。\n3. background-repeat 背景平铺\n4. background-position 背景图片位置\n   background-position: x y;\n   参数代表的意思是：x 坐标和 y 坐标。 可以使用 方位名词 或者 精确单位\n\n```\n1. 参数是方位名词\n    如果指定的两个值都是方位名词，则两个值前后顺序无关，比如 left top 和 top left 效果一致\n    如果只指定了一个方位名词，另一个值省略，则第二个值默认居中对齐\n2. 参数是精确单位\n    如果参数值是精确坐标，那么第一个肯定是 x 坐标，第二个一定是 y 坐标\n    如果只指定一个数值，那该数值一定是 x 坐标，另一个默认垂直居中\n3. 参数是混合单位\n    如果指定的两个值是精确单位和方位名词混合使用，则第一个值是 x 坐标，第二个值是 y 坐标\n```\n\n5. background-attachment 背景图像固定（背景附着）\n   background-attachment : scroll | fixed\n6. 背景复合写法\n   background: 背景颜色 背景图片地址 背景平铺 背景图像滚动 背景图片位置;\n   background: transparent url(image.jpg) repeat-y fixed top ;\n7. 背景色半透明\n   CSS3 为我们提供了背景颜色半透明的效果\n   background: rgba(0, 0, 0, 0.3);\n\n## 八、CSS 三大特性\n\nCSS 有三个非常重要的三个特性：层叠性、继承性、优先级。\n\n### 1、层叠性\n\n相同选择器给设置相同的样式，此时一个样式就会覆盖（层叠）另一个冲突的样式。层叠性主要解决样式冲突的问题\n层叠性原则：\n样式冲突，遵循的原则是就近原则，哪个样式离结构近，就执行哪个样式；样式不冲突，不会层叠\n\n### 2、继承性\n\nCSS中的继承: 子标签会继承父标签的某些样式，如文本颜色和字号。简单的理解就是：子承父业。\n\n### 3、优先级\n\n当同一个元素指定多个选择器，就会有优先级的产生。\n选择器相同，则执行层叠性；选择器不同，则根据选择器权重执行\n选择器权重：\n继承或者通配符 *		0,0,0,0\n标签选择器			0,0,0,1\n类选择器、伪类选择器  0,0,1,0\nid选择器				0,1,0,0\n行内选择器			1,0,0,0\n！important  		无穷大\n优先级注意点：\n\n1. 权重是有4组数字组成,但是不会有进位。\n2. 可以理解为类选择器永远大于元素选择器, id选择器永远大于类选择器,以此类推..\n3. 等级判断从左向右，如果某一位数值相同，则判断下一位数值。\n4. 可以简单记忆法: 通配符和继承权重为0, 标签选择器为1,类(伪类)选择器为 10, id选择器 100, 行内样式表为1000, !important 无穷大.\n5. 继承的权重是0， 如果该元素没有直接选中，不管父元素权重多高，子元素得到的权重都是 0。\n   注意：\n   权重叠加：如果是复合选择器，则会有权重叠加，需要计算权重。\n\n## 九、盒子模型\n\n页面布局要学习三大核心：盒子模型、浮动和定位. 学习好盒子模型能非常好的帮助我们布局页面\nCSS 盒子模型本质上是一个盒子，封装周围的 HTML 元素，它包括：边框、外边距、内边距、和 实际内容\n\n### 1、 边框（border）\n\nborder可以设置元素的边框。边框有三部分组成:边框宽度(粗细) 边框样式 边框颜色\nborder : border-width || border-style || border-color		没有顺序\n边框样式 border-style 可以设置如下值：\n none：没有边框即忽略所有边框的宽度（默认值）\n solid：边框为单实线(最为常用的)  dashed：边框为虚线\n dotted：边框为点线\nborder-collapse 属性控制浏览器绘制表格边框的方式。它控制相邻单元格的边框。\nborder-collapse:collapse;\ncollapse 单词是合并的意思\nborder-collapse:collapse; 表示相邻边框合并在一起\n注意：\n边框会额外增加盒子的实际大小。\n\n### 2、内边距（padding）\n\npadding属性用于设置内边距，即边框与内容之间的距离。\n当我们给盒子指定padding值之后，发生了2 件事情：\n\n1. 内容和边框有了距离，添加了内边距。\n2. padding影响了盒子实际大小。\n   也就是说，如果盒子已经有了宽度和高度，此时再指定内边框，会撑大盒子。\n   3、外边距（margin）\n   margin属性用于设置外边距，即控制盒子和盒子之间的距离。\n   外边距可以让块级盒子水平居中，但是必须满足两个条件：\n   ①盒子必须指定了宽度（width）。\n   ②盒子左右的外边距都设置为auto 。\n   margin: 0 auto;\n   注意：以上方法是让块级元素水平居中，行内元素或者行内块元素水平居中给其父元素添加text-align:center 即可。\n   #外边距合并\n3. 相邻块元素垂直外边距的合并\n   使用margin定义块元素的垂直外边距时，可能会出现外边距的合并。\n   解决方案：尽量只给一个盒子添加margin 值。\n4. 嵌套块元素垂直外边距的塌陷\n   对于两个嵌套关系（父子关系）的块元素，父元素有上外边距同时子元素也有上外边距，此时父元素会塌陷较大的外边距值。\n   解决方案：\n   ①可以为父元素定义上边框。\n   ②可以为父元素定义上内边距。\n   ③可以为父元素添加overflow:hidden。\n   还有其他方法，比如浮动、固定，绝对定位的盒子不会有塌陷问题\n   4、清除内外边距\n\n`* { padding:0; /* 清除内边距 */ margin:0; /* 清除外边距 */ }`\n去掉 li 前面的 项目符号(小圆点)\nlist-style: none;\n\n5. 圆角边框\n   border-radius:length;\n6. 盒子阴影\n   CSS3 中新增了盒子阴影，我们可以使用 box-shadow 属性为盒子添加阴影。\n   box-shadow: h-shadow v-shadow blur spread color inset;\n   注意：\n7. 默认的是外阴影(outset), 但是不可以写这个单词,否则造成阴影无效\n   2.盒子阴影不占用空间，不会影响其他盒子排列。\n   7、文字阴影\n   在 CSS3 中，我们可以使用 text-shadow 属性将阴影应用于文本\n   text-shadow: h-shadow v-shadow blur color;\n\n## 十、浮动\n\nCSS 提供了三种传统布局方式(简单说,就是盒子如何进行排列顺序)：普通流（标准流）、浮动、定位\n所谓的标准流: 就是标签按照规定好默认方式排列\n\n### 1、为什么需要浮动\n\n总结： 有很多的布局效果，标准流没有办法完成，此时就可以利用浮动完成布局。 因为浮动可以改变元素标签默认的排列方式.\n浮动最典型的应用：可以让多个块级元素一行内排列显示。\n网页布局第一准则：多个块级元素纵向排列找标准流，多个块级元素横向排列找浮动\n\n### 2、什么是浮动\n\nfloat 属性用于创建浮动框，将其移动到一边，直到左边缘或右边缘触及包含块或另一个浮动框的边缘。\n选择器 { float: 属性值; }\n\n### 3、浮动特性（重难点）\n\n加了浮动之后的元素,会具有很多特性,需要我们掌握的.\n\n1. 浮动元素会脱离标准流(脱标)\n2. 脱离标准普通流的控制（浮） 移动到指定位置（动）, （俗称脱标）\n3. 浮动的盒子不再保留原先的位置\n4. 浮动的元素会一行内显示并且元素顶部对齐\n5. 浮动的元素会具有行内块元素的特性\n   为了约束浮动元素位置, 我们网页布局一般采取的策略是: 先用标准流的父元素排列上下位置, 之后内部子元素采取浮动排列左右位置. 符合网页布局第一准侧.\n\n### 4、浮动布局注意点\n\n1. 浮动和标准流的父盒子搭配\n   先用标准流的父元素排列上下位置, 之后内部子元素采取浮动排列左右位置\n2. 一个元素浮动了，理论上其余的兄弟元素也要浮动\n   一个盒子里面有多个子盒子，如果其中一个盒子浮动了，那么其他兄弟也应该浮动，以防止引起问题。\n   浮动的盒子只会影响浮动盒子后面的标准流,不会影响前面的标准流\n\n## 十一、清除浮动\n\n### 1、为什么需要清除浮动？\n\n由于父级盒子很多情况下，不方便给高度，但是子盒子浮动又不占有位置，最后父级盒子高度为 0 时，就会影响下面的标准流盒子。\n① 父级没高度\n② 子盒子浮动了\n③ 影响下面布局了，我们就应该清除浮动了\n\n### 2、清除浮动本质\n\n清除浮动的本质是清除浮动元素造成的影响\n如果父盒子本身有高度，则不需要清除浮动\n清除浮动之后，父级就会根据浮动的子盒子自动检测高度。父级有了高度，就不会影响下面的标准流了\n\n### 3、清除浮动语法\n\n选择器{clear: right | left | both;}\n我们实际工作中，几乎只用 clear: both;\n清除浮动的策略是: 闭合浮动.\n\n### 4、清除浮动的方法\n\n1. 额外标签法也称为隔墙法，是 W3C 推荐的做法。\n   额外标签法也称为隔墙法，是 W3C 推荐的做法。\n   额外标签法会在浮动元素末尾添加一个空的标签。例如 ` <div style=”clear:both”></div>`，或者其他标签（如 `<br />`等）。\n   优点： 通俗易懂，书写方便\n   缺点： 添加许多无意义的标签，结构化较差\n   注意： 要求这个新的空标签必须是块级元素\n2. 父级添加 overflow 属性\n   可以给父级添加 overflow 属性，将其属性值设置为 hidden、 auto 或 scroll 。\n   子不教,父之过,注意是给父元素添加代码\n   优点：代码简洁\n   缺点：无法显示溢出的部分\n3. 父级添加after伪元素\n   :after 方式是额外标签法的升级版。也是给父元素添加\n\n```\n.clearfix:after {\n   content: \"\";\n   display: block;\n   height: 0;\n   clear: both;\n   visibility: hidden;\n   }\n   .clearfix { /* IE6、7 专有 */\n   *zoom: 1;\n   }\n```\n\n 优点：没有增加标签，结构更简单\n 缺点：照顾低版本浏览器\n 代表网站： 百度、淘宝网、网易等\n4. 父级添加双伪元素\n也是给给父元素添加\n\n```\n.clearfix:before,.clearfix:after {\n   content:\"\";\n   display:table;\n   }\n   .clearfix:after {\n   clear:both;\n   }\n   .clearfix {\n   *zoom:1;\n   }\n```\n\n 优点：代码更简洁\n 缺点：照顾低版本浏览器\n 代表网站：小米、腾讯等\n\n## 十二、css书写顺序\n\n建议遵循以下顺序：\n\n1. 布局定位属性：display / position / float / clear / visibility / overflow（建议 display 第一个写，毕竟关系到模式）\n2. 自身属性：width / height / margin / padding / border / background\n3. 文本属性：color / font / text-decoration / text-align / vertical-align / white- space / break-word\n4. 其他属性（CSS3）：content / cursor / border-radius / box-shadow / text-shadow / background:linear-gradient …\n   例：\n\n```\n.jdc {\n   display: block;\n   position: relative;\n   float: left;\n   width: 100px;\n   height: 100px;\n   margin: 0 10px;\n   padding: 20px 0;\n   font-family: Arial, \'Helvetica Neue\', Helvetica, sans-serif;\n   color: #333;\n   background: rgba(0,0,0,.5);\n   border-radius: 10px;\n   }\n```\n\n## 十三、定位\n\n### 1、为什么需要定位\n\n1. 某个元素可以自由的在一个盒子内移动位置，并且压住其他盒子。\n2. 当我们滚动窗口的时候，盒子是固定屏幕某个位置的。\n   以上效果，标准流或浮动都无法快速实现，此时需要定位来实现。\n   所以：\n   浮动可以让多个块级盒子一行没有缝隙排列显示，经常用于横向排列盒子。\n   定位则是可以让盒子自由的在某个盒子内移动位置或者固定屏幕中某个位置，并且可以压住其他盒子。\n\n### 2、定位组成\n\n定位：将盒子定在某一个位置，所以定位也是在摆放盒子， 按照定位的方式移动盒子。\n定位 = 定位模式 + 边偏移 。\n定位模式用于指定一个元素在文档中的定位方式。边偏移则决定了该元素的最终位置。\n边偏移就是定位的盒子移动到最终位置。有 top、bottom、left 和 right 4 个属性，如：top：100px;\n\n### 3、4种定位模式：\n\n1. 静态定位\n   静态定位是元素的默认定位方式，无定位的意思。\n   选择器 { position: static; }\n   静态定位按照标准流特性摆放位置，它没有边偏移\n   静态定位在布局时很少用到\n2. 相对定位 relative（重要）\n   相对定位是元素在移动位置的时候，是相对于它原来的位置来说的（自恋型）。\n   选择器 { position: relative; }\n   相对定位的特点：（务必记住）\n   - 它是相对于自己原来的位置来移动的（移动位置的时候参照点是自己原来的位置）。\n   - 原来在标准流的位置继续占有，后面的盒子仍然以标准流的方式对待它。\n     因此，相对定位并没有脱标。它最典型的应用是给绝对定位当爹的。\n3. 绝对定位 absolute（重要）\n   绝对定位是元素在移动位置的时候，是相对于它祖先元素来说的（拼爹型）。\n   选择器 { position: absolute; }\n   绝对定位的特点：（务必记住）\n   - 如果没有祖先元素或者祖先元素没有定位，则以浏览器为准定位（Document 文档）。\n   - 如果祖先元素有定位（相对、绝对、固定定位），则以最近一级的有定位祖先元素为参考点移动位置。\n   - 绝对定位不再占有原先的位置。（脱标）\n     所以绝对定位是脱离标准流的。\n     子绝父相的由来：\n     子级是绝对定位的话，父级要用相对定位\n     ① 子级绝对定位，不会占有位置，可以放到父盒子里面的任何一个地方，不会影响其他的兄弟盒子。\n     ② 父盒子需要加定位限制子盒子在父盒子内显示。\n     ③ 父盒子布局时，需要占有位置，因此父亲只能是相对定位。\n     总结： 因为父级需要占有位置，因此是相对定位， 子盒子不需要占有位置，则是绝对定位\n     当然，子绝父相不是永远不变的，如果父元素不需要占有位置，子绝父绝也会遇到。\n4. 固定定位 fixed （重要）\n   固定定位是元素固定于浏览器可视区的位置。主要使用场景： 可以在浏览器页面滚动时元素的位置不会改变\n   选择器 { position: fixed; }\n   固定定位的特点：（务必记住）\n\n- 以浏览器的可视窗口为参照点移动元素。\n  跟父元素没有任何关系\n  不随滚动条滚动\n- 固定定位不在占有原先的位置。\n  固定定位也是脱标的，其实固定定位也可以看做是一种特殊的绝对定位\n  #固定定位小技巧： 固定在版心右侧位置。\n  小算法：\n  让固定定位的盒子 left: 50%. 走到浏览器可视区（也可以看做版心） 的一半位置。\n  让固定定位的盒子 margin-left: 版心宽度的一半距离。 多走 版心宽度的一半位置就可以让固定定位的盒子贴着版心右侧对齐了。\n\n5. 粘性定位 sticky（了解）\n   粘性定位可以被认为是相对定位和固定定位的混合。 Sticky 粘性的\n   选择器 { position: sticky; top: 10px; }\n   粘性定位的特点：\n\n- 以浏览器的可视窗口为参照点移动元素（固定定位特点）\n- 粘性定位占有原先的位置（相对定位特点）\n- 必须添加 top 、left、right、bottom 其中一个才有效\n  跟页面滚动搭配使用。 兼容性较差，IE 不支持。\n  真实开发中一般使用js实现相同效果。\n\n### 4、定位叠放次序 z-index\n\n```\n在使用定位布局时，可能会出现盒子重叠的情况。此时，可以使用 z-index 来控制盒子的前后次序 (z轴)\n选择器 { z-index: 1; }\n数值可以是正整数、负整数或 0, 默认是 auto，数值越大，盒子越靠上\n如果属性值相同，则按照书写顺序，后来居上\n数字后面不能加单位\n只有定位的盒子才有 z-index 属性\n```\n\n### 5、 定位的拓展\n\n绝对定位的盒子居中\n加了绝对定位的盒子不能通过 margin:0 auto 水平居中，但是可以通过以下计算方法实现水平和垂直居中。\n① left: 50%;：让盒子的左侧移动到父级元素的水平中心位置。\n② margin-left: -100px;：让盒子向左移动自身宽度的一半。\n\n### 定位特殊特性\n\n绝对定位和固定定位也和浮动类似。\n行内元素添加绝对或者固定定位，可以直接设置高度和宽度。\n块级元素添加绝对或者固定定位，如果不给宽度或者高度，默认大小是内容的大小。\n脱标的盒子不会触发外边距塌陷\n浮动元素、绝对定位(固定定位）元素的都不会触发外边距合并的问题\n绝对定位（固定定位）会完全压住盒子\n浮动元素不同，只会压住它下面标准流的盒子，但是不会压住下面标准流盒子里面的文字（图片）\n但是绝对定位（固定定位） 会压住下面标准流所有的内容。\n浮动之所以不会压住文字，因为浮动产生的目的最初是为了做文字环绕效果的，文字会围绕浮动元素\n\n## 十四、元素的显示和隐藏\n\n本质：让一个元素在页面中隐藏或者显示出来。\n\n### 1、display 显示隐藏元素 但是不保留位置\n\ndisplay 属性用于设置一个元素应如何显示。\n display: none ；隐藏对象\n display：block ；除了转换为块级元素之外，同时还有显示元素的意思\ndisplay 隐藏元素后，不再占有原来的位置。\n后面应用及其广泛，搭配 JS 可以做很多的网页特效。\n\n### 2、visibility 显示隐藏元素 但是保留原来的位置\n\nvisibility 属性用于指定一个元素应可见还是隐藏。\n visibility：visible ; 元素可视\n visibility：hidden; 元素隐藏\nvisibility 隐藏元素后，继续占有原来的位置。\n如果隐藏元素想要原来位置， 就用 visibility：hidden\n如果隐藏元素不想要原来位置， 就用 display：none (用处更多 重点）\n\n### 3、overflow 溢出显示隐藏 但是只是对于溢出的部分处理\n\noverflow 属性指定了如果内容溢出一个元素的框（超过其指定高度及宽度） 时，会发生什么。\n但是如果有定位的盒子， 请慎用overflow:hidden 因为它会隐藏多余的部分。\n\n## 十五、CSS 高级技巧\n\n### 1、精灵图\n\n一个网页中往往会应用很多小的背景图像作为修饰，当网页中的图像过多时，服务器就会频繁地接收和发送请求图片，\n造成服务器请求压力过大，这将大大降低页面的加载速度。\n因此，为了有效地减少服务器接收和发送请求的次数，提高页面的加载速度，出现了 CSS 精灵技术（也称CSS Sprites、CSS 雪碧）。\n核心原理：将网页中的一些小背景图像整合到一张大图中 ，这样服务器只需要一次请求就可以了。\n使用精灵图核心总结：\n\n1. 精灵图主要针对于小的背景图片使用。\n2. 主要借助于背景位置来实现---background-position 。\n3. 一般情况下精灵图都是负值。（千万注意网页中的坐标： x轴右边走是正值，左边走是负值， y轴同理。）\n\n### 2、字体图标\n\n字体图标使用场景： 主要用于显示网页中通用、常用的一些小图标。\n字体图标可以为前端工程师提供一种方便高效的图标使用方式，展示的是图标，本质属于字体。\n注意： 字体图标不能替代精灵技术，只是对工作中图标部分技术的提升和优化。\n总结：\n如果遇到一些结构和样式比较简单的小图标，就用字体图标。\n如果遇到一些结构和样式复杂一点的小图片，就用精灵图。\n字体图标的引入：\n在 CSS 样式中全局声明字体： 简单理解把这些字体文件通过css引入到我们页面中。\n\n```\n@font-face {\n   font-family: \'icomoon\';\n   src: url(\'fonts/icomoon.eot?7kkyc2\');\n   src: url(\'fonts/icomoon.eot?7kkyc2#iefix\') format(\'embedded-opentype\'),\n   url(\'fonts/icomoon.ttf?7kkyc2\') format(\'truetype\'),\n   url(\'fonts/icomoon.woff?7kkyc2\') format(\'woff\'),\n   url(\'fonts/icomoon.svg?7kkyc2#icomoon\') format(\'svg\');\n   font-weight: normal;\n   font-style: normal;\n   }\n```\n\n给标签定义字体：\nspan {\nfont-family: \"icomoon\";\n}\n\n### 3、CSS 三角\n\n利用空盒子的border属性\n\n### 4、CSS 用户界面样式\n\n所谓的界面样式，就是更改一些用户操作样式，以便提高更好的用户体验。\n 1. 更改用户的鼠标样式\n例：li {cursor: pointer; } 	将鼠标形状设置为小手\n 2. 表单轮廓\n给表单添加 outline: 0; 或者 outline: none; 样式之后，就可以去掉默认的蓝色边框。\ninput {outline: none; }\n 3. 防止表单域拖拽\n实际开发中，我们文本域右下角是不可以拖拽的。\ntextarea{ resize: none;}\n\n### 5、vertical-align 属性应用\n\nCSS 的 vertical-align 属性使用场景： 经常用于设置图片或者表单(行内块元素）和文字垂直对齐。\n官方解释： 用于设置一个元素的垂直对齐方式，但是它只针对于行内元素或者行内块元素有效。\nvertical-align : baseline | top | middle | bottom\n字符位置被划分为bottom line底线、base line基线、middle line中线、top line 顶线\n图片、表单都属于行内块元素，默认的 vertical-align 是基线对齐。\n\n### 6、 解决图片底部默认空白缝隙问题\n\nbug：图片底侧会有一个空白缝隙，原因是行内块元素会和文字的基线对齐。\n主要解决方法有两种：\n给图片添加 vertical-align:middle | top| bottom 等。 （提倡使用的）\n把图片转换为块级元素 display: block;\n\n### 7、溢出的文字省略号显示\n\n单行文本溢出显示省略号--必须满足三个条件\n/*1. 先强制一行内显示文本*/\nwhite-space: nowrap; （ 默认 normal 自动换行）\n/*2. 超出的部分隐藏*/\noverflow: hidden;\n/*3. 文字用省略号替代超出的部分*/\ntext-overflow: ellipsis;\n多行文本溢出显示省略号\n多行文本溢出显示省略号，有较大兼容性问题， 适合于webKit浏览器或移动端（移动端大部分是webkit内核）\n更推荐让后台人员来做这个效果，因为后台人员可以设置显示多少个字，操作更简单。\n\n### 8、常见布局技巧\n\n1. margin负值运用\n   *1.让每个盒子margin 往左侧移动 -1px 正好压住相邻盒子边框\n   *2.鼠标经过某个盒子的时候，提高当前盒子的层级即可（如果没有有定位，则加相对定位（保留位置），如果有定位，则加z-index）\n2. 文字围绕浮动元素\n   巧妙运用浮动元素不会压住文字的特性\n3. 行内块巧妙运用\n   页码在页面中间显示:\n   *1. 把这些链接盒子转换为行内块， 之后给父级指定 text-align:center;\n   *2. 利用行内块元素中间有缝隙，并且给父级添加 text-align:center; 行内块元素会水平会居中\n\n### 9、CSS 三角强化\n\n```\n代码：\nwidth: 0;\nheight: 0;\nborder-color: transparent red transparent transparent;\nborder-style: solid;\nborder-width: 22px 8px 0 0;\n```\n\n### 10、CSS 初始化\n\n不同浏览器对有些标签的默认值是不同的，为了消除不同浏览器对HTML文本呈现的差异，照顾浏览器的兼容，我们需要对CSS 初始化\n简单理解： CSS初始化是指重设浏览器的样式。 (也称为CSS reset）\n每个网页都必须首先进行 CSS初始化\nUnicode编码字体：\n把中文字体的名称用相应的Unicode编码来代替，这样就可以有效的避免浏览器解释CSS代码时候出现乱码的问题。\n比如：\n黑体 \\9ED1\\4F53\n宋体 \\5B8B\\4F53\n微软雅黑 \\5FAE\\8F6F\\96C5\\9ED1\n', '', 0, 1, '2022-02-20 19:46:30', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (2, 'HTML5和CSS3新特性', '介绍 HTML5（新标签、表单、input 类型、表单属性）和 CSS3（选择器、盒子模型、过渡等）新特性及相关注意事项。', '# HTML5和CSS3新特性\n\n## 1.HTML5 的新特性\n\nHTML5 的新增特性主要是针对于以前的不足，增加了一些新的标签、新的表单和新的表单属性等。\n这些新特性都有兼容性问题，基本是 IE9+ 以上版本的浏览器才支持\n\n### 1.1 HTML5 新增的语义化标签\n\n`<header>`：头部标签\n\n`<nav>`：导航标签\n`<article>`：内容标签\n`<section>`：定义文档某个区域\n`<aside>`：侧边栏标签\n`<footer>`：尾部标签\n\n### 1.2 HTML5 新增的多媒体标签\n\n#### 1. 视频：`<video>`\n\n当前` <video>` 元素支持三种视频格式： 尽量使用 mp4格式\n语法：` <video src=\"文件地址\" controls=\"controls\"></video>`\n若考虑兼容性（了解，一般不使用）\n\n```\n<video controls=\"controls\" width=\"300\">\n<source src=\"move.ogg\" type=\"video/ogg\" >\n<source src=\"move.mp4\" type=\"video/mp4\" >\n您的浏览器暂不支持 <video> 标签播放视频\n</ video >\n```\n\n#### 2. 音频：`<audio>`\n\nHTML5 在不使用插件的情况下，也可以原生的支持音频格式文件的播放，当然，支持的格式是有限的。\n语法： `<audio src=\"文件地址\" controls=\"controls\"></audio>`\n若考虑兼容性 (了解)\n\n```\n< audio controls=\"controls\" >\n<source src=\"happy.mp3\" type=\"audio/mpeg\" >\n<source src=\"happy.ogg\" type=\"audio/ogg\" >\n您的浏览器暂不支持 <audio> 标签。\n</ audio>\n```\n\n多媒体标签总结：\n音频标签和视频标签使用方式基本一致\n浏览器支持情况不同\n谷歌浏览器把音频和视频自动播放禁止了\n我们可以给视频标签添加 muted 属性来静音播放视频，音频不可以（可以通过JavaScript解决）\n视频标签是重点，我们经常设置自动播放，不使用 controls 控件，循环和设置大小属性\n\n### 1.3 HTML5 新增的 input 类型\n\n重点记住： number tel search 这三个\n\n### 1.4 HTML5 新增的表单属性\n\n重点记住： placeholder	提示文本		表单的提示信息\nmultiple		multiple	可多选文件提交\n\n## 2. CSS3 的新特性\n\n现阶段主要学习：新增选择器和盒子模型以及其他特性\n\n### 2.1 CSS3 新增选择器\n\nCSS3 给我们新增了选择器，可以更加便捷，更加自由的选择目标元素。\n\n1. 属性选择器\n2. 结构伪类选择器\n3. 伪元素选择器\n\n### 2.2 属性选择器\n\n属性选择器可以根据元素特定属性的来选择元素。 这样就可以不用借助于类或者id选择器。\n\n1. E[att]\n   选择具有att属性的E元素\n2. E[att=\"val\"]\n   选择具有att属性且属性值等于val的E元素\n3. E[att^=\"val\"]\n   匹配具有att属性且值以val开头的E元素\n4. E[att$=\"val\"]\n   匹配具有att属性且值以val结尾的E元素\n5. E[att*=\"val\"]\n   匹配具有att属性且值中含有val的E元素\n   注意：\n   注意：类选择器、属性选择器、伪类选择器，权重为 0010。\n\n### 2.3 结构伪类选择器\n\n结构伪类选择器主要根据文档结构来选择器元素， 常用于根据父级选择器里面的子元素\nE:first-child	匹配父元素中的第一个子元素E\nE:last-child	匹配父元素中最后一一个E元素\nE:nth-child(n)	匹配父元素中的第n个子元素E\nE:first-of-type	指定类型E的第一个\nE:last-of-type	指定类型E的最后一个\nE:nth-of-type(n)	指定类型E的第n个\n注意：\n类选择器、属性选择器、伪类选择器，权重为 0010。\n\nnth-child（n） 选择某个父元素的一个或多个特定的子元素（重点）\n\nn 可以是数字，关键字和公式\nn 如果是数字，就是选择第 n 个子元素， 里面数字从1开始…\nn 可以是关键字：even 偶数，odd 奇数\nn 可以是公式：常见的公式如下 ( 如果n是公式，则从0开始计算，但是第 0 个元素或者超出了元素的个数会被忽略 )\n2n 偶数\n2n+1 奇数\n5n 5 10 15...\nn+5 从第5个开始(包含第五个)到最后\n-n+5 前5个(包含第5个)\n区别：\n\n1. nth-child 对父元素里面所有孩子排序选择（序号是固定的） 先找到第n个孩子，然后看看是否和E匹配\n2. nth-of-type 对父元素里面指定子元素进行排序选择。 先去匹配E ，然后再根据E 找第n个孩子\n   小结：\n   结构伪类选择器一般用于选择父级里面的第几个孩子\n   nth-child 对父元素里面所有孩子排序选择（序号是固定的） 先找到第n个孩子，然后看看是否和E匹配\n   nth-of-type 对父元素里面指定子元素进行排序选择。 先去匹配E ，然后再根据E 找第n个孩子\n   关于 nth-child（n） 我们要知道 n 是从 0 开始计算的，要记住常用的公式\n   如果是无序列表，我们肯定用 nth-child 更多\n   类选择器、属性选择器、伪类选择器，权重为 10。\n\n### 2.4 伪元素选择器（重点）\n\n伪元素选择器可以帮助我们利用CSS创建新标签元素，而不需要HTML标签，从而简化HTML结构\n::before	在元素内部的前面插入内容\n::after		在元素内部的后面插入内容\n注意：\nbefore 和 after 创建一个元素，但是属于行内元素\n新创建的这个元素在文档树中是找不到的，所以我们称为伪元素\n语法： element::before {}\nbefore 和 after 必须有 content 属性\nbefore 在父元素内容的前面创建元素，after 在父元素内容的后面插入元素\n伪元素选择器和标签选择器一样，权重为 1\n伪元素选择器使用场景1：伪元素字体图标...\n伪元素选择器使用场景2：伪元素清除浮动...\n\n### 2.5 CSS3 盒子模型\n\nCSS3 中可以通过 box-sizing 来指定盒模型，有2个值：即可指定为 content-box、border-box，这样我们计算盒子大小的方式就发生了改变。\n可以分成两种情况：\n\n1. box-sizing: content-box 盒子大小为 width + padding + border （以前默认的）\n2. box-sizing: border-box 盒子大小为 width\n   如果盒子模型我们改为了box-sizing: border-box ， 那padding和border就不会撑大盒子了（前提padding和border不会超过width宽度）\n\n### 2.6 其他特性 (了解)\n\n1. 图片变模糊\n   CSS3滤镜filter:将模糊或颜色偏移等图形效果应用于元素\n   filter: 函数(); 例如： filter: blur(5px); blur模糊处理 数值越大越模糊\n2. 计算盒子宽度 width: calc 函数\n   calc() 此CSS函数让你在声明CSS属性值时执行一些计算。\n   width: calc(100% - 80px);\n   括号里面可以使用 + - * / 来进行计算。\n\n### 2.7 CSS3 过渡（重点）\n\n过渡（transition)是CSS3中具有颠覆性的特征之一，我们可以在不使用 Flash 动画或JavaScript 的情况下，\n当元素从一种样式变换为另一种样式时为元素添加效果。\n过渡动画： 是从一个状态 渐渐的过渡到另外一个状态\n可以让我们页面更好看，更动感十足，虽然 低版本浏览器不支持（ie9以下版本） 但是不会影响页面布局。\n我们现在经常和 :hover 一起 搭配使用\n语法：transition: 要过渡的属性 花费时间 运动曲线 何时开始\n\n1. 属性：想要变化的 css 属性， 宽度高度 背景颜色 内外边距都可以 。如果想要所有的属性都变化过渡， 写一个all 就可以。\n2. 花费时间：单位是 秒（必须写单位） 比如 0.5s\n3. 运动曲线：默认是 ease （可以省略）\n4. 何时开始：单位是 秒（必须写单位）可以设置延迟触发时间 默认是 0s （可以省略）\n   记住过渡的使用口诀： 谁做过渡给谁加\n\n', '', 0, 1, '2022-02-23 19:06:19', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (3, 'CSS3进阶：2D、3D转换', '本文介绍了 CSS3 中 2D 转换（移动、旋转、缩放）、动画（创建与使用、属性介绍）和 3D 转换（移动、旋转、呈现）相关知识。', '# CSS3进阶 2D、3D转换\n\n## 一、2D转换\n\n### 1、2D 转换之移动 translate\n\n语法：	transform: translate(x,y);\n总结：\n定义 2D 转换，沿着 X 和 Y 轴移动元素\ntranslate中的百分比单位是相对于自身元素的 translate:(50%,50%);\ntranslate类似定位，不会影响到其他元素的位置\n对行内标签没有效果\n\n### 2、2D 转换之旋转 rotate\n\n语法：	transform:rotate(angle);\n总结：\n角度为正时，顺时针，负时，为逆时针\n默认旋转的中心点是元素的中心点\n\n### 3、2D 转换之缩放scale\n\n语法：	transform:scale(x,y);\n总结：\ntransform:scale(1,1) ：宽和高都放大一倍，相对于没有放大\ntransform:scale(2,2) ：宽和高都放大了2倍\ntransform:scale(2) ：只写一个参数，第二个参数则和第一个参数一样，相当于 scale(2,2)\ntransform:scale(0.5,0.5)：缩小\n\n## 二、动画\n\n动画（animation）是CSS3中具有颠覆性的特征之一，可通过设置多个节点来精确控制一个或一组动画，常用来实现复杂的动画效果。\n\n### 1、动画序列\n\n动画是使元素从一种样式逐渐变化为另一种样式的效果。您可以改变任意多的样式任意多的次数。\n在 @keyframes 中规定某项 CSS 样式，就能创建由当前样式逐渐改为新样式的动画效果。\n请用百分比来规定变化发生的时间，或用关键词 \"from\" 和 \"to\"，等同于 0% 和 100%。\n0% 是动画的开始，100% 是动画的完成。这样的规则就是动画序列。\n\n### 2、动画的基本使用\n\n1. 用keyframes 定义动画（类似定义类选择器）\n\n```\n @keyframes 动画名称 {\n   0%{\n   width:100px;\n   }\n   100%{\n   width:200px;\n   }\n   }\n```\n\n2. 元素使用动画\n\n```\ndiv {\n   width: 200px;\n   height: 200px;\n   background-color: aqua;\n   margin: 100px auto;\n   /* 调用动画 */\n   animation-name: 动画名称;\n   /* 持续时间 */\n   animation-duration: 持续时间;\n   }\n```\n\n### 3、动画简写属性\n\nanimation：动画名称 动画时间 运动曲线  何时开始  播放次数  是否反方向  动画等待或者结束的状态;\nanimation: myfirst 5s linear 2s infinite alternate;\n附：\n盒子动画结束后，停在结束位置：  animation-fill-mode  ：   forwards\n想要动画走回来 ，而不是直接跳回来：animation-direction   ：  alternate\n暂停动画：animation-play-state:   puased;   窗体给弄乱了，怎么办\n\n### 4、总结\n\n属性	      描述\n@keyframes	规定动画。\nanimation	所有动画属性的简写属性，除了animation-play-state属性。\nanimation-name	规定@keyframes动画的名称。\nanimation-duration	规定动画完成一个周期所花费的秒或毫秒，默认是0。\nanimation-timing-function	规定动画的速度曲线，默认是“ease”。\nanimation-delay	规定动画何时开始，默认是0。\nanimation-iteration-count	规定动画被播放的次数，默认是1，还有infinite\nanimation-direction	规定动画是否在下一周期逆向播放，默认是“normal“,alternate逆播放\nanimation-play-state	规定动画是否正在运行或暂停。默认是\"running\",还有\"pause\"。\nanimation-fill-mode	规定动画结束后状态，保持forwards回到起始backwards\n\n## 三、3D 转换\n\n### 1、3D移动 translate3d\n\ntransform:translate3d(x,y,z)：其中 x、y、z 分别指要移动的轴的方向的距离\ntranslform:translateX(100px)：仅仅是在x轴上移动\ntranslform:translateY(100px)：仅仅是在Y轴上移动\ntranslform:translateZ(100px)：仅仅是在Z轴上移动（注意：translateZ只能跟px单位）\n透视 perspective指定透视距离，有了透视，就能看到translateZ 引起的变化\n\n### 2、3D旋转 rotate3d\n\n语法：\ntransform:rotateX(45deg)：沿着x轴正方向旋转 45度\ntransform:rotateY(45deg) ：沿着y轴正方向旋转 45deg\ntransform:rotateZ(45deg) ：沿着Z轴正方向旋转 45deg\ntransform:rotate3d(x,y,z,deg)： 沿着自定义轴旋转 deg为角度（了解即可）\n\n### 3、3D呈现 transfrom-style\n\n控制子元素是否开启三维立体环境。\n给父亲添加影响的是子盒子。\nTransform-style: preserve-3d; 子元素开启立体空间，默认的值是 flat 不开启\n', '', 0, 1, '2022-02-27 19:49:43', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (4, 'JavaScript 学习笔记', 'JavaScript 学习笔记', '', '', 0, 1, '2022-03-08 19:16:53', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (5, 'git 和 github', 'Windows 安装 Git 及配置信息，Git 操作包括获取仓库方式、常用命令、创建推送远程分支相关内容。', '# Git基础\n\n## 1. 安装并配置Git\n\n### 1.1 windows下载并安装Git\n\n- 下载地址：https://git-scm.com/downloads，安装过程中全点next\n- 安装成功之后鼠标右键，存在如图所示，则安装Git成功\n\n### 1.2 配置用户信息\n\n- 配置用户名和邮箱，鼠标右键点击Git Base Here，分别输入：\n\n  ```\n  git config --global user.name \"零尽头\"\n  git config --global user.email \"mushuai66@qq.com\"\n  ```\n- 通过 git config --global user.name 和 git config --global user.email 配置的用户名和邮箱地址，会被写\n\n  入到 C:/Users/用户名文件夹/.gitconfig 文件中。这个文件是 Git 的**全局配置文件**，**配置一次即可永久生效**。\n- 运行终端命令查看Git配置信息\n\n  ```\n  # 查看所有配置项\n  git config --list --global\n  # 查看指定全局配置项\n  git config user.name\n  git config user.email\n  ```\n\n### 1.3 Git操作\n\n获取 Git 仓库的两种方式\n\n- 将尚未进行版本控制的本地目录**转换**为 Git 仓库\n- 从其它服务器**克隆**一个已存在的 Git 仓库\n\n#### 1.3.1 常用命令\n\n```\ngit init\ngit add .\ngit commit -m \"...\"\ngit status\n# 新建分支\ngit checkout -b XXX(分支名称)\n# 查看分支\ngit branch\n# 切换分支\ngit checkout XXX(分支名称)\n# 合并分支\ngit merge xxx(需要合并的分支)\n# 在云端仓库新建分支\ngit push -u origin xxx(分支名称)\n# 拉取远程分支（自动合并）\ngit pull origin dev\n// 获取远程指定分支到本地临时新建的分支（不自动合并）\ngit fetch origin master:temp\n# 上传指定分支\ngit push origin xxx(分支名称)\n# 删除远程指定分支\ngit push origin :xxx(分支名称)\n# 删除本地指定分支\ngit branch -d xxx(分支名称)\n\n# 推送\ngit push\n# 强制推送\ngit push -f origin master\n```\n\n创建并推送远程分支\nhttps://blog.csdn.net/qq_44760844/article/details/127783772\n', '', 0, 1, '2022-03-15 22:07:00', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (6, 'Ajax', 'Ajax 是网页异步通信及更新的技术及应用。', '# Ajax\n\n## 一、什么是ajax\n\nAjax（Asynchronous JavaScript and XML）即异步的 JavaScript 和 XML。它不是一种新的编程语言，而是一种用于创建快速动态网页的技术。其核心是使用 JavaScript 的`XMLHttpRequest`对象（在现代浏览器中也可以使用`fetch` API，它在一定程度上是`XMLHttpRequest`的替代方案）来与服务器进行异步通信。这意味着可以在不重新加载整个网页的情况下，更新网页的部分内容。\n\n例如，在一个网页应用中，当用户填写表单并提交时，传统的方式是整个页面刷新，然后服务器返回新的页面。而使用 Ajax，用户提交表单后，页面可以在后台向服务器发送请求，获取数据并更新页面上的某些元素，如显示一个新的消息提示或者更新一个列表，而页面的其他部分保持不变，这样可以提供更流畅的用户体验。\n\n## 二、Ajax的基本工作流程\n\n1、创建`XMLHttpRequest`对象（或使用`fetch`）\n\n\n在大多数现代浏览器中，可以这样创建`XMLHttpRequest`对象：\n\n```\nvar xhr = new XMLHttpRequest();\n```\n\n`fetch`的基本用法如下：\n\n```\nfetch(\'url\') .then(response => response.json()) .then(data => {     // 处理返回的数据  });\n```\n\n2、打开一个请求\n\n对于`XMLHttpRequest`，需要指定请求的类型（如`GET`、`POST`等）和请求的 URL。例如：\n\n```\nxhr.open(\'GET\', \'example.com/api/data\', true);\n```\n\n这里`true`表示异步请求。如果是`false`，则请求是同步的，会阻塞浏览器的其他操作，一般不推荐使用同步请求，因为它会让页面看起来像是 “卡住” 了，直到请求完成。\n\n3、发送请求\n\n对于`XMLHttpRequest`，使用`send`方法发送请求。如果是`GET`请求，通常可以不传参数或者传`null`。例如：\n\n```\nxhr.send(null);\n```\n\n对于`POST`请求，可能需要设置请求头并发送数据。例如，如果要发送 JSON 数据：\n\n```\nxhr.open(\'POST\', \'example.com/api/submit\', true); xhr.setRequestHeader(\'Content - type\', \'application/json\'); var data = { name: \'John\', age: 30 }; xhr.send(JSON.stringify(data));\n```\n\n4、处理服务器响应\n\n对于`XMLHttpRequest`，可以通过`onreadystatechange`事件来监听请求状态的变化。当`readyState`的值为 4（表示请求已完成）并且`status`的值在 200 - 299 之间（表示成功）时，可以处理服务器返回的数据。例如：\n\n```\nxhr.onreadystatechange = function() {     if (xhr.readyState === 4 && xhr.status >= 200 && xhr.status < 300) {         var responseData = JSON.parse(xhr.responseText);         // 在这里处理返回的数据，如更新页面元素     } };\n```\n\n对于`fetch`，可以使用`.then`方法来处理响应，如前面所示，先将响应解析为 JSON 格式，然后处理数据。\n\n## 三、Ajax 的应用场景\n\n1. 表单提交\n   * 当用户提交表单时，如注册、登录、评论等表单，可以使用 Ajax 将表单数据发送到服务器，服务器返回验证结果或者其他信息，然后在页面上相应的位置显示这些信息，而不用刷新整个页面。\n2. 数据加载\n   * 加载动态内容，如新闻列表、产品目录等。当用户滚动页面时，可以通过 Ajax 请求加载更多的数据，而不是一次性加载所有的数据，这样可以提高页面的初始加载速度。\n3. 实时更新\n   * 像实时聊天应用、股票价格更新等场景，通过 Ajax 定期向服务器发送请求获取最新的数据，然后实时更新页面上显示的内容。\n\n', '', 0, 1, '2022-03-18 22:17:50', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (7, 'node.js 基础', 'Node.js 是基于 V8 的运行环境，解决 I/O 阻塞等问题，可构建服务器和工具。', '# Node.js\n\n## 一、Node.js 是什么？\n\nNode.js 是一个基于 Chrome V8 引擎的 JavaScript 运行环境，它让 JavaScript 能够在服务器端运行，而不仅仅局限于浏览器环境。\n\n从技术架构层面讲，Node.js 采用事件驱动、非阻塞 I/O 模型，这使得它轻量且高效。它就像是一个桥梁，将 JavaScript 的应用范围从前端拓展到了后端开发领域，并且拥有丰富的库和模块，可以帮助开发者快速构建各种类型的网络应用。\n\n## 二、Node.js 解决的问题\n\n### （一）I/O 阻塞问题\n\n* 在传统的服务器端编程语言（如 Python 中的同步 I/O 模型）中，当程序发起一个 I/O 操作（如读取文件或者向数据库发起查询）时，程序会一直等待这个操作完成后才继续执行下一个任务。这就像一个餐厅服务员，每次只能服务一桌客人，等这桌客人点完菜、吃完离开后，才能服务下一桌客人。如果这个 I/O 操作比较耗时（比如读取一个大文件），整个程序的性能就会受到很大影响。\n* Node.js 的非阻塞 I/O 模型则不同。当发起一个 I/O 操作后，Node.js 不会等待这个操作完成，而是继续执行其他任务。当 I/O 操作完成时，它会通过事件回调的方式来通知程序。这就好比餐厅服务员在给一桌客人下单后，不用一直等厨房做菜，而是可以先去服务其他桌客人，等菜做好了，厨房会通知服务员上菜。这种方式使得 Node.js 能够高效地处理大量并发的 I/O 操作，特别适用于处理高并发的网络请求，如 Web 服务器、实时聊天应用等。\n\n### （二）前后端语言统一问题\n\n* 在没有 Node.js 之前，前端使用 JavaScript，后端通常使用其他语言（如 Python、Java、Ruby 等）。这就导致开发团队需要掌握多种语言，并且在前后端交互时可能会遇到数据格式转换、沟通成本等问题。\n* Node.js 允许开发者使用 JavaScript 进行前后端开发，实现了语言的统一。开发者可以使用相同的语言、相似的编程模式和工具链来构建完整的 Web 应用。例如，在一个全栈 JavaScript 应用中，前端使用 React 或者 Vue.js 等框架构建用户界面，后端使用 Node.js 和 Express 框架来构建 API 接口，两者之间的数据交互更加自然流畅，减少了语言转换带来的成本。\n\n## 三、Node.js 简单应用\n\n### （一）构建一个简单的 Web 服务器\n\n1. **安装 Node.js**\n   * 首先，需要在你的计算机上安装 Node.js。可以从 Node.js 官方网站（[https://nodejs.org/](https://nodejs.org/)）下载适合你操作系统的安装包，然后按照安装向导进行安装。\n2. **创建服务器文件**\n   * 新建一个文件，比如命名为`server.js`。在这个文件中，我们使用 Node.js 内置的`http`模块来创建一个简单的 Web 服务器。\n   * 以下是示例代码：\n\n```javascript\n// 引入http模块\nconst http = require(\'http\');\n// 创建一个服务器\nconst server = http.createServer((req, res) => {\n    // 设置响应头，告诉浏览器返回的是HTML内容\n    res.writeHead(200, {\'Content - Type\': \'text/html\'});\n    // 向客户端发送响应内容\n    res.write(\'<html><body><h1>Hello, World!</h1></body></html>\');\n    // 结束响应\n    res.end();\n});\n// 监听端口3000\nserver.listen(3000, () => {\n    console.log(\'Server is running on port 3000\');\n});\n```\n\n* 在上述代码中：\n  * 首先通过`require(\'http\')`引入了`http`模块。这个模块提供了创建 HTTP 服务器和客户端的功能。\n  * 然后使用`http.createServer()`方法创建了一个服务器。这个方法接受一个回调函数，该回调函数在每次有客户端请求时被调用。回调函数有两个参数：`req`（代表请求对象）和`res`（代表响应对象）。\n  * 在回调函数内部，通过`res.writeHead()`设置响应头，这里设置状态码为`200`（表示成功），并且指定内容类型为`text/html`。然后使用`res.write()`向客户端发送一个简单的 HTML 内容。最后使用`res.end()`结束响应。\n  * 最后，通过`server.listen()`方法让服务器监听本地的`3000`端口。当服务器成功启动后，会在控制台打印`Server is running on port 3000`。\n\n3. **运行服务器**\n   * 在命令行中，进入`server.js`所在的目录，然后执行`node server.js`命令。此时，在浏览器中访问`http://localhost:3000`，就可以看到页面显示`Hello, World!`。\n\n### （二）构建命令行工具\n\n1. **创建命令行工具文件**\n   * 新建一个文件，比如`cli.js`。假设我们要创建一个简单的命令行工具，用于统计一个文本文件中的单词数量。\n   * 示例代码如下：\n\n```javascript\n// 引入fs模块，用于文件系统操作\nconst fs = require(\'fs\');\n// 从命令行参数获取文件名\nconst filename = process.argv[2];\nif (!filename) {\n    console.log(\'请指定一个文件名\');\n    process.exit(1);\n}\n// 读取文件内容\nfs.readFile(filename, \'utf8\', (err, data) => {\n    if (err) {\n        console.error(\'读取文件出错:\', err);\n        process.exit(1);\n    }\n    const words = data.split(\' \').length;\n    console.log(`文件 ${filename} 中的单词数量为: ${words}`);\n});\n```\n\n* 在这个代码中：\n  * 首先通过`require(\'fs\')`引入了`fs`模块，用于文件系统操作，如读取文件。\n  * 然后通过`process.argv[2]`获取命令行参数中的文件名。`process.argv`是一个数组，其中`process.argv[0]`是 Node.js 的执行文件路径，`process.argv[1]`是被执行的脚本文件路径，`process.argv[2]`及以后是命令行传递的参数。\n  * 如果没有指定文件名，会在控制台打印提示信息并退出程序（`process.exit(1)`表示以错误码`1`退出）。\n  * 使用`fs.readFile()`方法读取文件内容。这个方法接受文件名、编码格式（这里是`utf8`）和一个回调函数。如果读取文件出错，会在控制台打印错误信息并退出程序；如果读取成功，会将文件内容按照空格分割成单词数组，然后统计单词数量并打印出来。\n\n2. **运行命令行工具**\n   * 在命令行中，进入`cli.js`所在的目录，然后执行`node cli.js [文件名]`，其中`[文件名]`是你要统计单词数量的文本文件的名称。例如，`node cli.js test.txt`就可以统计`test.txt`文件中的单词数量。\n', '', 0, 1, '2022-03-30 21:45:57', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (8, 'npm', 'npm 是 Node.js 包管理工具，管理依赖、版本，可安装和卸载包。', '# npm\n\n## 一、npm 简介\n\n* npm（Node Package Manager）是 Node.js 的包管理工具。它就像是一个应用商店，里面包含了海量的 JavaScript 软件包，这些软件包可以帮助开发者快速构建各种应用。这些软件包可以是一个小型的工具函数库，也可以是一个完整的 Web 框架，如 Express、React 等。\n\n## 二、npm 解决的问题\n\n### （一）依赖管理问题\n\n* 在开发一个大型项目时，往往会用到许多不同的库和模块。如果没有包管理工具，开发者需要手动下载和管理这些依赖，这会非常繁琐且容易出错。例如，当项目需要使用多个库，每个库又依赖于其他库时，手动下载可能会导致版本冲突或者遗漏某些依赖。\n* npm 通过维护一个`package.json`文件来解决这个问题。这个文件记录了项目所依赖的所有包及其版本号。当在一个新的环境中部署项目时，只需运行`npm install`命令，npm 就会根据`package.json`自动下载并安装所有需要的依赖包，确保项目的依赖环境正确搭建。\n\n### （二）版本控制问题\n\n* 不同的项目可能需要使用同一个库的不同版本。例如，项目 A 需要使用`lodash`库的版本 3，而项目 B 需要使用版本 4。手动管理这些版本很容易混淆。\n* npm 允许在`package.json`中精确指定每个依赖包的版本范围。可以使用语义化版本号（如`^1.0.0`表示兼容 1.0.0 版本的最新版）来控制依赖包的更新，这样既可以保证项目的稳定性，又可以方便地更新依赖包到合适的版本。\n\n## 三、npm 简单使用\n\n### （一）安装包\n\n1. **全局安装**\n   * 有些工具包需要在全局环境下安装，这样在任何目录下都可以使用。例如，`npm install -g create - react - app`，这个命令会将`create - react - app`这个工具安装到全局环境中。`-g`参数表示全局安装。安装完成后，可以使用`create - react - app`命令来快速创建 React 应用。\n2. **本地安装**\n   * 对于项目依赖的包，通常是本地安装。首先，在项目目录下创建一个`package.json`文件（如果没有的话），可以通过`npm init`命令来创建，这个命令会引导你输入项目的基本信息，如名称、版本、作者等，然后生成`package.json`文件。\n   * 假设要在项目中安装`express`框架，在项目目录下执行`npm install express`命令。npm 会自动下载`express`包及其所有依赖，并将它们安装到项目的`node_modules`目录下。同时，会在`package.json`文件的`dependencies`（生产环境依赖）部分添加`express`及其版本号信息。\n\n### （二）管理依赖包版本\n\n1. **在 package.json 中指定版本号**\n   * 在`package.json`文件中，依赖包的版本号可以使用精确版本（如`\"express\": \"4.18.2\"`），这种方式会固定安装指定版本的包。也可以使用语义化版本范围，例如`\"lodash\": \"^4.17.21\"`，其中`^`表示安装兼容 4.17.21 版本的最新版本，主要版本号（4）不变，次要版本号和补丁版本号可以更新。\n2. **更新依赖包**\n   * 当需要更新项目的依赖包时，可以执行`npm update`命令。这个命令会根据`package.json`中指定的版本范围，更新所有可以更新的依赖包。如果只想更新某个特定的包，可以使用`npm update [package - name]`命令，例如`npm update lodash`。\n\n### （三）卸载包\n\n* 如果想要从项目中卸载一个包，可以在项目目录下执行`npm uninstall [package - name]`命令。例如，`npm uninstall express`会从项目的`node_modules`目录中删除`express`包及其相关文件，并且会从`package.json`文件的`dependencies`部分移除对应的记录。\n', '', 0, 1, '2022-04-03 19:09:34', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (9, 'express', 'Express 是 Node.js 的 Web 框架，简化路由，有中间件，简单易用。', '# express\n\n## 一、Express 框架是什么？\n\nExpress 是一个基于 Node.js 的简洁、灵活的 Web 应用框架。它是一个中间件框架，为构建 Web 应用程序和 API 提供了一套简洁的工具和方法。在 Node.js 的生态系统中，Express 处于核心地位，用于快速开发服务器端应用。\n\n从架构上看，Express 构建在 Node.js 的 HTTP 模块之上，对原生的 HTTP 请求和响应对象进行了封装，简化了开发流程，并且通过中间件机制，能够方便地实现如路由处理、请求过滤、错误处理等功能。\n\n## 二、Express 解决的问题\n\n### （一）简化路由处理\n\n* 在 Node.js 原生的 HTTP 模块中，手动处理路由是比较复杂的。需要解析请求的 URL 路径，根据不同的路径来执行不同的操作。例如，要区分对`/user`路径和`/product`路径的请求，并返回不同的数据，就需要编写大量的条件判断语句。\n* Express 提供了简洁的路由机制。通过`app.get()`、`app.post()`等方法，可以很容易地定义不同 HTTP 方法（如 GET、POST 等）对应的路由。例如：\n\n```javascript\nconst express = require(\'express\');\nconst app = express();\n\n// 定义一个GET请求的路由\napp.get(\'/user\', (req, res) => {\n    res.send(\'这是用户相关的信息\');\n});\n```\n\n在这个例子中，当客户端发起一个对`/user`路径的 GET 请求时，服务器就会返回`这是用户相关的信息`。\n\n### （二）中间件机制便于功能扩展\n\n* 在开发 Web 应用时，往往需要在请求处理过程中添加多种功能，如日志记录、权限验证、数据格式化等。如果没有 Express 这样的框架，需要在每个请求处理函数中添加这些功能的代码，导致代码冗余且难以维护。\n* Express 的中间件机制允许将这些功能封装成独立的中间件。中间件是一个函数，它可以访问请求对象（`req`）、响应对象（`res`）和下一个中间件函数。例如，以下是一个简单的日志记录中间件：\n\n```javascript\nconst express = require(\'express\');\nconst app = express();\n\n// 日志记录中间件\nconst logger = (req, res, next) => {\n    console.log(`收到请求：${req.method} ${req.url}`);\n    next();\n};\napp.use(logger);\n```\n\n在这个例子中，`app.use(logger)`将`logger`中间件添加到应用中。当有请求到来时，会先执行`logger`中间件，记录请求信息，然后再执行后续的路由处理中间件或请求处理函数。\n\n## 三、Express 简单使用\n\n### （一）创建一个基本的 Express 应用\n\n1. **安装 Express**\n   * 首先确保已经安装了 Node.js，然后在项目目录下通过命令`npm install express`安装 Express 框架。\n2. **创建服务器文件**\n   * 新建一个文件，例如`server.js`。在文件中引入 Express 并创建一个服务器：\n\n```javascript\nconst express = require(\'express\');\nconst app = express();\nconst port = 3000;\n\n// 定义一个根路由\napp.get(\'/\', (req, res) => {\n    res.send(\'欢迎来到Express服务器\');\n});\n\napp.listen(port, () => {\n    console.log(`服务器在端口 ${port} 运行`);\n});\n```\n\n* 在这个代码中：\n  * 首先通过`require(\'express\')`引入 Express 框架，然后使用`express()`函数创建一个应用实例`app`。\n  * 定义了一个端口号`port`为`3000`。\n  * 通过`app.get(\'/\', (req, res) => {...})`定义了一个根路由（`/`）。当客户端访问根路径时，服务器会返回`欢迎来到Express服务器`。\n  * 最后使用`app.listen(port, () => {...})`让服务器在指定端口监听请求。当服务器启动成功后，会在控制台打印`服务器在端口3000运行`。\n\n3. **启动服务器并访问应用**\n   * 在命令行中，进入`server.js`所在的目录，然后执行`node server.js`命令来启动服务器。在浏览器中访问`http://localhost:3000`，就可以看到页面显示`欢迎来到Express服务器`。\n\n### （二）使用 Express 处理 POST 请求和接收数据\n\n1. **处理 POST 请求**\n   * 首先，需要引入`body - parser`中间件来处理 POST 请求的数据。`body - parser`中间件可以解析多种格式的数据，如 JSON、URL - encoded 等。安装`body - parser`中间件可以通过`npm install body - parser`命令。\n   * 在`server.js`文件中添加以下代码：\n\n```javascript\nconst express = require(\'express\');\nconst bodyParser = require(\'body - parser\');\nconst app = express();\nconst port = 3000;\n\n// 使用body - parser中间件来解析JSON数据\napp.use(bodyParser.json());\n\n// 定义一个POST请求的路由\napp.post(\'/addUser\', (req, res) => {\n    const user = req.body;\n    console.log(\'收到用户数据：\', user);\n    res.send(\'用户数据已接收\');\n});\n\napp.listen(port, () => {\n    console.log(`服务器在端口 ${port} 运行`);\n});\n```\n\n* 在这个代码中：\n  * 引入`body - parser`中间件并通过`app.use(bodyParser.json())`来使用它解析 JSON 格式的数据。\n  * 定义了一个`/addUser`路径的 POST 请求路由。当客户端发送一个包含用户数据的 POST 请求（数据格式为 JSON）到`/addUser`路径时，服务器会通过`req.body`获取用户数据，打印出来，然后返回`用户数据已接收`。\n\n2. **使用工具发送 POST 请求并测试**\n   * 可以使用工具如 Postman 来发送 POST 请求。在 Postman 中，设置请求方法为 POST，URL 为`http://localhost:3000/addUser`，在请求体（Body）中选择 JSON 格式，并填写用户数据，如`{\"name\": \"张三\", \"age\": 20}`。发送请求后，在服务器控制台可以看到打印的用户数据，并且在 Postman 中可以收到服务器返回的`用户数据已接收`消息。\n', '', 0, 1, '2022-04-05 22:10:02', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (10, 'mysql', 'MySQL 是开源数据库，解决数据存储等问题，SQL 用于操作，有多种查询。', '# mysql\n\n## 一、MySQL 是什么？\n\nMySQL 是一个开源的关系型数据库管理系统（RDBMS）。它使用结构化查询语言（SQL）来管理和操作数据。在数据库体系结构中，MySQL 由服务器程序和多个客户端程序组成，服务器负责存储和管理数据，客户端可以通过网络连接到服务器进行数据的交互。\n\n从数据存储角度看，MySQL 将数据存储在表中，表由行（记录）和列（字段）组成，这种结构使得数据组织有序、易于理解和维护。它能够高效地处理大量的数据，并提供了多种数据类型来满足不同的业务需求，如整数、小数、字符串、日期等。\n\n## 二、MySQL 解决的问题\n\n### （一）数据持久化和集中管理问题\n\n* 在应用程序开发中，如果没有数据库，数据可能会临时存储在内存或者本地文件中。内存存储的数据在程序结束或者服务器重启后会丢失，而本地文件存储在处理复杂的查询、多用户访问和数据一致性维护等方面存在困难。\n* MySQL 提供了一个稳定的数据持久化存储方案。可以将应用程序产生的各种数据，如用户信息、订单数据、文章内容等，以结构化的方式存储在数据库表中。并且可以通过权限管理来控制不同用户对数据的访问和操作，实现数据的集中管理。\n\n### （二）数据关联和复杂查询问题\n\n* 当应用程序的数据量增大且数据之间存在复杂的关联关系时，如一个电商应用中用户表、订单表、商品表之间的关系，如果只是简单地使用文件存储，很难高效地处理这些关联数据。\n* MySQL 的关系型模型允许通过定义表之间的关系（如一对一、一对多、多对多），使用 SQL 语句进行多表联查，轻松地获取相关联的数据。例如，可以查询某个用户的所有订单信息以及订单中的商品详情。\n\n## 三、MySQL 简单使用\n\n### （一）安装和配置\n\n* **安装**：可以从 MySQL 官方网站（[https://dev.mysql.com/downloads/mysql/](https://dev.mysql.com/downloads/mysql/)）下载适合你操作系统的安装包进行安装。在安装过程中，需要设置一些基本参数，如 root 用户的密码等。\n* **配置**：安装完成后，可以通过修改配置文件（如`my.cnf`或`my.ini`）来配置 MySQL 的参数，如端口号、字符集、缓存大小等，以满足特定的应用场景需求。\n\n### （二）连接到 MySQL 数据库\n\n* 在大多数编程语言中，都有相应的 MySQL 驱动来实现与数据库的连接。以 Python 为例，需要先安装`pymysql`库（`pip install pymysql`）。以下是一个简单的连接示例：\n\n```python\nimport pymysql\n\n# 连接数据库\nconn = pymysql.connect(\n    host=\'localhost\',\n    user=\'root\',\n    password=\'your_password\',\n    database=\'your_database_name\'\n)\n```\n\n在这个示例中，通过`pymysql.connect`函数建立与本地 MySQL 服务器（`host=\'localhost\'`）的连接，使用`root`用户登录，密码为`your_password`，并指定要连接的数据库为`your_database_name`。\n\n## 四、SQL 语句\n\n### （一）基本概念\n\n* SQL（Structured Query Language）即结构化查询语言，是用于管理关系型数据库的标准语言。它包括数据定义语言（DDL）、数据操作语言（DML）、数据控制语言（DCL）等部分。\n\n### （二）增删改查操作\n\n#### 1. 插入数据（INSERT）\n\n* 语法：`INSERT INTO table_name (column1, column2,...) VALUES (value1, value2,...);`\n* 例如，向一个名为`students`的表中插入一条学生记录：\n\n```sql\nINSERT INTO students (name, age, gender) VALUES (\'张三\', 20, \'男\');\n```\n\n这个语句将在`students`表中插入一条包含姓名为`张三`、年龄为`20`、性别为`男`的学生记录。\n\n#### 2. 删除数据（DELETE）\n\n* 语法：`DELETE FROM table_name WHERE condition;`\n* 例如，删除`students`表中年龄小于`18`的学生记录：\n\n```sql\nDELETE FROM students WHERE age < 18;\n```\n\n#### 3. 修改数据（UPDATE）\n\n* 语法：`UPDATE table_name SET column1 = value1, column2 = value2,... WHERE condition;`\n* 例如，将`students`表中姓名为`张三`的学生年龄修改为`21`：\n\n```sql\nUPDATE students SET age = 21 WHERE name = \'张三\';\n```\n\n#### 4. 查询数据（SELECT）\n\n* 语法：`SELECT column1, column2,... FROM table_name WHERE condition;`\n* 例如，查询`students`表中所有女生的姓名和年龄：\n\n```sql\nSELECT name, age FROM students WHERE gender = \'女\';\n```\n\n### （三）多表联查操作\n\n#### 1. 内连接（INNER JOIN）\n\n* 内连接返回两个表中满足连接条件的行。语法：`SELECT * FROM table1 INNER JOIN table2 ON table1.column = table2.column;`\n* 假设存在`orders`表（包含订单信息，有`user_id`字段关联用户）和`users`表（包含用户信息），查询所有用户的订单信息：\n\n```sql\nSELECT * FROM orders INNER JOIN users ON orders.user_id = users.id;\n```\n\n#### 2. 左连接（LEFT JOIN）\n\n* 左连接返回左表中的所有行以及右表中满足连接条件的行。如果右表中没有匹配的行，则用`NULL`填充。语法：`SELECT * FROM table1 LEFT JOIN table2 ON table1.column = table2.column;`\n* 例如，查询所有用户及其订单信息，即使某个用户没有订单也显示该用户信息：\n\n```sql\nSELECT * FROM users LEFT JOIN orders ON users.id = orders.user_id;\n```\n\n#### 3. 右连接（RIGHT JOIN）\n\n* 右连接与左连接类似，只是返回右表中的所有行以及左表中满足连接条件的行。语法：`SELECT * FROM table1 RIGHT JOIN table2 ON table1.column = table2.column;`\n* 实际应用场景与左连接相对应，取决于以哪个表为主来获取关联数据。\n', '', 0, 1, '2022-04-15 22:11:13', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (11, '身份认证', '身份认证验证用户身份，JWT Token 有优有劣，认证方式多样。', '# 身份认证\n\n## 一、身份认证是什么？\n\n在软件开发中，身份认证是验证用户身份的过程。它就像是一个守门人，用于确认试图访问系统资源（如应用程序、数据库、API 等）的用户是否是其声称的身份。通过检查用户提供的凭据（如用户名和密码、数字证书等）与系统中存储的合法用户信息进行对比来实现。\n\n## 二、为什么要使用身份认证？\n\n### （一）保护数据安全\n\n* 软件系统通常包含敏感信息，如用户的个人资料、财务数据、商业机密等。未经授权的用户访问这些数据可能会导致数据泄露、篡改等安全问题。身份认证能够确保只有经过授权的合法用户才能访问相应的数据，从而为数据安全提供了基本保障。\n\n### （二）合规性要求\n\n* 许多行业和法规要求软件系统必须具备有效的身份认证机制。例如，金融行业需要遵守严格的安全标准，如 PCI - DSS（支付卡行业数据安全标准），医疗行业需要遵守 HIPAA（健康保险可移植性和责任法案）等。实施身份认证有助于软件系统满足这些合规性要求。\n\n### （三）用户权限管理\n\n* 不同的用户在软件系统中可能具有不同的权限。身份认证是实现用户权限管理的前提。通过身份认证，可以根据用户的角色和权限来控制其对系统资源的访问范围，确保用户只能执行其权限范围内的操作。\n\n## 三、身份认证的方式\n\n### （一）基于用户名和密码\n\n* 这是最常见的身份认证方式。用户在注册时设置用户名和密码，登录时提供这些凭据。系统会将用户输入的密码与存储在数据库中的密码哈希值（为了安全，密码通常不会以明文形式存储）进行比对。如果匹配，则认证成功。\n\n### （二）多因素认证（MFA）\n\n* 除了用户名和密码外，还需要其他因素来验证身份。例如，短信验证码（用户输入用户名和密码后，系统发送短信验证码到用户手机，用户需要输入验证码才能登录）、硬件令牌（如 U 盾，用户需要插入硬件设备并输入密码等信息）、生物识别技术（指纹识别、面部识别等）。多因素认证大大提高了身份认证的安全性。\n\n### （三）基于证书的认证\n\n* 用户通过数字证书来证明自己的身份。数字证书是由权威的证书颁发机构（CA）颁发的，包含用户的公钥、身份信息等内容。系统通过验证证书的有效性和真实性来认证用户身份。这种方式常用于企业级的安全通信和网络访问。\n\n## 四、JWT（JSON Web Token）的 Token 是什么？\n\nJWT 是一种开放标准（RFC 7519），用于在各方之间安全地传输信息。JWT 的 Token 是一个字符串，它包含了三部分：头部（Header）、载荷（Payload）和签名（Signature）。\n\n* **头部（Header）**：主要包含令牌的类型（通常是 JWT）和所使用的签名算法（如 HMAC SHA256、RSA 等）。这部分是一个经过 Base64 编码的 JSON 对象。\n* **载荷（Payload）**：包含了用户的一些信息，如用户 ID、角色、过期时间等。这部分也是一个经过 Base64 编码的 JSON 对象。载荷中的信息可以根据具体需求自定义，但应该避免包含敏感信息，因为这部分信息可以被解码查看。\n* **签名（Signature）**：是通过头部和载荷以及一个密钥（只有服务器知道），使用指定的签名算法生成的。签名用于验证消息在传输过程中没有被篡改。\n\n## 五、JWT Token 的优势\n\n### （一）无状态性\n\n* 在传统的基于会话（Session）的身份认证中，服务器需要存储会话信息来跟踪用户状态。而 JWT 是无状态的，服务器不需要存储关于用户的会话状态。这使得服务器更容易进行水平扩展，因为不需要在多个服务器之间同步会话状态。\n\n### （二）跨平台和跨语言\n\n* JWT 是一种基于 JSON 的标准，它可以很容易地在不同的平台和编程语言之间传递和解析。无论是 Web 应用、移动应用还是后端服务之间的通信，都可以使用 JWT 进行身份认证。\n\n### （三）自包含性\n\n* JWT Token 本身包含了用户的相关信息，使得在分布式系统中，不同的服务可以通过解析 Token 来获取用户信息，而不需要频繁地查询数据库或其他存储介质来获取用户身份相关的数据。\n\n## 六、JWT Token 的劣势\n\n### （一）数据泄露风险\n\n* 虽然 JWT 的签名可以防止数据篡改，但如果 Token 被窃取（例如，通过网络嗅探、XSS 攻击等），攻击者可以解码 Token 并获取其中包含的用户信息。因此，在使用 JWT 时，需要采取适当的安全措施来保护 Token，如使用安全的传输协议（HTTPS）。\n\n### （二）无法即时撤销\n\n* 一旦 JWT Token 被发放，很难即时撤销。如果用户的权限发生变化或者 Token 被盗用，在 Token 过期之前，很难阻止其继续被使用。虽然可以通过设置较短的过期时间来降低风险，但这又会增加用户频繁登录的不便。\n', '', 0, 1, '2022-04-18 19:34:45', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (12, 'vue 基础', 'Vue 是构建用户界面的 JavaScript 框架。基础知识包括实例、模板语法、组件、生命周期、路由等内容。', '**一、Vue 是什么**\n\nVue.js（通常简称为 Vue）是一个用于构建用户界面的渐进式 JavaScript 框架。它的核心库只关注视图层，易于上手，并且可以与其他库或现有项目进行整合。Vue 采用了组件化的开发思想，能够高效地创建单页应用（SPA）和复杂的前端界面。\n\n* **特点**\n  * **响应式原理**：Vue 能够自动追踪数据的变化，当数据发生改变时，与之绑定的 DOM（文档对象模型）会自动更新，而无需手动操作 DOM。例如，当一个 Vue 实例中的`data`属性中的变量值改变，与之关联的 HTML 模板中的文本或者样式等会自动更新。\n  * **组件化**：可以将一个大型的应用拆分成许多小的、独立的、可复用的组件。每个组件都有自己的模板、逻辑和样式。就像搭建积木一样，通过组合不同的组件来构建完整的应用。例如，一个电商网站可以把商品列表、购物车、用户信息等模块分别做成组件。\n  * **指令系统**：Vue 提供了一系列指令，用于在 HTML 模板中方便地进行数据绑定、事件处理等操作。如`v - bind`用于绑定属性，`v - model`用于实现表单元素和数据的双向绑定，`v - if`和`v - show`用于条件渲染等。\n\n**二、Vue 基础知识包含以下几个主要部分**\n\n1. **安装与引入**\n   * **直接引入 CDN**：可以通过在 HTML 文件中添加`<script>`标签引入 Vue。例如，在`<head>`标签中添加如下代码来引入开发版本的 Vue：\n\n```html\n<script src=\"https://cdn.jsdelivr.net/npm/vue@2.6.14/dist/vue.js\"></script>\n```\n\n* **使用 npm 安装（适用于构建大型项目）**：如果要使用 Vue 构建比较复杂的项目，特别是配合 Webpack 等打包工具时，首先要在项目目录下通过命令行运行`npm install vue`进行安装。然后在 JavaScript 文件中通过`import Vue from \'vue\'`引入 Vue。\n\n2. **Vue 实例**\n   * **创建 Vue 实例**：一个 Vue 应用是通过创建一个 Vue 实例开始的。例如：\n\n```javascript\nvar app = new Vue({\n  el: \'#app\',\n  data: {\n    message: \'Hello, Vue!\'\n  }\n});\n```\n\n* **el 属性**：`el`属性用于指定 Vue 实例挂载的 DOM 元素。在上述例子中，`el: \'#app\'`表示这个 Vue 实例会挂载到 HTML 文件中`id`为`app`的元素上。\n* **data 属性**：`data`属性是一个对象，用于存储应用的数据。在模板中可以通过双花括号`{{ }}`来引用`data`中的数据。例如，在 HTML 模板中可以使用`{{message}}`来显示`data`中的`message`变量的值。\n\n3. **模板语法**\n   * **文本插值**：使用双花括号`{{ }}`进行文本插值。例如，`{{ variableName }}`会将`variableName`的值渲染到 DOM 中。如果`variableName`是一个 JavaScript 表达式，它也会被计算并渲染。如`{{ 1 + 1 }}`会渲染为`2`。\n   * **指令**\n     * **v - bind**：用于绑定 HTML 元素的属性。例如，`v - bind:href=\"url\"`可以将`url`变量的值绑定到元素的`href`属性上。可以简写为`:href=\"url\"`。\n     * **v - model**：主要用于表单元素，实现数据的双向绑定。例如，对于一个输入框`<input v - model=\"inputValue\">`，当用户在输入框中输入内容时，`inputValue`变量的值会自动更新，反之，当`inputValue`在 JavaScript 代码中被修改时，输入框中的内容也会更新。\n     * **v - if 和 v - else - if 和 v - else**：用于条件渲染。`v - if=\"condition\"`会根据`condition`的真假来决定是否渲染该元素。例如：\n\n```html\n<div v - if=\"isShow\">\n  This div will be shown if isShow is true.\n</div>\n<div v - else>\n  This div will be shown if isShow is false.\n</div>\n```\n\n* **v - for**：用于循环渲染列表。例如，`v - for=\"item in items\"`可以遍历`items`数组，并为每个`item`渲染一个 DOM 元素。假设`items`是一个包含字符串的数组`[\'apple\', \'banana\', \'cherry\']`，可以这样使用：\n\n```html\n<ul>\n  <li v - for=\"fruit in items\">{{fruit}}</li>\n</ul>\n```\n\n4. **组件基础**\n   * **定义组件**：可以使用`Vue.component()`方法来定义一个全局组件。例如：\n\n```javascript\nVue.component(\'my - component\', {\n  template: \'<div> This is my component </div>\'\n});\n```\n\n* **组件的使用**：在 HTML 模板中可以像使用 HTML 标签一样使用组件。例如，`<my - component></my - component>`会渲染出组件定义的内容。\n* **组件的通信**\n  * **父子组件通信**：父组件可以通过属性（`props`）向子组件传递数据，子组件可以通过`$emit`事件来向父组件发送消息。例如，父组件有一个数据`parentMessage`，通过`props`传递给子组件：\n\n```javascript\nVue.component(\'child - component\', {\n  props: [\'message\'],\n  template: \'<div>{{message}}</div>\'\n});\nnew Vue({\n  el: \'#app\',\n  data: {\n    parentMessage: \'Hello from parent\'\n  }\n});\n```\n\n在 HTML 模板中可以这样使用：`<child - component :message=\"parentMessage\"></child - component>`。\n\n* **非父子组件通信（事件总线）**：可以创建一个空的 Vue 实例作为事件总线来实现非父子组件之间的通信。例如，定义一个事件总线：\n\n```javascript\nvar eventBus = new Vue();\n```\n\n一个组件可以通过`eventBus.$emit(\'event - name\', data)`发送事件，另一个组件可以通过`eventBus.$on(\'event - name\', function(data) {})`来接收事件并处理数据。\n5. **生命周期钩子**\n\n* Vue 实例在创建到销毁的过程中有一系列的生命周期钩子函数。\n* **created**：在实例创建完成后被调用，此时`data`和`methods`等已经初始化，但是 DOM 还没有挂载。例如，可以在这个钩子中进行数据的初始化或者获取远程数据等操作。\n* **mounted**：在实例挂载到 DOM 后被调用。此时可以访问到 DOM 元素，适合进行 DOM 操作，如获取某个元素的高度、宽度等。\n* **updated**：当数据更新导致 DOM 重新渲染后被调用。可以在这里进行一些基于更新后的 DOM 的操作。\n* **destroyed**：在实例销毁后被调用。可以在这里进行一些清理操作，如清除定时器等。\n\n6. **路由（Vue Router）**\n   * **安装**：对于单页应用来说，路由是很重要的一部分。可以通过`npm install vue - router`来安装 Vue Router。\n   * **基本使用**：首先要定义路由。例如：\n\n```javascript\nimport Vue from \'vue\'\nimport VueRouter from \'vue - router\'\nVue.use(VueRouter);\nconst routes = [\n  { path: \'/\', component: Home },\n  { path: \'/about\', component: About }\n];\nconst router = new VueRouter({\n  routes\n});\nnew Vue({\n  el: \'#app\',\n  router\n});\n```\n\n* 在 HTML 模板中，可以通过`<router - view></router - view>`来显示当前路由对应的组件，通过`<router - link to=\"/about\">About</router - link>`来创建路由链接。这样当用户点击链接时，会导航到对应的组件并显示在`router - view`中。\n', '', 0, 1, '2022-05-01 22:13:43', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (13, 'vue 组件', 'Vue 组件可全局或局部定义，通过标签使用。有父子组件间的数据传递，还有插槽来接收父组件传递的内容。', '# Vue 组件\n\n## 一、组件的定义\n\n1. **全局组件定义**\n   * 使用`Vue.component()`方法来创建全局组件。例如：\n\n```javasc\nVue.component(\'my-component\', {\n  template: \'<div>这是我的组件</div>\'\n});\n```\n\n* 其中，`my - component`是组件的名称，在 HTML 中可以像使用普通 HTML 标签一样使用这个组件，`template`属性定义了组件的模板内容。\n\n2. **局部组件定义**\n   * 在 Vue 实例内部定义组件，这种组件只能在该实例内部使用。例如：\n\n```javascript\nvar app = new Vue({\n  el: \'#app\',\n  components: {\n    \'local - component\': {\n      template: \'<div>这是一个局部组件</div>\'\n    }\n  }\n});\n```\n\n* 这里的`local - component`组件只能在`id`为`app`的元素挂载的 Vue 实例范围内使用。\n\n## 二、组件的使用\n\n* 在 HTML 模板中使用组件，就像使用 HTML 标签一样。对于全局组件，例如`<my - component></my - component>`，对于局部组件，在其所属的 Vue 实例挂载范围内使用，如`<local - component></local - component>`。\n\n## 三、组件的数据传递\n\n1. **父组件向子组件传递数据（Props）**\n   * 父组件通过`props`属性向子组件传递数据。例如，父组件有数据`parentMessage`：\n\n```javascript\nVue.component(\'child - component\', {\n  props: [\'message\'],\n  template: \'<div>{{message}}</div>\'\n});\nnew Vue({\n  el: \'#app\',\n  data: {\n    parentMessage: \'来自父组件的消息\'\n  }\n});\n```\n\n* 在 HTML 模板中，通过`<child - component :message=\"parentMessage\"></child - component>`将`parentMessage`传递给子组件。\n\n2. **子组件向父组件传递数据（\\$emit）**\n   * 子组件通过`$emit`方法触发一个自定义事件来向父组件传递数据。例如，子组件有一个按钮，点击按钮向父组件传递数据：\n\n```javascript\nVue.component(\'child - component\', {\n  template: \'<button @click=\"sendData\">点击发送数据</button>\',\n  methods: {\n    sendData() {\n      this.$emit(\'data - sent\', \'子组件的数据\');\n    }\n  }\n});\nnew Vue({\n  el: \'#app\',\n  components: {\n    \'child - component\': \'child - component\'\n  },\n  methods: {\n    receiveData(data) {\n      console.log(\'收到子组件的数据:\', data);\n    }\n  }\n});\n```\n\n* 在 HTML 模板中使用`<child - component @data - sent=\"receiveData\"></child - component>`来接收子组件传递的数据。\n\n## 四、组件的插槽（Slots）\n\n1. **默认插槽**\n   * 组件可以包含插槽，用于接收父组件传递的内容。例如，定义一个组件：\n\n```javascript\nVue.component(\'slot - component\', {\n  template: \'<div><slot></slot></div>\'\n});\n```\n\n* 父组件使用时可以这样传递内容：`<slot - component>这是传递给插槽的内容</slot - component>`。\n\n2. **具名插槽**\n   * 当组件有多个插槽时，可以使用具名插槽来区分。例如，组件定义：\n\n```javascript\nVue.component(\'named - slot - component\', {\n  template: \'<div><slot name=\"header\"></slot><slot name=\"content\"></slot></div>\'\n});\n```\n\n* 父组件使用：\n\n```html\n<named - slot - component>\n  <template v - slot:header>这是头部内容</template>\n  <template v - slot:content>这是主体内容</template>\n</named - slot - component>\n```\n', '', 0, 1, '2022-05-05 19:35:16', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (14, '前后端交互', '前后端交互指前端与后端的数据通信与协作。方式包括传统表单提交、Ajax 及使用 axios 库等，数据格式常用 JSON，偶尔用 XML。', '# 前后端交互\n\n## 一、概念\n\n前后端交互是指前端（如 Vue 应用）和后端（如服务器端的应用程序）之间的数据通信和协作。前端负责展示数据和接收用户操作，后端负责处理业务逻辑、存储数据等。\n\n## 二、交互方式\n\n### （一）传统的表单提交\n\n1. **HTML 表单**\n   * 前端通过 HTML 的`<form>`标签创建表单，包含`<input>`、`<textarea>`、`<select>`等表单元素。例如：\n\n```html\n<form action=\"/submit\" method=\"post\">\n  <input type=\"text\" name=\"username\">\n  <input type=\"password\" name=\"password\">\n  <input type=\"submit\" value=\"提交\">\n</form>\n```\n\n* 当用户点击提交按钮时，浏览器会将表单数据按照`method`指定的方式（如`POST`或`GET`）发送到`action`指定的后端 URL。\n\n2. **后端处理**\n   * 后端（如使用 Node.js + Express）会接收这些数据并进行处理。例如，在 Express 中：\n\n```javascript\nconst express = require(\'express\');\nconst app = express();\napp.post(\'/submit\', (req, res) => {\n  const username = req.body.username;\n  const password = req.body.password;\n  // 进行数据验证、存储等操作\n  res.send(\'提交成功\');\n});\napp.listen(3000, () => {\n  console.log(\'服务器运行在3000端口\');\n});\n```\n\n* 这里`req.body`用于获取 POST 请求中的表单数据，然后进行相应处理，最后通过`res.send`向前端返回响应。\n\n### （二）Ajax（Asynchronous JavaScript and XML）\n\n1. **基本原理**\n   * Ajax 允许前端在不刷新整个页面的情况下与后端进行数据交互。它使用`XMLHttpRequest`对象（在现代浏览器中也可以使用`fetch` API）。例如，使用`fetch`：\n\n```javascript\n fetch(\'/api/data\', {\n   method: \'GET\'\n })\n.then(response => response.json())\n.then(data => {\n   console.log(data);\n });\n```\n\n* 这段代码向`/api/data`发送一个`GET`请求，然后将响应解析为 JSON 格式并处理数据。\n\n2. **应用场景**\n   * 用于实时更新数据，如在一个新闻列表页面，每隔一段时间自动获取最新新闻；或者在用户输入搜索内容时，实时从后端获取搜索结果。\n\n### （三）使用 axios 库（在 Vue 中常用）\n\n1. **安装和引入**\n   * 在 Vue 项目中，可以通过`npm install axios`安装 axios。然后在需要使用的 JavaScript 文件中引入，如`import axios from \'axios\';`。\n2. **发送请求**\n   * **GET 请求**：\n\n```javascript\naxios.get(\'/api/users\')\n .then(response => {\n    console.log(response.data);\n  });\n```\n\n* 这里向`/api/users`发送`GET`请求，获取用户数据并打印。\n* **POST 请求**：\n\n```javascript\n axios.post(\'/api/login\', {\n   username: \'test\',\n   password: \'123456\'\n })\n.then(response => {\n   console.log(response.data);\n });\n```\n\n* 向`/api/login`发送包含用户登录信息的`POST`请求，后端可以对登录信息进行验证并返回相应结果。\n\n## 三、数据格式\n\n1. **JSON（JavaScript Object Notation）**\n   * JSON 是前后端交互中最常用的数据格式。它是一种轻量级的数据交换格式，易于阅读和编写。例如，一个 JSON 数据可能是：\n\n```json\n{\n  \"name\": \"张三\",\n  \"age\": 20,\n  \"hobbies\": [\"阅读\", \"运动\"]\n}\n```\n\n* 前端发送数据时可以将 JavaScript 对象转换为 JSON 字符串（使用`JSON.stringify()`），后端返回数据时通常也会以 JSON 格式发送，前端再将其解析为 JavaScript 对象（使用`JSON.parse()`）。\n\n2. **XML（eXtensible Markup Language）**\n   * XML 也是一种数据格式，不过现在使用相对较少。它的格式比较复杂，例如：\n\n```xml\n<person>\n  <name>李四</name>\n  <age>22</age>\n  <hobbies>\n    <hobby>绘画</hobby>\n    <hobby>音乐</hobby>\n  </hobbies>\n</person>\n```\n\n* 前端和后端需要专门的 XML 解析器来处理 XML 数据。\n', '', 0, 1, '2022-05-08 21:15:15', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (15, '路由：vue-router', 'Vue - Router 是 Vue.js 官方路由管理器，可配置路由，有动态、嵌套路由及导航守卫，方便构建 SPA 实现页面切换控制。', '# Vue - Router\n\n## 一、概述\n\nVue - Router 是 Vue.js 官方的路由管理器。它和 Vue.js 核心深度集成，让构建单页应用（SPA）中的导航变得简单。通过管理 URL 和对应的组件显示，实现页面间的无缝切换。\n\n## 二、安装与基本配置\n\n1. **安装**\n   * 使用 npm 安装是常见的方式。在项目目录下的命令行中运行`npm install vue - router`。\n2. **基本配置步骤**\n   * 首先，在 JavaScript 文件中引入 Vue - Router。例如：\n\n```javascript\nimport Vue from \'vue\';\nimport VueRouter from \'vue - router\';\nVue.use(VueRouter);\n```\n\n* 然后，定义路由。路由是一个数组，每个路由对象包含`path`（路径）和`component`（组件）属性。例如：\n\n```javascript\nconst routes = [\n  { path: \'/\', component: Home },\n  { path: \'/about\', component: About }\n];\n```\n\n* 这里定义了两个路由，根路径`/`对应`Home`组件，`/about`路径对应`About`组件。\n* 接着，创建路由实例并传递路由配置。例如：\n\n```javascript\nconst router = new VueRouter({\n  routes\n});\n```\n\n* 最后，将路由实例挂载到 Vue 应用。在创建 Vue 实例时添加`router`属性。例如：\n\n```javascript\nnew Vue({\n  el: \'#app\',\n  router\n});\n```\n\n## 三、路由组件的使用\n\n1. **在模板中显示路由组件**\n   * 在 HTML 模板中，使用`<router - view></router - view>`标签来显示当前路由对应的组件。例如，在`App.vue`文件中：\n\n```html\n<template>\n  <div id=\"app\">\n    <router - view></router - view>\n  </div>\n</template>\n```\n\n* 当用户访问不同的路由路径时，对应的组件就会显示在这个标签位置。\n\n2. **创建路由链接**\n   * 使用`<router - link>`标签创建路由链接，它会渲染成一个带有正确`href`属性的`<a>`标签。例如：\n\n```html\n<router - link to=\"/\">Home</router - link>\n<router - link to=\"/about\">About</router - link>\n```\n\n* 当用户点击这些链接时，会导航到相应的路由路径，并且页面不会刷新，实现了单页应用的页面切换。\n\n## 四、动态路由\n\n1. **定义动态路由参数**\n   * 可以在路由路径中定义参数。例如，定义一个用户详情页面的动态路由：\n\n```javascript\nconst routes = [\n  { path: \'/user/:id\', component: UserDetail }\n];\n```\n\n* 这里`/user/:id`中的`id`就是动态参数，不同的`id`值会加载不同的用户详情。\n\n2. **在组件中获取参数**\n   * 在`UserDetail`组件中，可以通过`this.$route.params.id`来获取这个动态参数。例如：\n\n```javascript\nexport default {\n  name: \'UserDetail\',\n  mounted() {\n    const userId = this.$route.params.id;\n    // 根据userId获取用户详情数据等操作\n  }\n};\n```\n\n## 五、嵌套路由\n\n1. **定义嵌套路由**\n   * 当一个组件内部还需要根据不同的子路径显示不同的子组件时，就需要使用嵌套路由。例如，在一个`Dashboard`组件内部有不同的子页面：\n\n```javascript\nconst routes = [\n  {\n    path: \'/dashboard\',\n    component: Dashboard,\n    children: [\n      { path: \'overview\', component: Overview },\n      { path: \'settings\', component: Settings }\n    ]\n  }\n];\n```\n\n* 这里`/dashboard`是父路由，它有两个子路由`/dashboard/overview`和`/dashboard/settings`。\n\n2. **在父组件中显示子组件**\n   * 在`Dashboard`组件的模板中，同样使用`<router - view></router - view>`来显示子路由对应的组件。例如：\n\n```html\n<template>\n  <div>\n    <h1>Dashboard</h1>\n    <router - view></router - view>\n  </div>\n</template>\n```\n\n* 当用户访问`/dashboard/overview`时，`Overview`组件会显示在`Dashboard`组件内部的`<router - view>`位置。\n\n## 六、路由导航守卫\n\n1. **全局前置守卫**\n   * 可以使用全局前置守卫来在路由跳转前进行一些验证或操作。例如，检查用户是否登录：\n\n```javascript\nrouter.beforeEach((to, from, next) => {\n  const isLoggedIn = checkLoginStatus();\n  if (to.path === \'/dashboard\' &&!isLoggedIn) {\n    next(\'/login\');\n  } else {\n    next();\n  }\n});\n```\n\n* 这里`beforeEach`方法会在每个路由跳转前被调用。`to`是要跳转的目标路由，`from`是当前路由，`next`用于控制是否继续跳转。\n\n2. **路由独享守卫**\n   * 可以在单个路由定义中添加守卫。例如：\n\n```javascript\nconst routes = [\n  {\n    path: \'/admin\',\n    component: Admin,\n    beforeEnter: (to, from, next) => {\n      const hasAdminPermission = checkAdminPermission();\n      if (hasAdminPermission) {\n        next();\n      } else {\n        next(\'/\');\n      }\n    }\n  }\n];\n```\n\n* 这种守卫只对该特定路由生效，在进入这个路由前进行权限检查等操作。\n', '', 0, 1, '2022-05-10 19:38:05', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (16, '状态管理：vuex', 'Vuex 是 Vue.js 的状态管理库，集中管理应用状态。核心概念包括 State、Mutations、Actions、Getters 及模块，方便管理复杂应用状态。', '# Vuex\n\n## 一、概述\n\nVuex 是一个专为 Vue.js 应用程序开发的状态管理模式 + 库。它采用集中式存储管理应用的所有组件的状态，使得状态的变化可预测且易于调试。\n\n## 二、核心概念\n\n### （一）State（状态）\n\n1. **定义**\n   * 是应用的数据中心，存储着需要在多个组件中共享的数据。例如，在一个电商应用中，商品列表、购物车数据等都可以存储在 State 中。\n2. **在组件中访问**\n   * 在 Vue 组件中，可以通过`this.$store.state`来访问 State 中的数据。例如，如果`store`中有一个名为`count`的状态属性，在组件中可以通过`this.$store.state.count`来获取它的值。\n\n### （二）Mutations（突变）\n\n1. **定义**\n   * 是唯一能修改 State 的地方，它是一些同步函数，用于提交状态变更。就像一个严格的规则执行者，保证状态的修改是有序的。\n2. **使用方式**\n   * 首先在 Vuex 的`store`中定义`Mutations`。例如：\n\n```javascript\nconst store = new Vuex.Store({\n  state: {\n    count: 0\n  },\n  mutations: {\n    increment(state) {\n      state.count++;\n    }\n  }\n});\n```\n\n* 在组件中，通过`this.$store.commit(\'increment\')`来调用`Mutations`，从而修改`State`中的`count`属性。\n\n### （三）Actions（动作）\n\n1. **定义**\n   * 用于处理异步操作，比如发送网络请求获取数据。它可以包含任意的异步操作，并且可以提交`Mutations`来间接修改`State`。\n2. **使用方式**\n   * 在`store`中定义`Actions`。例如：\n\n```javascript\nconst store = new Vuex.Store({\n  state: {\n    products: []\n  },\n  mutations: {\n    setProducts(state, products) {\n      state.products = products;\n    }\n  },\n  actions: {\n    fetchProducts({ commit }) {\n      axios.get(\'/api/products\')\n      .then(response => {\n          commit(\'setProducts\', response.data);\n        });\n    }\n  }\n});\n```\n\n* 在组件中，通过`this.$store.dispatch(\'fetchProducts\')`来触发`Actions`，获取产品数据并更新`State`中的`products`属性。\n\n### （四）Getters（获取器）\n\n1. **定义**\n   * 可以看作是`State`的计算属性，用于从`State`中派生出一些状态。当需要对`State`中的数据进行过滤、计算等操作时使用。\n2. **使用方式**\n   * 在`store`中定义`Getters`。例如：\n\n```javascript\nconst store = new Vuex.Store({\n  state: {\n    products: [\n      { id: 1, price: 10, name: \'Product 1\' },\n      { id: 2, price: 20, name: \'Product 2\' }\n    ]\n  },\n  getters: {\n    totalPrice(state) {\n      return state.products.reduce((total, product) => {\n        total += product.price;\n        return total;\n      }, 0);\n    }\n  }\n});\n```\n\n* 在组件中，通过`this.$store.getters.totalPrice`来获取计算后的总价。\n\n## 三、模块（Modules）\n\n1. **定义**\n   * 当应用变得复杂，`State`、`Mutations`、`Actions`和`Getters`会变得庞大。这时可以使用模块将`store`分割成多个小的模块，每个模块有自己独立的一套上述概念。\n2. **使用方式**\n   * 例如，定义一个用户模块：\n\n```javascript\nconst userModule = {\n  namespaced: true,\n  state: {\n    userInfo: {\n      name: \'John\',\n      age: 30\n    }\n  },\n  mutations: {\n    updateUserInfo(state, newInfo) {\n      state.userInfo = newInfo;\n    }\n  },\n  actions: {\n    fetchUserInfo({ commit }) {\n      axios.get(\'/api/userInfo\')\n      .then(response => {\n          commit(\'updateUserInfo\', response.data);\n        });\n    }\n  },\n  getters: {\n    getUserAge(state) {\n      return state.userInfo.age;\n    }\n  }\n};\nconst store = new Vuex.Store({\n  modules: {\n    user: userModule\n  }\n});\n```\n\n* 在组件中访问用户模块的状态可以通过`this.$store.state.user.userInfo`，访问`Getters`可以通过`this.$store.getters[\'user.getUserAge\']`等。\n', '', 0, 1, '2022-05-11 22:25:17', 1, '2025-05-25 23:25:46', 1, 0, 1, 1);
INSERT INTO `article` VALUES (17, '前端工程化', '前端工程化是将软件开发方法应用于前端开发，涵盖模块化、使用构建工具（如 Webpack）、代码规范与格式化（如 ESLint）、自动化测试（如 Jest）及项目部署等，以提升开发效率、质量和可维护性。', '# 前端工程化\n\n## 一、概述\n\n前端工程化是将软件开发的方法和原则应用到前端开发中，通过一系列工具和流程来提高前端开发的效率、质量和可维护性。它涵盖了从项目的初始化、开发过程中的代码管理、构建、测试到部署等多个环节。\n\n## 二、主要内容\n\n### （一）模块化\n\n1. **概念**\n   * 模块化是将前端代码按照功能或业务逻辑划分为独立的模块，每个模块有自己的职责和接口。这样可以降低代码的耦合度，提高代码的复用性和可维护性。\n2. **实现方式**\n   * **CommonJS**：主要用于服务器端的 JavaScript 模块规范，如 Node.js。在 CommonJS 中，通过`require`函数引入模块，通过`module.exports`或`exports`导出模块。例如：\n\n```javascript\n// 模块a.js\nfunction add(a, b) {\n  return a + b;\n}\nmodule.exports = add;\n// 另一个模块中使用\nconst addFunction = require(\'./a.js\');\nconsole.log(addFunction(1, 2));\n```\n\n* **AMD（Asynchronous Module Definition）**：专为浏览器环境设计的异步模块加载规范。它通过`define`函数来定义模块，通过`require`函数来加载模块。例如：\n\n```javascript\ndefine([\'./a\'], function(add) {\n  console.log(add(3, 4));\n});\n```\n\n* **ES6 模块**：是 JavaScript 原生的模块系统。使用`import`和`export`关键字。例如：\n\n```javascript\n// 模块a.js\nexport function add(a, b) {\n  return a + b;\n}\n// 另一个模块中使用\nimport { add } from \'./a.js\';\nconsole.log(add(5, 6));\n```\n\n### （二）构建工具\n\n1. **概念**\n   * 构建工具用于将前端开发中的各种资源（如 JavaScript、CSS、HTML 等）进行处理，包括编译、压缩、合并、打包等操作，以优化代码性能并适配不同的浏览器环境。\n2. **常见构建工具 - Webpack**\n   * **安装与配置**：首先通过`npm install webpack webpack - cli - g`安装。然后在项目目录下创建`webpack.config.js`文件进行配置。例如，简单的配置如下：\n\n```javascript\nconst path = require(\'path\');\nmodule.exports = {\n  entry: \'./src/index.js\',\n  output: {\n    path: path.resolve(__dirname, \'dist\'),\n    filename: \'bundle.js\'\n  }\n};\n```\n\n* 这个配置指定了入口文件为`src/index.js`，输出文件为`dist/bundle.js`。\n* **加载器（Loaders）**：Webpack 本身只能理解 JavaScript，对于其他类型的文件（如 CSS、图片等）需要使用加载器来处理。例如，使用`style - loader`和`css - loader`来处理 CSS 文件。在配置文件中添加：\n\n```javascript\nmodule: {\n  rules: [\n    {\n      test: /\\.css$/,\n      use: [\'style - loader\', \'css - loader\']\n    }\n  ]\n};\n```\n\n* 当遇到`.css`文件时，会先使用`css - loader`解析 CSS 文件，再使用`style - loader`将 CSS 插入到 HTML 文档中。\n* **插件（Plugins）**：插件用于执行更复杂的任务，如压缩代码、生成 HTML 文件等。例如，使用`html - webpack - plugin`来生成 HTML 文件并自动引入打包后的 JavaScript 文件。首先安装`html - webpack - plugin`，然后在配置文件中添加：\n\n```javascript\nconst HtmlWebpackPlugin = require(\'html - webpack - plugin\');\nmodule.exports = {\n  //...其他配置\n  plugins: [\n    new HtmlWebpackPlugin({\n      template: \'./src/index.html\',\n      filename: \'index.html\'\n    })\n  ]\n};\n```\n\n* 这样会根据`src/index.html`模板生成`dist/index.html`文件，并自动引入`bundle.js`。\n\n### （三）代码规范与格式化\n\n1. **概念**\n   * 代码规范和格式化能够确保团队开发的代码风格一致，提高代码的可读性和可维护性。\n2. **工具 - ESLint**\n   * **安装与配置**：通过`npm install eslint - g`安装。然后在项目目录下通过`eslint --init`初始化配置文件。配置文件可以指定代码规则，如变量命名规范、缩进规则等。例如，配置文件可能包含：\n\n```json\n{\n  \"rules\": {\n    \"semi\": [\"error\", \"always\"],\n    \"indent\": [\"error\", 2]\n  }\n}\n```\n\n* 这表示要求语句必须以分号结尾，缩进为 2 个空格。\n* **集成到开发流程**：可以在代码编辑器中安装 ESLint 插件，让编辑器在编写代码时实时提示不符合规范的地方。也可以在构建过程中加入 ESLint 检查，确保代码在构建时符合规范。\n\n### （四）自动化测试\n\n1. **概念**\n   * 自动化测试用于验证前端代码的功能是否正确，包括单元测试、集成测试等。通过编写测试用例，可以在代码修改后快速验证是否引入了新的错误。\n2. **常见测试框架 - Jest**\n   * **安装与使用**：通过`npm install jest - g`安装。例如，对于一个简单的 JavaScript 函数进行单元测试：\n\n```javascript\nfunction add(a, b) {\n  return a + b;\n}\ntest(\'add函数应该正确相加两个数\', () => {\n  expect(add(1, 2)).toBe(3);\n});\n```\n\n* 在项目目录下运行`jest`命令就可以执行这个测试用例。如果函数的功能不符合预期，测试就会失败。\n\n### （五）项目部署\n\n1. **概念**\n   * 将前端项目发布到服务器或者云端，让用户能够访问。这涉及到选择合适的服务器、配置服务器环境、上传文件等操作。\n2. **方式 - 静态服务器部署**\n   * 对于静态前端项目（如纯 HTML、CSS 和 JavaScript 构建的项目），可以使用简单的静态服务器来部署。例如，使用`serve`工具，通过`npm install serve - g`安装，然后在项目目录下运行`serve - s dist`（假设构建后的文件在`dist`目录），就可以启动一个本地服务器来访问项目。也可以将项目文件上传到云服务器（如阿里云、腾讯云等）的静态资源存储区域，配置好域名等相关信息后，让用户通过互联网访问。\n', '', 0, 1, '2022-05-25 19:18:46', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (18, '原生微信小程序开发', '原生微信小程序开发需注册账号并安装开发工具。其项目结构包括基本文件和页面文件夹等。使用 WXML 构建页面结构，WXSS 设置样式，JavaScript 处理逻辑。', '# 原生微信小程序开发\n\n## 一、开发环境搭建\n\n1. **注册账号**\n   * 首先需要在微信公众平台注册一个小程序账号，填写相关的信息，包括邮箱、密码、主体类型（个人、企业等）。完成注册后，通过账号登录微信公众平台。\n2. **安装开发工具**\n   * 下载并安装微信开发者工具。它是官方提供的集成开发环境，支持代码编写、调试、预览和发布等功能。安装完成后，打开工具，使用小程序账号进行登录。\n\n## 二、项目结构\n\n1. **基本结构**\n   * 一个微信小程序项目主要包含`app.js`、`app.json`、`app.wxss`三个文件和`pages`、`utils`等文件夹。\n   * `app.js`是小程序的逻辑文件，用于控制小程序的生命周期，如`onLaunch`（小程序启动时触发）、`onShow`（小程序显示时触发）和`onHide`（小程序隐藏时触发）等函数。\n   * `app.json`是小程序的全局配置文件，用于配置页面路径、窗口样式、导航栏样式等。例如，可以设置页面的标题栏颜色、是否启用下拉刷新等功能。\n   * `app.wxss`是小程序的全局样式文件，定义了小程序的公共样式，如字体大小、颜色、布局等。\n   * `pages`文件夹存放小程序的各个页面，每个页面通常由`js`（逻辑）、`wxml`（类似 HTML 的模板语言）、`wxss`（样式）和`json`（页面配置）四个文件组成。\n   * `utils`文件夹用于存放工具类函数，如数据请求、日期处理等工具函数。\n\n## 三、WXML（WeiXin Markup Language）\n\n1. **基本语法**\n   * WXML 是一种类似于 HTML 的标记语言，用于构建小程序的页面结构。它支持标签、属性和数据绑定。例如，`<view>`标签用于构建视图容器，类似于 HTML 中的`<div>`。\n   * **数据绑定**：使用双花括号`{{}}`进行数据绑定。假设在页面的`js`文件中有一个数据`message`，可以在 WXML 中通过`{{message}}`来显示这个数据。例如：\n\n```xml\n<view>{{message}}</view>\n```\n\n* **列表渲染**：使用`wx:for`指令进行列表渲染。例如，如果有一个数组`list`，可以这样在 WXML 中循环显示数组元素：\n\n```xml\n<view wx:for=\"{{list}}\" wx:key=\"index\">{{item}}</view>\n```\n\n* 这里`wx:key`属性是为了帮助小程序更高效地更新列表，`index`是数组的索引，`item`是数组中的每个元素。\n* **条件渲染**：使用`wx:if`、`wx:elif`和`wx:else`指令进行条件渲染。例如：\n\n```xml\n<view wx:if=\"{{isShow}}\">显示内容</view>\n<view wx:else>隐藏内容</view>\n```\n\n* 根据`isShow`变量的值来决定是否显示对应的视图。\n\n## 四、WXSS（WeiXin Style Sheets）\n\n1. **基本语法**\n   * WXSS 是小程序的样式语言，类似于 CSS。它支持大部分 CSS 的选择器和属性。例如，可以通过`class`和`id`选择器来设置元素的样式。\n   * **尺寸单位**：小程序有自己独特的尺寸单位`rpx`（responsive pixel）。它可以根据屏幕宽度进行自适应调整。例如，在不同屏幕尺寸的设备上，`750rpx`通常会占满屏幕宽度。\n   * **样式导入**：可以通过`@import`语句导入外部样式文件。例如，在`app.wxss`中可以使用`@import \'common.wxss\';`来导入`common.wxss`文件中的样式。\n\n## 五、JavaScript 逻辑\n\n1. **页面逻辑**\n   * 在每个页面的`js`文件中，除了定义数据和函数外，还可以通过`Page`函数来创建页面实例。例如：\n\n```javascript\nPage({\n  data: {\n    message: \'Hello, World!\'\n  },\n  onLoad() {\n    // 页面加载时执行的逻辑\n  }\n});\n```\n\n* 这里`data`属性用于存储页面的数据，`onLoad`函数在页面加载时被触发。\n* **事件处理**：可以在 WXML 中绑定事件处理函数。例如，对于一个按钮的点击事件：\n\n```xml\n<button bindtap=\"handleClick\">点击我</button>\n```\n\n在对应的`js`文件中定义`handleClick`函数：\n\n```javascript\nPage({\n  handleClick() {\n    console.log(\'按钮被点击了\');\n  }\n});\n```\n\n* **数据请求**：可以使用小程序提供的`wx.request`函数进行网络数据请求。例如：\n\n```javascript\nwx.request({\n  url: \'https://api.example.com/data\',\n  success: (res) => {\n    console.log(res.data);\n    // 将获取的数据存储到data中\n    this.setData({\n      data: res.data\n    });\n  }\n});\n```\n\n* 这里`success`函数在请求成功后被触发，通过`this.setData`函数将获取的数据更新到页面的数据中。\n\n## 六、小程序的 API\n\n1. **路由 API**\n   * 小程序提供了用于页面跳转的 API。例如，`wx.navigateTo`用于跳转到应用内的某个页面，同时保留当前页面。\n\n```javascript\nwx.navigateTo({\n  url: \'/pages/detail/detail?id=1\'\n});\n```\n\n* 这个函数会跳转到`/pages/detail/detail`页面，并传递一个`id`参数。\n\n2. **用户信息获取 API**\n   * 可以通过`wx.getUserInfo`获取用户的基本信息。例如：\n\n```javascript\nwx.getUserInfo({\n  success: (res) => {\n    console.log(res.userInfo);\n  }\n});\n```\n\n* 这个函数在用户授权后，会在`success`函数中返回用户的姓名、头像等信息。\n\n## 七、小程序的生命周期\n\n1. **应用生命周期**\n   * 小程序的应用生命周期包括`onLaunch`（启动）、`onShow`（显示）和`onHide`（隐藏）。`onLaunch`在小程序首次启动时触发，一般用于进行一些初始化操作，如加载全局数据。`onShow`在小程序从后台切换到前台时触发，`onHide`在小程序从前台切换到后台时触发。\n2. **页面生命周期**\n   * 页面生命周期包括`onLoad`（加载）、`onReady`（初次渲染完成）、`onShow`（显示）、`onHide`（隐藏）和`onUnload`（卸载）。`onLoad`在页面加载时触发，通常用于获取页面参数。`onReady`在页面初次渲染完成后触发，此时可以获取页面的节点信息等操作。`onShow`和`onHide`与应用生命周期中的类似，`onUnload`在页面卸载时触发，比如在页面跳转或者关闭时。\n', '', 0, 1, '2022-06-10 22:29:22', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (19, 'uni-app', 'UniApp 是用 Vue.js 开发多端应用的框架。通过 HBuilderX 搭建开发环境，其项目结构有特定目录和文件。基于 Vue.js 语法开发，支持多端适配，实现高效的多端应用开发。', '# Uniapp\n\n## 一、概述\n\nUniApp 是一个使用 Vue.js 开发所有前端应用的框架，开发者可以通过一套代码编写多端应用，包括微信小程序、H5、App（安卓和苹果）等。\n\n## 二、开发环境搭建\n\n1. **安装 HBuilderX**\n   * HBuilderX 是官方推荐的开发工具，它集成了开发 UniApp 所需的各种工具。可以从官方网站下载并安装适合自己操作系统的版本。安装完成后，打开 HBuilderX。\n2. **创建 UniApp 项目**\n   * 在 HBuilderX 中，通过菜单 “文件”->“新建”->“项目”，选择 “Uni - App” 模板，填写项目名称、路径等信息后创建项目。项目创建后会自动生成基本的目录结构和文件。\n\n## 三、项目结构\n\n1. **基本目录和文件**\n   * **pages 目录**：存放各个页面的组件文件，每个页面通常由`.vue`文件构成，这些文件包含了页面的模板（`<template>`）、脚本（`<script>`）和样式（`<style>`）。例如，`index.vue`就是首页的组件文件。\n   * **static 目录**：用于存放静态资源，如图片、字体文件等。这些资源在打包后会原封不动地放入应用中。\n   * **main.js**：是项目的入口文件，主要用于创建 Vue 应用，配置插件等。例如，在这里可以引入全局组件、全局状态管理等。\n   * **App.vue**：是整个应用的根组件，它定义了应用的整体布局和一些全局的样式、生命周期钩子等。例如，在`<template>`部分可以设置导航栏、底部 tab 栏等全局元素。\n\n## 四、基于 Vue.js 的开发\n\n1. **模板语法（`<template>`）**\n   * 与 Vue.js 相同，UniApp 在模板部分使用双花括号`{{}}`进行数据绑定。例如，`{{message}}`可以将`message`数据显示在页面上。同时也支持指令，如`v - bind`（简写为`:`）用于绑定属性，`v - model`用于双向数据绑定，`v - for`用于循环渲染等。例如：\n\n```html\n<view v - for=\"(item, index) in list\" :key=\"index\">{{item}}</view>\n```\n\n* 这里会循环渲染`list`数组中的元素。\n\n2. **脚本部分（`<script>`）**\n   * 在`<script>`部分，同样可以定义组件的属性、方法和生命周期钩子。例如，在一个组件中：\n\n```javascript\nexport default {\n  data() {\n    return {\n      message: \'Hello, UniApp!\'\n    };\n  },\n  methods: {\n    handleClick() {\n      console.log(\'按钮被点击\');\n    }\n  },\n  mounted() {\n    // 组件挂载后的操作\n  }\n};\n```\n\n* 这里`data`函数返回组件的数据，`methods`定义了组件的方法，`mounted`是生命周期钩子，在组件挂载到页面后执行。\n\n3. **样式部分（`<style>`）**\n   * 可以使用 CSS 或者预处理器（如 Sass、Less）来编写样式。在样式部分，需要注意不同端的样式兼容性。例如，对于某些 H5 特有的样式属性，可能在小程序端无法正常使用。同时，UniApp 也支持一些样式的条件编译，用于针对不同端设置不同的样式。例如：\n\n```css\n/* #ifdef MP - WEIXIN */\n  /* 微信小程序端的样式 */\n/* #endif */\n/* #ifdef H5 */\n  /* H5端的样式 */\n/* #endif */\n```\n\n## 五、多端适配\n\n1. **平台判断**\n   * UniApp 提供了`uni.getSystemInfoSync()`等方法获取系统信息，包括当前运行的平台。通过判断平台，可以编写针对不同平台的代码。例如：\n\n```javascript\nif (uni.getSystemInfoSync().platform === \'android\') {\n  // 安卓平台的特定代码\n} else if (uni.getSystemInfoSync().platform === \'ios\') {\n  // 苹果平台的特定代码\n}\n```\n\n2. **样式适配**\n   * 除了前面提到的样式条件编译，还可以利用 UniApp 的 rpx 单位进行自适应布局。rpx（responsive pixel）是一种相对单位，以屏幕宽度为基础进行计算。例如，750rpx 在所有屏幕上大致等于屏幕宽度，这样可以方便地实现布局的自适应。\n\n## 六、API 使用\n\n1. **路由 API**\n   * UniApp 提供了多种路由方式，如`uni.navigateTo`用于跳转到应用内的其他页面，保留当前页面。例如：\n\n```javascript\nuni.navigateTo({\n  url: \'/pages/detail/detail?id=1\'\n});\n```\n\n* 还有`uni.redirectTo`用于关闭当前页面，跳转到其他页面等。\n\n2. **网络请求 API**\n   * 可以使用`uni.request`进行网络数据请求。例如：\n\n```javascript\nuni.request({\n  url: \'https://api.example.com/data\',\n  success: (res) => {\n    console.log(res.data);\n    // 处理数据，更新组件数据等操作\n  }\n});\n```\n\n* 它与微信小程序的`wx.request`类似，但在多端开发中更具通用性。\n\n## 七、组件库使用\n\n1. **内置组件**\n   * UniApp 有许多内置组件，如`<view>`（视图容器）、`<text>`（文本）、`<button>`（按钮）等，这些组件的使用方式与 Vue.js 组件类似，并且在不同端有较好的兼容性。例如，使用`<button>`组件：\n\n```html\n<button @click=\"handleClick\">点击我</button>\n```\n\n2. **第三方组件库**\n   * 可以使用第三方组件库来丰富应用的功能和界面。例如，使用 uView 组件库，首先需要在项目中安装，然后在`main.js`中引入并注册。之后就可以在页面中使用该组件库中的组件，如 u - Button 等，来快速构建美观的界面。\n', '', 0, 1, '2022-07-17 21:29:46', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (20, 'react 基础', 'React 是构建用户界面的 JavaScript 库。核心是组件，有函数组件和类组件。使用 JSX 描述 UI。基于虚拟 DOM 高效更新。涉及状态和属性，类组件有生命周期方法。', '# React\n\n## 一、概述\n\nReact 是一个用于构建用户界面的 JavaScript 库，由 Facebook 开发并开源。它采用声明式编程范式，让开发者可以高效地创建交互式 UI。其核心思想是将 UI 看作是由数据驱动的一系列组件的组合。\n\n## 二、基本概念\n\n### （一）组件\n\n1. **函数组件**\n   * 是 React 组件的一种形式，它是一个纯 JavaScript 函数，接收 props（属性）作为参数，并返回一个 React 元素。例如：\n\n```javascript\nfunction Greeting(props) {\n  return <h1>Hello, {props.name}!</h1>;\n}\n```\n\n* 这里`Greeting`是一个函数组件，它接收一个名为`name`的属性，然后在`h1`标签中显示问候语。\n\n2. **类组件**\n   * 基于 ES6 的类来定义。类组件有自己的生命周期方法和状态管理。例如：\n\n```javascript\nclass Counter extends React.Component {\n  constructor(props) {\n    super(props);\n    this.state = {\n      count: 0\n    };\n  }\n  render() {\n    return (\n      <div>\n        <p>Count: {this.state.count}</p>\n        <button onClick={() => this.setState({ count: this.state.count + 1 })}>\n          Increment\n        </button>\n      </div>\n    );\n  }\n}\n```\n\n* 这个`Counter`类组件有一个`state`（状态），包含一个`count`属性。在`render`方法中，展示了当前计数并提供一个按钮，点击按钮可以通过`setState`方法更新`count`的值。\n\n### （二）JSX（JavaScript XML）\n\n1. **概念**\n   * JSX 是一种 JavaScript 的语法扩展，看起来很像 HTML，但它允许在 JavaScript 代码中嵌入类似 HTML 的标签来描述 UI 结构。React 使用 Babel 等工具将 JSX 编译成普通的 JavaScript。例如，`const element = <h1>Hello, World!</h1>;`是一个简单的 JSX 表达式。\n2. **使用规则**\n   * **表达式嵌入**：可以在 JSX 中嵌入 JavaScript 表达式，通过将表达式放在花括号`{}`内。例如，`{2 + 3}`会被计算并显示结果。\n   * **属性绑定**：在 JSX 中，属性值可以是 JavaScript 表达式。例如，`<img src={user.avatar} alt=\"User Avatar\" />`，其中`user.avatar`是一个 JavaScript 变量。\n   * **组件使用**：可以像使用 HTML 标签一样使用组件。如果有一个`Greeting`组件，就可以通过`<Greeting name=\"John\" />`来使用，将`name`属性传递给组件。\n\n## 三、React 的工作原理：虚拟 DOM（Document Object Model）\n\n1. **概念**\n   * 虚拟 DOM 是 React 的核心概念之一。它是一个轻量级的 JavaScript 对象，是真实 DOM 的抽象表示。当组件的状态或属性发生变化时，React 会创建一个新的虚拟 DOM 树，并与旧的虚拟 DOM 树进行比较（这个过程称为 Diffing）。\n2. **更新流程**\n   * 比较之后，React 会找出需要更新的最小部分，然后只将这些变化应用到真实 DOM 上。这样可以减少对真实 DOM 的操作次数，提高性能。例如，当一个列表中的一个元素发生变化时，React 不会重新渲染整个列表，而是只更新那个变化的元素。\n\n## 四、状态（State）和属性（Props）\n\n1. **状态（State）**\n   * 状态是组件内部的数据，只有类组件可以有状态。状态是可变的，当状态改变时，组件会重新渲染。状态应该通过`setState`方法来更新，这样 React 才能正确地处理 DOM 更新。例如，在前面的`Counter`类组件中，`count`就是一个状态，通过`setState`方法更新它会导致组件重新渲染。\n2. **属性（Props）**\n   * 属性是从父组件传递给子组件的数据，是不可变的。子组件不能直接修改接收到的属性。属性用于在组件之间传递数据和配置信息。例如，在`Greeting`函数组件中，`name`就是通过属性传递进来的数据。\n\n## 五、生命周期方法（主要针对类组件）\n\n1. **挂载阶段（Mounting）**\n   * **constructor**：是类组件的构造函数，用于初始化状态和绑定方法。例如，在`Counter`组件的`constructor`中初始化了`count`状态。\n   * **componentDidMount**：在组件挂载到 DOM 后立即调用。这个阶段适合进行数据获取、订阅等操作。例如，可以在这个方法中发送网络请求获取数据，并将数据设置为组件的状态。\n2. **更新阶段（Updating）**\n   * **shouldComponentUpdate**：在组件更新之前调用，用于决定组件是否需要重新渲染。如果返回`false`，则组件不会重新渲染，这可以用于性能优化。\n   * **componentDidUpdate**：在组件更新后调用。可以在这里对更新后的 DOM 进行操作，或者根据更新后的状态执行其他操作。\n3. **卸载阶段（Unmounting）**\n   * **componentWillUnmount**：在组件从 DOM 中卸载之前调用。适合清理一些在`componentDidMount`中创建的订阅、定时器等资源。\n\n## 六、React 的生态系统\n\n1. **React Router**\n   * 用于在 React 应用中实现路由功能。它允许创建单页应用，通过管理 URL 和对应的组件显示，实现页面之间的导航。例如，可以定义不同的路由路径和对应的组件，当用户访问不同的 URL 时，显示相应的组件。\n2. **Redux（或其他状态管理库）**\n   * 当 React 应用变得复杂，需要管理大量的状态时，可以使用 Redux 等状态管理库。Redux 采用单向数据流的方式，通过`action`（动作）、`reducer`（减速器）和`store`（存储）来管理整个应用的状态。它使得状态的变化可预测且易于调试。\n', '', 0, 1, '2022-08-09 19:20:42', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (21, '前端面试题总结', '前端面试题总结', '## 面试题库\n\n### 一、说一说 HTML 语义化？\n\n1. **HTML 语义化就是指在使用 HTML 标签构建页面时，避免大篇幅使用无语义的标签。**\n2. **使用语义化标签：有利于提高代码可读性，有利于搜索引擎优化，有利于页面结构化，在不引入 CSS 时也有较好的页面结构和代码结构。**\n\n### 二、说一说盒模型？\n\n1. **盒模型分为两类，一是标准盒模型，二是怪异盒模型。一般我们的盒子默认是标准盒模型。**\n2. **两者区别是标准盒模型的实际宽高会把 padding 和 border 计算在内，而怪异盒模型不会。 **\n3. **形成怪异盒模型的条件是 **`box-sizing: border-box`；形成标准盒模型的条件 `box-sizing: content-box`。\n\n### 三、说一说三栏布局的实现方案\n\n1. **三栏布局，要求左右两边盒子宽度固定，中间盒子宽度自适应，盒子的高度都是随内容撑高的，一般都是中间盒子内容较多，为了保证页面渲染快，在写结构的时候，需要把中间盒子放在左右盒子的前面。 实现三栏布局的方法通常是圣杯布局和双飞翼布局。 **\n2. **关键技术：使用float布局，两侧的margin为负值，圣杯结构中使用padding，双飞翼使用margin**\n\n### 四、说一说浮动\n\n1. **浮动的作用：常用于图片，可以实现文字环绕图片。**\n2. **浮动的特点：脱离文档流，容易造成盒子塌陷，影响其他元素的排列。**\n3. **清除浮动的方法：**\n   * **给父元素添加高度**\n   * **父元素添加属性 **`overflow: hidden`\n   * **父级添加伪元素 **`::after{content:\'\', clear: both, display: table}` （推荐）\n   * **父级添加 before 和 after 双伪元素**\n\n### 五、说一说 BFC\n\n1. **定义：BFC(Block Formatting Context) 块级格式化上下文，是 Web 页面一块独立的渲染区域，内部元素的渲染不会影响边界以外的元素。**\n2. **形成条件：开启浮动，绝对定位（ position: fixed, absolute ），overflow（除了visible都会触发），display（display: inline-block, flex）**\n3. **布局规则：在 BFC 中，盒子从顶部开始垂直地一个接一个排列；盒子垂直方向的距离由 margin 决定，同一个 BFC 的两个相邻盒子margin会重叠；BFC 区域不会与浮动的盒子产生交集，而是紧贴边缘浮动；计算 BFC 高度时，自然会检测浮动的盒子高度。**\n4. **解决问题：清除内部浮动，去除边距重叠。**\n\n### 六、说几个未知宽高元素水平垂直居中方法\n\n1. **设置元素相对父级定位 **`position: absolute; left: 50%; top: 50%`，让自身平移自身高度50% `transform: translate(-50%,-50%)`，这种方式兼容性好，被广泛使用的一种方式。\n2. **设置元素的父级为弹性盒子**`display:flex`，设置父级盒子内部子元素水平垂直都居中`justify-content:center; align-items:center` ，这种方式代码简洁，但是兼容性 ie11 以上支持，由于目前 ie 版本都已经很高，很多网站现在也使用这种方式实现水平垂直居中。\n3. **设置元素的父级为网格元素**`display: grid`，设置父级和盒子内部子元素水平垂直都居中`justify-content:center; align-items:center` ，这种方式代码简介，但是兼容性 ie10 以上支持。\n4. **设置元素的父级为表格元素**`display: table-cell`，其内部元素水平垂直都居中`text-align: center; vertical-align: middle;` ，设置子元素为行内块`display: inline-block` 。这种方式兼容性较好。\n\n### 七、说一说 JavaScript 有几种方法判断变量的类型？\n\n* **JavaScript 有4种方法判断变量的类型，分别是typeof、instanceof、constructor (用于引用数据类型)、Object.prototype.toString.call()（对象原型链判断方法）。**\n\n1. **typeof：用来判断基本数据类型，对于引用数据类型 function 返回 function 其他都返回 Object 。**\n2. **instanceof：主要用于区分引用数据类型，检测方法是检测的类型再当前实例的原型链上，用其检测出来的结果都是 true ，不太适合检测简单数据类型的检测，检测过程繁琐且对简单数据类型中的 undefined null symbol 检测不出来。 **\n3. **constructor：用于检测引用数据类型，检测方法是获取实例的构造函数判断和某个类是否相同，如果相同就说明该数据是符合那个数据类型的，这种方法不会把原型链上的其他类也加入进来，避免了原型链的干扰。**\n4. **Object.prototype.toString.call()：适用于所有类型的检测，检测方法是 Object.prototype.toString.call(数据) 返回的是该数据类型的字符串。最精准的就是这个方法。**\n\n### 八、说一说你对闭包的理解？\n\n1. **闭包：一个函数能读取另一个函数内部的变量。**\n2. **闭包函数：声明在一个函数中的函数，叫做闭包函数。这个函数能够读取其他函数内部变量。**\n3. **闭包形成的原理：作用域链，当前作用域可以访问上级作用域中的变量 。**\n4. **闭包解决的问题：能够让函数作用域中的变量在函数执行结束之后不被销毁，同时也能在函数外部可以访问函数内部的局部变量。**\n5. **闭包带来的问题：由于垃圾回收器不会将闭包中变量销毁，于是就造成了内存泄露，内存泄露积累多了就容易导致内存溢出。**\n6. **闭包的应用: 模仿块级作用域，实现柯里化**\n\n### 九、说一下浏览器输入 URL 发生了什么？\n\n* **输入地址，浏览器查找域名的 IP 地址。 浏览器向 该 IP 地址的web 服务器发送一个 HTTP 请求，在发送请求之前浏览器和服务器建立TCP的三次握手，判断是否是HTTP缓存，如果是强制缓存且在有效期内，不再向服务器发请求，如果是HTTP协商缓存向后端发送请求且和后端服务器对比，在有效期内，服务器返回304，直接从浏览器获取数据，如果不在有效期内服务器返回200，返回新数据。 请求发送出去服务器返回重定向，浏览器再按照重定向的地址重新发送请求。 如果请求的参数有问题，服务器端返回404，如果服务器端挂了返回500。 如果有数据一切正常，当浏览器拿到服务器的数据之后，开始渲染页面同时获取HTML页面中图片、音频、视频、CSS、JS，在这期间获取到JS文件之后，会直接执行JS代码，阻塞浏览器渲染，因为渲染引擎和JS引擎互斥，不能同时工作，所以通常把Script标签放在body标签的底部。 渲染过程就是先将HTML转换成dom树，再将CSS样式转换成stylesheet，根据dom树和stylesheet创建布局树，对布局树进行分层，为每个图层生成绘制列表，再将图层分成图块，紧接着光栅化将图块转换成位图，最后合成绘制生成页面。**\n\n1. **url 解析：判断是搜索内容还是请求 URL **\n2. **查找本地缓存：如果有缓存直接返回给页面，没有缓存则进入网络请求阶段 **\n3. **DNS 解析**\n4. **通过三次握手建立 TCP 连接 **\n5. **合成请求头信息，发送 http 请求 **\n6. **处理响应信息 **\n7. **通过四次挥手断开 TCP 连接 **\n8. **如果响应状态码301，则重定向 **\n9. **浏览器进行页面渲染：1）解析 html ，生成 DOM 树；2）根据 css 计算节点样式，生成 stylesheet ；3）生成布局树；4）为特定的元素生成独立图层；5）...**\n\n### 十、说一说数组去重有哪些方法\n\n1. **遍历数组：创建一个空的新数组，遍历数组，判断新数组中是否存在，如果不存在就添加到新数组，返回的这个新数组就是去重后的数组。**\n2. **利用Set类型数据无重复项：new 一个 Set，参数为需要去重的数组，Set 会自动删除重复的元素，再将 Set 转为数组返回。这个方法的优点是效率更高，代码简单，思路清晰，缺点是可能会有兼容性问题 。**\n   **代码示例：new Set([1,1,2,2,3,3])**	**// => [1,2,3]**		**推荐使用！**\n3. **filter + indexof 去重：原理就是 indexOf 会返回最先找到的数字的索引，假设数组是 [1, 1]，在对第二个1使用 indexOf 方法时，返回的是第一个1的索引0。**\n   **代码示例：[1,1,2,2,3,3].filter((item, index, array) => index === array.indexOf(item))**	**// => [1,2,3]**\n4. **reduce + includes去重：这个方法就是利用 reduce 遍历和传入一个空数组作为去重后的新数组，然后内部判断新数组中是否存在当前遍历的元素，不存在就插入到新数组中。**\n\n### 十一、说一说 CSS 尺寸设置的单位\n\n1. **px：pixel 像素的缩写，绝对长度单位，它的大小取决于屏幕的分辨率，是开发网页中常常使用的单位。**\n2. **em：相对长度单位，在 **`font-size` 中使用是相对于父元素的字体大小，在其他属性中使用是相对于自身的字体大小，如 width。如当前元素的字体尺寸未设置，由于字体大小可继承的原因，可逐级向上查找，最终找不到则相对于浏览器默认字体大小。\n3. **rem：相对长度单位，相对于根元素的字体大小，根元素字体大小未设置，使用浏览器默认字体大小。 **\n4. **vw：相对长度单位，相对于视窗宽度的1%。**\n5. **vh：相对长度单位，相对于视窗高度的1%。**\n\n**加分回答：**\n\n* **rem应用：在移动端网页开发中，页面要做成响应式的，可使用rem配合媒体查询或者flexible.js实现。原理是通过媒体查询或者flexible.js，能够在屏幕尺寸发生改变时，重置html根元素的字体大小，页面中的元素都是使用rem为单位设置的尺寸，因此只要改变根元素字体大小，页面中的其他元素的尺寸就自动跟着修改 **\n* **vw应用：由于vw被更多浏览器兼容之后，在做移动端响应式页面时，通常使用vw配合rem。原理是使用vw设置根元素html字体的大小，当窗口大小发生改变，vw代表的尺寸随着修改，无需加入媒体查询和flexible.js，页面中的其他元素仍使用rem为单位，就可实现响应式。**\n\n### 十二、说一说样式优先级的规则是什么？\n\n* **！improtant > 行内样式 > id选择器 > 类选择器 > 标签选择器 > 通配符**\n* **选择器权重：** **	**继承或者通配符 \\***		**0,0,0,0** **  **			**标签选择器**			**0,0,0,1** **  **			**类选择器、伪类选择器  0,0,1,0** **  **			**id选择器**				**0,1,0,0** **  **			**行内选择器**			**1,0,0,0** **  **			**！important  **		**无穷大\n\n### 十三、说一说 js 继承的方法和优缺点？\n\n1. **原型链继承：让一个构造函数的原型是另一个类型的实例，那么这个构造函数new出来的实例就具有该实例的属性。**\n2. **构造函数继承：在子类型构造函数的内部调用父类型构造函数，使用 apply() 或 call() 方法将父对象的构造函数绑定在子对象上。**\n3. **原型链+构造函数继承：**\n4. **原型式继承：利用 Object.create() 方法，在一个函数A内部创建一个临时性的构造函数，然后将传入的对象作为这个构造函数的原型，最后返回这个临时类型的一个新实例。**\n5. **复制式继承：**\n6. **原型链+构造函数+复制式继承：**\n   **加分回答：**\n   * **ES5 的继承：实质是先创造子类的实例对象this，然后再将父类的方法添加到this上面。**\n   * **ES6 的继承机制完全不同，实质是先将父类实例对象的属性和方法，加到this上面（所以必须先调用super方法），然后再用子类的构造函数修改this。**\n\n### 十四、说一说 promise 是什么与使用方法？\n\n1. **Promise的作用：Promise是异步微任务，解决了异步多层嵌套回调的问题，让代码的可读性更高，更容易维护。**\n2. **Promise使用：Promise是ES6提供的一个构造函数，可以使用Promise构造函数new一个实例，Promise构造函数接收一个函数作为参数，这个函数有两个参数，分别是两个函数 **`resolve`和`reject`，`resolve`将Promise的状态由等待变为成功，将异步操作的结果作为参数传递过去；`reject`则将状态由等待转变为失败，在异步操作失败时调用，将异步操作报出的错误作为参数传递过去。实例创建完成后，可以使用`then`方法分别指定成功或失败的回调函数，也可以使用catch捕获失败，then和catch最终返回的也是一个Promise，所以可以链式调用。\n3. **Promise的特点：**\n   * **\\\\1. 对象的状态不受外界影响（Promise对象代表一个异步操作，有三种状态）。 - pending（执行中） - Resolved（成功，又称Fulfilled） - rejected（拒绝） 其中 pending 为初始状态，fulfilled 和 rejected 为结束状态（结束状态表示 promise 的生命周期已结束）。**\n   * **\\\\2. 一旦状态改变，就不会再变，任何时候都可以得到这个结果。 Promise对象的状态改变，只有两种可能（状态凝固了，就不会再变了，会一直保持这个结果）： - 从 Pending 变为 Resolved  - 从 Pending 变为Rejected 。**\n   * **\\\\3. resolve 方法的参数是 then 中回调函数的参数，reject 方法中的参数是catch中的参数。**\n   * **\\\\4. then 方法和 catch 方法 只要不报错，返回的都是一个 fullfilled 状态的 promise。**\n\n### 十五、说一说跨域是什么？如何解决跨域问题？\n\n1. **跨域：当前页面中的某个接口请求的地址和当前页面的地址如果协议、域名、端口其中有一项不同，就说该接口跨域了。**\n2. **跨域限制的原因：浏览器为了保证网页的安全，出的同源协议策略。**\n3. **跨域解决方案：**\n   * **前端：1. 利用 script 中 src 属性发送 jsonp 请求但是这种方式只支持 get 请求无法解决其他的请求类型；2. 前端配置一个代理服务器（proxy）代替浏览器去发送请求：因为服务器与服务器之间是可以通信的不受同源策略的影响。 **\n   * **服务端：服务端通过配置 cors 来解决跨域，配置响应头：setHeader(access-control-allow-origin，对应的域名)**\n\n### 十六、说一说前端性能优化手段？\n\n1. **前端性能优化分为两类，一类是文件加载更快，另一类是文件渲染更快。**\n2. **加载更快的方法：**\n   * **让传输的数据包更小（压缩文件/图片）：图片压缩和文件压缩 **\n   * **减少网络请求的次数：雪碧图/精灵图、节流防抖**\n   * **减少渲染的次数：缓存（HTTP缓存、本地缓存、Vue的keep-alive缓存等）**\n3. **渲染更快的方法：**\n   * **提前渲染：ssr 服务器端渲染**\n   * **避免渲染阻塞：CSS 放在 HTML 的 head 中， JS 放在 HTML 的 body 底部**\n   * **避免无用渲染：懒加载 **\n   * **减少渲染次数：对dom查询进行缓存、将dom操作合并、使用减少重排的标签**\n4. **加分回答：雪碧图（精灵图）的应用场景一般是项目中不常更换的一些固定图标组合在一起，比如logo、搜索图标、切换图标等。 电商项目中最常用到的懒加载，一般在查看商品展示的时候通常下拉加载更多，因为商品数据太多，一次性请求过来数据太大且渲染的时间太长。**\n\n### 十七、说一说cookie、sessionStorage、localStorage 区别？\n\n1. **Cookie、SessionStorage、 LocalStorage都是浏览器的本地存储。**\n2. **它们的共同点：都是存储在浏览器本地的。**\n3. **它们的区别：**\n   * **cookie是由服务器端写入的，而SessionStorage、 LocalStorage都是由前端写入的。**\n   * **cookie的生命周期是由服务器端在写入的时候就设置好的，LocalStorage是写入就一直存在，除非手动清除，SessionStorage是页面关闭的时候就会自动清除。**\n   * **cookie的存储空间比较小大概4KB，SessionStorage、 LocalStorage存储空间比较大，大概5M。**\n   * **Cookie、SessionStorage、 LocalStorage数据共享都遵循同源原则，SessionStorage还限制必须是同一个页面。在前端给后端发送请求的时候会自动携带Cookie中的数据，但是SessionStorage、 LocalStorage不会 。**\n4. **它们应用场景也不同，Cookie一般用于存储登录验证信息SessionID或者token，LocalStorage常用于存储不易变动的数据，减轻服务器的压力，SessionStorage可以用来检测用户是否是刷新进入页面，如音乐播放器恢复播放进度条的功能。**\n\n### 十八、说一说 Vuex 是什么，每个属性是干嘛的，如何使用 ？\n\n1. **概念：Vuex是专门为Vue.js开发的状态管理模式，用来集中管理全局共享变量。相当于给window对象挂载一个全局变量。**\n2. **属性：state（数据源）、actions（处理异步事件）、mutations（处理同步事件）、getters(过滤数据)和modules（模块）**\n\n### 十九、说一说 null 和 undefined 的区别，如何让一个属性变为 null\n\n1. **undefind 是全局对象的一个属性，当一个变量没有被赋值或者一个函数没有返回值或者某个对象不存在某个属性却去访问或者函数定义了形参但没有传递实参，这时候都是undefined。**\n2. **undefined 通过 typeof 判断类型是\'undefined\'。undefined == undefined undefined === undefined 。**\n3. **null 代表对象的值未设置，相当于一个对象没有设置指针地址就是null。**\n4. **null 通过 typeof 判断类型是\'object\'。null === null，null == null，null == undefined，null !== undefined**\n5. **undefined 表示一个变量初始状态值，而 null 则表示一个变量被人为的设置为空对象，而不是原始状态。在实际使用过程中，不需要对一个变量显式的赋值 undefined，当需要释放一个对象时，直接赋值为 null 即可。 让一个变量为null，直接给该变量赋值为null即可。**\n6. **加分回答：null 其实属于自己的类型 Null，而不属于Object类型，typeof 之所以会判定为 Object 类型，是因为JavaScript 数据类型在底层都是以二进制的形式表示的，二进制的前三位为 0 会被 typeof 判断为对象类型，而 null 的二进制位恰好都是 0 ，因此，null 被误判断为 Object 类型。 对象被赋值了null 以后，对象对应的堆内存中的值就是游离状态了，GC 会择机回收该值并释放内存。因此，需要释放某个对象，就将变量设置为 null，即表示该对象已经被清空，目前无效状态。**\n\n### 二十、说一说 vue 钩子函数？\n\n1. **钩子函数用来描述一个组件从引入到退出的全过程中的某个过程，整个过程称为生命周期。 钩子函数按照组件生命周期的过程分为，挂载阶段=>更新阶段=>销毁阶段。**\n2. **每个阶段对应的钩子函数：**\n   * **挂载阶段：beforeCreate、created、beforeMounted、mounted **\n   * **更新阶段：beforeUpdate、updated**\n   * **销毁阶段：beforeDestroy、destroyed**\n3. **父子组件钩子函数在三个阶段的代码执行顺序：**\n   * **挂载：父亲created> 子created > 子mounted> 父亲mounted**\n   * **更新：父亲beforeUpdate > 子beforeUpdated > 子updated > 父亲updated **\n   * **销毁：父亲beforeDestroy> 子beforeDestroy > 子destroyed> 父destroyed**\n\n### 二十一、说一说call apply bind的作用和区别？\n\n**首先，call apply bind三个方法都可以用来改变函数的this指向，具体区别如下：**\n\n1. **fn.call (newThis,params) call函数的第一个参数是this的新指向，后面依次传入函数fn要用到的参数。会立即执行fn函数。**\n2. **fn.apply (newThis,paramsArr) apply函数的第一个参数是this的新指向,第二个参数是fn要用到的参数数组，会立即执行fn函数。**\n3. **fn.bind (newThis,params) bind函数的第一个参数是this的新指向，后面依次传入函数fn要用到的参数。 不会立即执行fn函数，且只能改变一次fn函数的指向，后续再用bind更改无效。**\n\n### 二十二、说一说 Vue 中 \\$nextTick 作用与原理？\n\n**vue中更新dom是异步操作，在修改完数据后，视图不会立刻更新，而是当同一事件循环中的所有数据变化完成之后，再进行统一的更新，所以有的时候在修改完数据后想要获取更新后的dom，则需要在nextTick中获取。nextTick的作用就是在当前渲染完成后执行，解决了异步获取不到更新后dom问题，本质是反回promise。**\n\n### 二十三、说一说 map 和 forEach 的区别？\n\n1. **map() 和 forEach() 都是数组迭代器方法，它们的区别：**\n   * **map有返回值，可以开辟新空间，return出来一个length和原数组一致的数组，即便数组元素是undefined或者是null。**\n   * **forEach默认无返回值，返回结果为undefined，可以通过在函数体内部使用索引修改数组元素。**\n2. **加分回答：map的处理速度比forEach快，而且返回一个新的数组，方便链式调用其他数组新方法，比如filter、reduce let arr = [1, 2, 3, 4, 5]; let arr2 = arr.map(value => value \\* value).filter(value => value > 10); // arr2 = [16, 25]**\n\n### 二十四、说一说 es6 中箭头函数？\n\n1. **箭头函数相当于匿名函数，简化了函数定义。箭头函数有两种写法，当函数体是单条语句的时候可以省略{}和return。另一种是包含多条语句，不可以省略{}和return。**\n2. **箭头函数最大的特点就是没有this，所以this是从外部获取，就是继承外部的执行上下文中的this，由于没有this关键字所以箭头函数也不能作为构造函数， 同时通过 **`call()` 或 `apply()` 方法调用一个函数时，只能传递参数（不能绑定this），第一个参数会被忽略。箭头函数也没有原型和super。不能使用yield关键字，因此箭头函数不能用作 Generator 函数。不能返回直接对象字面量。\n3. **箭头函数函数适用场景： **\n   * **简单的函数表达式，内部没有this引用，没有递归、事件绑定、解绑定，适用于map、filter等方法中。**\n   * **内层函数表达式，需要调用this，且this应与外层函数一致时箭头。**\n4. **函数的不适用场景： 定义对象上的方法 。**\n\n### 二十五、说一说 JS 实现异步的方法？\n\n1. **同步：一定要等任务执行完了，得到结果，才执行下一个任务。**\n2. **异步：不等任务执行完，直接执行下一个任务。**\n3. **所有异步任务都是在同步任务执行结束之后，从任务队列中依次取出执行。**\n4. **实现异步的方法：回调函数、事件监听、setTimeout（定时器）、Promise、生成器Generators/yield、async/await。**\n5. **加分回答：JS 异步编程进化史：callback -> promise -> generator/yield -> async/await。**\n\n### 二十六、说一说 Vue2.0 双向绑定的原理与缺陷？\n\n1. **Vue响应式指的是：组件的data发生变化，立刻触发视图的更新。**\n2. **vue通过v-model指令进行数据的双向绑定，数据发生变化，则立即触发视图的更新。**\n3. **原理：通过Object.definedProperty劫持数据发生的改变，如果数据发生了改变（在set中进行赋值的），触发update方法进行更新节点内容，从而实现了数据双向绑定的原理。**\n4. **Object.defineProperty的缺点 ：**\n   * **一次性递归到底开销很大，如果数据很大，大量的递归导致调用栈溢出**\n   * **不能监听对象的新增属性和删除属性**\n   * **无法正确的监听数组下标的变化，当监听的数组下标对应的数据发生改变时，不能实时响应。**\n\n### 二十七、说一说 Vue3.0 实现数据双向绑定的方法 ？\n\n### 二十八、说一说伪数组和数组的区别？、\n\n1. **伪数组类型是对象object，可以使用length属性查看长度，也可以使用[index]获取某个元素，但是不能使用数组的其他方法，也不能改变长度，遍历使用for in方法。**\n2. **伪数组出现的场景：函数的参数arguments、原生js获取DOM元素**\n3. **伪数组转换成数组的方法：**\n   * **Array.prototype.slice.call()**\n   * **[].slice.call(伪数组)**\n   * **Array.from()**\n   * **[...args]**\n\n### 二十九、说一说 this 指向（普通函数、箭头函数）？\n\n1. **this 关键字由来：在对象内部的方法中使用对象内部的属性是一个非常普遍的需求。但是 JavaScript 的作用域机制并不支持这一点，基于这个需求，JavaScript 又搞出来另外一套 this 机制。**\n2. **普通函数this指向：谁调用 this指向谁**\n   * **由new调用的话，this指向新创建的对象；**\n   * **由call或apply调用，this指向指定的对象；**\n   * **有执行上下文，指向上下文对象；**\n   * **默认情况，严格模式指向undefined，否则指向全局对象window。**\n3. **箭头函数没有arguments、没有prototype，没有自己的this，只能继承上一级作用域中this。箭头函数因为没有this，所以也不能作为构造函数，但是需要继承函数外部this的时候，使用箭头函数比较方便。**\n\n### 三十、说一下浏览器如何渲染页面的？\n\n1. **浏览器拿到HTML，先将HTML转换成dom树，再将CSS样式转换成stylesheet，根据dom树和stylesheet创建布局树，对布局树进行分层，为每个图层生成绘制列表，再将图层分成图块，紧接着光栅化将图块转换成位图，最后合成绘制生成页面。**\n2. **加分回答：**\n   * **分层的目的：避免整个页面渲染，把页面分成多个图层，尤其是动画的时候，把动画独立出一个图层，渲染时只渲染该图层就ok，transform，z-index等，浏览器会自动优化生成图层 **\n   * **光栅化目的：页面如果很长但是可视区很小，避免渲染非可视区的样式造成资源浪费，所以将每个图层又划分成多个小个子，当前只渲染可视区附近区域。**\n\n### 三十一、说一说 HashRouter 和 HistoryRouter 的区别和原理？\n\n**HashRouter和 HistoryRouter的区别： **\n\n1. **history和hash都是利用浏览器的两种特性实现前端路由，history是利用浏览历史记录栈的API实现，hash是监听location对象hash值变化事件来实现 **\n2. **history的url没有\'#\'号，hash反之 **\n3. **相同的url，history会触发添加到浏览器历史记录栈中，hash不会触发，history需要后端配合，如果后端不配合刷新新页面会出现404，hash不需要。 **\n4. **HashRouter的原理：通过**`window.onhashchange`方法获取新URL中hash值，再做进一步处理\n5. **HistoryRouter的原理：通过**`history.pushState`使用它做页面跳转不会触发页面刷新，使用`window.onpopstate` 监听浏览器的前进和后退，再做其他处理\n6. **加分回答 hash模式下url会带有#，需要url更优雅时，可以使用history模式。 需要兼容低版本的浏览器时，建议使用hash模式。 需要添加任意类型数据到记录时，可以使用history模式。**\n\n### 三十二、说一说 new 会发生什么？\n\n`new` 关键字会进行如下的操作：\n\n1. **创建一个空的简单JavaScript对象（即**`{}`）；\n2. **为步骤1新创建的对象添加属性**`__proto__`，将该属性链接至构造函数的原型对象 ；\n3. **将步骤1新创建的对象作为**`this`的上下文 ；\n4. **如果该函数没有返回对象，则返回**`this`。\n5. **加分回答 **`new`关键字后面的构造函数不能是箭头函数。\n\n### 三十三、说一下 token 能放在 cookie 中吗？\n\n1. **能。 token一般是用来判断用户是否登录的，它内部包含的信息有：uid(用户唯一的身份标识)、time(当前时间的时间戳)、sign（签名，token 的前几位以哈希算法压缩成的一定长度的十六进制字符串） **\n2. `token`可以存放在`Cookie`中，`token` 是否过期，应该由后端来判断，不该前端来判断，所以`token`存储在`cookie`中只要不设置`cookie`的过期时间就ok了，如果 `token` 失效，就让后端在接口中返回固定的状态表示`token` 失效，需要重新登录，再重新登录的时候，重新设置 `cookie` 中的 `token` 就行。\n3. **加分回答 token认证流程:**\n   1. **客户端使用用户名跟密码请求登录 **\n   2. **服务端收到请求，去验证用户名与密码 **\n   3. **验证成功后，服务端签发一个 token ，并把它发送给客户端 **\n   4. **客户端接收 token 以后会把它存储起来，比如放在 cookie 里或者 localStorage 里 **\n   5. **客户端每次发送请求时都需要带着服务端签发的 token（把 token 放到 HTTP 的 Header 里） **\n   6. **服务端收到请求后，需要验证请求里带有的 token ，如验证成功则返回对应的数据**\n\n### 三十四、说一说组件通信的方式？\n\n1. **父子组件通信常用props和\\$emit还有\\$refs；**\n   * **父向子传值：通过属性绑定。父组件在引用子组件时，通过属性绑定（v-bind：）的形式，把需要传递给子组件的数据，传递到子组件内部，供子组件使用 。子组件通过props数组接受，props 中的数据都是只读的，无法重新赋值。**\n   * **父向子传递方法：使用事件绑定机制 v-on，自定义一个事件属性，传递给子组件。在子组件中定义一个方法，在方法中，利用 \\$emit 触发 父组件传递过来的，挂载在当前实例上的事件，还可以传递参数。在子组件中调用定义的那个方法，就可以触发父组件传递过来的方法了。**\n   * **子向父传值：通过事件绑定。在子组件中，利用 \\$emit 触发 父组件传递过来的方法的时候，可以将子组件的数据当做参数传递给父组件。**\n2. **兄弟组件通信常用定义的公共事件bus的\\$on、\\$emit；**\n3. **祖先和子孙组件通信常用\\$attrs和\\$listener、provide和inject；**\n4. **复杂通信常用vuex。**\n\n### 三十五、说一说创建 ajax 过程？\n\n1. **创建XML HttpRequest 对象，即创建一个异步调用对象。 **\n2. **创建一个新的HTTP 请求，并指定该HTTP 请求的方法，URL及验证信息 **\n3. **设置响应HTTP请求状态变化的函数。 **\n4. **发送HTTP 请求。 **\n5. **获取异步调用返回的数据。 **\n6. **使用JavaScript和DOM 实现局部刷新。**\n\n### 三十六、说一说 Vue 列表为什么加 key？\n\n1. **为了性能优化。因为vue是虚拟DOM，更新DOM时用diff算法对节点进行一一比对，比如有很多li元素，要在某个位置插入一个li元素，但没有给li上加key，那么在进行运算的时候，就会将所有li元素重新渲染一遍，但是如果有key，那么它就会按照key一一比对li元素，只需要创建新的li元素，插入即可，不需要对其他元素进行修改和重新渲染。 **\n2. **加分回答 key也不能是li元素的index，因为假设我们给数组前插入一个新元素，它的下标是0，那么和原来的第一个元素重复了，整个数组的key都发生了改变，这样就跟没有key的情况一样了。**\n\n### 三十七、说一说 JS 变量提升？\n\n1. **变量提升是指JS的变量和函数声明会在代码编译期，提升到代码的最前面。**\n2. **变量提升成立的前提是使用 var 关键字进行声明的变量，并且变量提升的时候只有声明被提升，赋值并不会被提升，同时函数的声明提升会比变量的提升优先。 **\n3. **变量提升的结果，可以在变量初始化之前访问该变量，返回的是undefined。在函数声明前可以调用该函数。 **\n4. **加分回答 使用 let 和 const 声明的变量是创建提升，形成暂时性死区，在初始化之前访问 let 和 const 创建的变量会报错。**\n\n### 三十八、说一说 v-if 和 v-show区别？\n\n1. **作用: 都是控制元素隐藏和显示的指令 。**\n2. **区别： **\n   * **v-show：控制的元素无论是true还是false，都被渲染出来了，通过display：none控制元素隐藏 。**\n   * **v-if：控制的元素是true则进行渲染，如果是false则不渲染，根本在dom树结构中不显示 。**\n   * **v-show是操作**`display:none`，而v-if是操作Dom直接进行删除和添加，在性能上不及v-show。\n3. **应用： **\n   * **v-show：适合使用在切换频繁显示/隐藏的元素上 。**\n   * **v-if：适合使用在切换不频繁，且元素内容很多，渲染一次性能消耗很大的元素上。**\n', '', 0, 1, '2022-08-28 13:22:31', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (22, '域名备案', '阿里云域名备案为合规运营所需，含准备、填信息、上传资料、审核等流程，要保信息真、材料全，留意核验与地区差异。', '### 为什么要进行域名备案\n\n* **保障互联网信息安全**：备案登记可以让相关部门及时发现和处理违法违规信息，防止不良信息的传播和网络犯罪的发生，保护公民的合法权益，维护社会的稳定和安全.\n* **规范互联网信息传播和使用**：备案登记可以规范互联网信息的传播和使用，防止不良信息的滥发和滥用，促使备案主体更加自觉地遵守法律法规，规范互联网信息服务行为，促进互联网信息服务的健康发展.\n* **遵守法律法规**：根据《互联网信息服务管理办法》规定，所有提供互联网信息服务的单位和个人都必须进行备案登记，备案登记是互联网信息服务单位和个人的法律义务，不进行备案登记将面临行政处罚和法律责任.\n* **便于管理和监管**：备案登记可以让相关部门及时了解备案主体的信息和网站的信息，便于对互联网信息服务行为进行管理和监管，使互联网行业能够更加有序地发展.\n\n### 备案流程\n\n1. **备案前准备**1**3**4：\n   * **注册阿里云账号**：访问阿里云官网，点击 “免费注册” 按钮，按提示输入用户名、密码、手机号等信息完成注册，并进行实名认证。\n   * **准备备案材料**：个人备案需准备身份证正反面照片、域名证书等；企业备案需提供企业营业执照原件及复印件、企业法人身份证正反面照片、备案负责人身份证正反面照片、域名证书等 ，备案负责人手机需下载 “阿里云” APP 。\n   * **购买域名和服务器**：在阿里云域名注册页面搜索并注册所需域名，确保域名已完成实名认证，且有效期大于三个月，并购买阿里云的 ECS 云服务器等产品，购买后系统将自动分配备案服务号。\n2. **登录备案系统填写信息**1：\n   * **登录备案系统**：在阿里云控制台首页，点击右上角 “备案”，选择 “ICP 备案系统” 或直接访问备案入口，使用阿里云账号登录。\n   * **填写备案信息**：根据自身真实信息填写备案信息，包括主办单位信息、网站信息、网站负责人信息等，并点击 “验证备案类型”。\n   * **产品验证**：选择产品类型，如已购买云虚拟主机或 ECS 服务器，系统将自动选取相关备案服务号，无备案服务号则需先购买。\n3. **上传备案资料**：根据提示，在手机移动端上传营业执照、法人身份证、备案负责人身份证等资料，上传成功后点击 “下一步” 进行确认，无误后选择 “提交备案”**1**.\n4. **等待审核**1：\n   * **阿里云初审**：提交备案信息后，阿里云将在 1-2 个工作日内完成初审，初审通过后会收到短信通知，若未通过可查看驳回原因并修改。\n   * **工信部审核**：阿里云初审通过后，备案资料将提交至工信部审核，审核周期大约为 20 个工作日左右，期间可通过阿里云 ICP 代备案平台查看审核进度，且在收到工信部发送的核验短信后，需在 24 小时内完成短信核验 。\n5. **备案成功与后续操作**：工信部审核通过后，网站备案成功，可在阿里云备案管理页面查看备案编号和备案证书，网站可正式上线运营，若网站信息发生变更，需及时更新备案信息，重新提交相关资料并等待审核**1**.\n\n### 注意事项\n\n* **信息真实性**：确保所填写的备案信息真实、准确，使用虚假信息备案将导致失败或被取消资格.\n* **域名和服务器要求**：备案的域名和服务器需在同一个阿里云账号下，且服务器的实名认证和域名的实名认证必须是同一主体**2**4.\n* **备案材料完整性**：按照要求准备齐全所有备案材料，如身份证、营业执照等，材料不完整或不符合要求将导致备案失败.\n* **短信核验及时性**：收到工信部发送的核验短信后，必须在 24 小时内完成短信核验，否则核验无效，会影响备案进度**1**2.\n* **注意备案地域差异**：阿里云服务器的域名备案在不同地区的备案步骤和流程可能会稍有不同，例如上海备案需打开手机定位显示在上海境内，深圳备案负责人需进行阿里云幕布的拍照审核等**3**.\n', '', 0, 1, '2022-09-03 16:29:54', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (23, 'go语言学习笔记', 'go语言学习笔记', '# Go语言基础\n\n参考文档：https://www.topgoer.com/\n\n# 开发环境\n\n## Go安装\n\nGo官网下载地址：https://golang.org/dl/\n\n## 编辑器\n\nvscode\n\n1. 安装插件\n\n   Go for Visual Studio Code\n2. 安装Go语言开发工具包\n\n   Windows平台按下`Ctrl+Shift+P`，输入框中输入>`go:install`，全选工具下载\n\n   下载失败解决方案：复制`Go语言基础\\go_windows`文件夹下的可执行文件，拷贝到 GO安装目录下的bin文件夹`go/bin`\n\n## 第一个go程序\n\n1. 创建`hello_world`文件夹\n2. 初始化Go模块`go mod init hello_world`\n\n   在当前目录下创建一个名为 `go.mod` 的文件，这个文件用来管理模块的依赖关系和版本信息\n3. 在hello_world目录中创建一个`main.go`文件\n\n   ```\n   package main\n\n   import \"fmt\"\n\n   func main() {\n   	fmt.Println(\"Hello World\")\n   }\n   ```\n4. 在hello_world目录下执行`go run main.go`\n5. 在hello_world目录下执行`go build`，生成`hello_world.exe`文件\n6. 执行`hello_world.exe`文件`.\\hello_world.exe`\n\n# Go基础\n\n## Go常用命令\n\nGo语言提供了一系列命令来管理和开发Go项目。以下是Go命令行工具中常用的命令及其功能：\n\n### 模块管理\n\n```\ngo mod init: 初始化一个新的Go模块，并创建 go.mod 文件。\ngo mod tidy: 移除未使用的依赖，并下载缺失的依赖。\ngo mod download: 下载 go.mod 中列出的所有模块依赖。\ngo mod vendor: 将依赖复制到 vendor 目录中。\ngo mod verify: 校验本地模块缓存是否与 go.sum 文件一致。\ngo mod graph: 输出模块的依赖图。\ngo mod why: 解释为什么需要依赖某个模块。\n```\n\n### 构建与测试\n\n```\ngo build: 编译当前模块或包，但不运行。\ngo run: 编译并运行Go程序，通常用于快速测试和开发。\ngo test: 自动化测试工具，运行项目中的测试函数。\ngo clean: 移除编译过程中生成的文件。\ngo install: 编译并安装包和命令到GOPATH或模块的 bin 目录中。\ngo get: 下载并安装远程包，同时更新 go.mod 文件。\n```\n\n### 文档与工具\n\n```\ngo doc: 显示Go包或符号的文档。\ngo fmt: 格式化Go代码，符合Go语言规范。\ngo vet: 静态代码分析工具，检查代码中的潜在问题。\ngo generate: 通过执行源代码中的注释命令生成代码。\ngo tool: 运行指定的Go工具。\ngo list: 列出包的元数据。\ngo version: 显示Go编译器的版本信息。\ngo env: 打印Go环境变量信息。\n```\n\n### 其他命令\n\n```\ngo fix: 更新代码以使用Go语言的最新语法和API。\ngo bug: 打开浏览器并进入Go的错误报告页面。\n```\n\n## 跨平台编译\n\n要使用Go编译不同操作系统下的可执行文件，可以通过设置环境变量 `GOOS` 和 `GOARCH` 来实现（用于指定编译时的目标操作系统和目标架构）。\n\n在Windows上使用PowerShell或CMD时，环境变量的设置方式与Unix系统不同。\n\n使用 `set` 命令在CMD中设置环境变量：\n\n```cmd\nset GOOS=linux\nset GOARCH=amd64\ngo build -o hello_world\n```\n\n使用 `$env` 在PowerShell中设置环境变量：\n\n```powershell\n$env:GOOS=\"linux\"\n$env:GOARCH=\"amd64\"\ngo build -o hello_world\n```\n\n以下是在**PowerShell**中分别为Windows、macOS和Linux编译可执行文件的命令。\n\n### 编译Windows可执行文件\n\n```\n$env:GOOS=\"windows\"; $env:GOARCH=\"amd64\"; go build -o hello_world\n```\n\n### 编译macOS可执行文件\n\n```\n$env:GOOS=\"darwin\"; $env:GOARCH=\"amd64\"; go build -o hello_world\n```\n\n### 编译Linux可执行文件\n\n```\n$env:GOOS=\"linux\"; $env:GOARCH=\"amd64\"; go build -o hello_world\n```\n\n## Go语言特征\n\n### 命名\n\n1. Go的函数、变量、常量、自定义类型、包`(package)`的命名方式遵循以下规则\n\n   ```\n   1）首字符可以是任意的Unicode字符或者下划线\n   2）剩余字符可以是Unicode字符、下划线、数字\n   3）字符长度不限\n   ```\n2. Go只有25个关键字\n\n   ```\n    break        default      func         interface    select\n    case         defer        go           map          struct\n    chan         else         goto         package      switch\n    const        fallthrough  if           range        type\n    continue     for          import       return       var\n   ```\n3. Go有37个保留字\n\n   ```\n   Constants:    true  false  iota  nil\n\n   Types:    int  int8  int16  int32  int64  \n             uint  uint8  uint16  uint32  uint64  uintptr\n             float32  float64  complex128  complex64\n             bool  byte  rune  string  error\n\n   Functions:   make  len  cap  new  append  copy  close  delete\n                complex  real  imag\n                panic  recover\n   ```\n4. 可见性\n\n   ```\n    1）声明在函数内部，是函数的本地值，类似private\n    2）声明在函数外部，是对当前包可见(包内所有.go文件都可见)的全局值，类似protect\n    3）声明在函数外部且首字母大写是所有包可见的全局值,类似public\n   ```\n\n### 声明\n\n有四种主要声明方式\n\n```\n var（声明变量）, const（声明常量）, type（声明类型） ,func（声明函数）\n```\n\n## 内置类型和函数\n\n### 内置类型\n\n#### 值类型\n\n基本类型（布尔型、数字型）、字符串、数组、结构体。\n\n```\n基本类型：\n    布尔类型型：bool\n    数字类型：\n        整型：int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, uintptr\n        浮点型：float32, float64\n        复数类型：complex64, complex128\n    字符类型(golang中没有专门的字符类型,存放单个ascii字符,一般用byte保存,单个汉字一般用int来保存)：\n    	byte（uint8 的别名）\n    	rune（int32 的别名，用于表示 Unicode 码点）\n字符串：string\n数组：array，如 [5]int 表示长度为5的整数数组。\n结构体：struct，如 type Person struct { Name string; Age int }。\n接口类型：interface{}\n```\n\n#### 引用类型\n\n切片、映射、通道、指针、函数类型。\n\n```\n切片：slice\n[]int：表示一个整数切片。切片实际上是对底层数组的一种引用。\n映射：map\nmap[string]int：表示键为字符串、值为整数的映射。\n通道(管道)：chan\nchan int：表示一个传输整数类型的通道，用于Goroutine之间的通信。\n指针：*\n*int：表示指向整数类型的指针。指针是直接引用内存地址的类型。\n函数类型：func\nfunc(int, int) int：表示一个函数类型，函数在Go中也是一种引用类型。\n```\n\n#### 类型默认值\n\n在Go语言中，各个类型都有默认的零值，当变量声明但未显式初始化时，会自动赋予这个默认值。下面是各个常见类型的默认值：\n\n```\n基本类型：\n    布尔类型型：false\n    数字类型：\n        整型：0\n        浮点型：0.0\n        复数类型：0\n    字符类型：\n    	byte：0\n    	rune：0\n  \n派生类型：\n	字符串：\"\"\n	指针类型：默认值是 nil（表示空指针）。\n	数组：默认值是数组元素全为零值的数组，例如 [3]int 的默认值是 [0, 0, 0]。\n	切片：默认值是 nil（表示空切片），而不是空数组。\n	映射：默认值是 nil（表示空映射）\n	管道：默认值是 nil（表示空通道）\n	结构体：结构体的每个字段都被初始化为相应类型的零值，因此结构体的默认值是所有字段都为零值的结构体。\n	接口类型：默认值是 nil（表示空接口）\n```\n\n\n| 类型          | 长度(字节) | 默认值 | 说明                                      |\n| ------------- | ---------- | ------ | ----------------------------------------- |\n| bool          | 1          | false  |                                           |\n| byte          | 1          | 0      | uint8                                     |\n| rune          | 4          | 0      | Unicode Code Point, int32                 |\n| int, uint     | 4或8       | 0      | 32 或 64 位                               |\n| int8, uint8   | 1          | 0      | -128 ~ 127, 0 ~ 255，byte是uint8 的别名   |\n| int16, uint16 | 2          | 0      | -32768 ~ 32767, 0 ~ 65535                 |\n| int32, uint32 | 4          | 0      | -21亿~ 21亿, 0 ~ 42亿，rune是int32 的别名 |\n| int64, uint64 | 8          | 0      |                                           |\n| float32       | 4          | 0.0    |                                           |\n| float64       | 8          | 0.0    |                                           |\n| complex64     | 8          |        |                                           |\n| complex128    | 16         |        |                                           |\n| uintptr       | 4或8       |        | 以存储指针的 uint32 或 uint64 整数        |\n| array         |            |        | 值类型                                    |\n| struct        |            |        | 值类型                                    |\n| string        |            | \"\"     | UTF-8 字符串                              |\n| slice         |            | nil    | 引用类型                                  |\n| map           |            | nil    | 引用类型                                  |\n| channel       |            | nil    | 引用类型                                  |\n| interface     |            | nil    | 接口                                      |\n| function      |            | nil    | 函数                                      |\n\n### 内置函数\n\nGo语言提供了一些方便的内置函数，这些函数不需要导入任何包即可使用：\n\n```\n- **类型相关**：\n  - `new(T)`：创建一个类型为`T`的指针，并将分配的内存初始化为零值。\n  - `make(T, args)`：分配和初始化切片、映射或通道类型的实例。\n- **长度和容量**：\n  - `len(v)`：返回数组、切片、映射、字符串、通道的长度。\n  - `cap(v)`：返回数组、切片或通道的容量。\n- **内存管理**：\n  - `copy(dst, src)`：将`src`切片的元素复制到`dst`切片，返回复制的元素个数。\n  - `append(slice, elems...)`：将元素追加到切片后，返回新的切片。\n- **类型转换**：\n  - `complex(r, i)`：创建一个复数，实部为`r`，虚部为`i`。\n  - `real(c)`：返回复数`c`的实部。\n  - `imag(c)`：返回复数`c`的虚部。\n- **数学计算**：\n  - `close(c)`：关闭通道`c`，用于发送方不再发送数据的场景。\n- **反射和类型断言**：\n  - `panic(v)`：引发一个运行时错误，并终止程序的执行。\n  - `recover()`：用于从`panic`中恢复，通常与`defer`语句一起使用。\n```\n\n## 流程控制\n\n### 条件语句：if\n\n```\nif n := 0; n >0  {\n	println(\"正数\")\n} else if n < 0 {\n	println(\"负数\")\n} else {\n	println(\"零\")\n}\n```\n\n在Go语言中，`if n := 0; n >0` 这种写法是一种在`if`语句中声明和初始化变量的方式，n的作用域仅限于该 `if` 语句的范围内。\n\n*注意：go语言不支持三元操作符(三目运算符) \"a > b ? a : b\"*\n\n### 条件语句：switch\n\n```\nswitch var1 {\n    case val1:\n        ...\n    case val2:\n        ...\n    default:\n        ...\n}\n```\n\n### 条件语句：select\n\nselect 语句类似于 switch 语句，但是select会随机执行一个可运行的case。如果没有case可运行，它将阻塞，直到有case可运行。\n\n```\nselect {\n    case communication clause  :\n       statement(s);    \n    case communication clause  :\n       statement(s);\n    /* 你可以定义任意数量的 case */\n    default : /* 可选 */\n       statement(s);\n}\n```\n\n### 循环语句：for\n\nGolang for支持三种循环方式，包括类似 while 的语法\n\n```\ns := \"abc\"\n\n1.\nfor i, n := 0, len(s); i < n; i++ { // 常见的 for 循环，支持初始化语句。\n    println(s[i])\n}\n\n2.\nn := len(s)\nfor n > 0 {                // 替代 while (n > 0) {}\n    println(s[n])        // 替代 for (; n > 0;) {}\n    n-- \n}\n\n3.\nfor {                    // 替代 while (true) {}\n    println(s)            // 替代 for (;;) {}\n}\n```\n\n### 循环语句：for...range\n\nGolang range类似迭代器操作，返回 (索引, 值) 或 (键, 值)。\n\nfor 循环的 range 格式可以对 slice、map、数组、字符串等进行迭代循环。格式如下：\n\n```\nfor key, value := range oldMap {\n    newMap[key] = value\n}\n```\n\n### 循环控制goto、break、continue\n\n**goto：**`goto` 语句用于跳转到代码中的指定标签。它可以用来在任意位置转到特定标签，但使用时需要谨慎，因为不当使用 `goto` 可能会导致代码的可读性差和难以维护。\n\n```\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    i := 0\nloop:\n    if i >= 5 {\n        goto end // 跳转到 end 标签\n    }\n    fmt.Println(i)\n    i++\n    goto loop // 跳转回 loop 标签\nend:\n    fmt.Println(\"Done\")\n}\n```\n\n**break：**`break` 语句用于退出当前循环（`for`、`switch` 或 `select`）。当 `break` 被执行时，循环立即终止，不会继续执行循环体内的后续代码。\n\n**continue：**`continue` 语句用于跳过当前循环的剩余部分，直接开始下一次迭代。`continue` 只会影响包含它的最近的循环。\n\n## 函数\n\n## 方法\n\n# 面向对象\n\n# 网络编程\n\n# 并发编程\n\n# 数据操作\n\n# gin框架\n', '', 0, 1, '2022-11-17 19:31:31', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (24, '重装系统操作流程', '重装系统，看这一篇就够了', '# 重装系统操作流程\n\n## 一、制作安装U盘\n\n### 1 下载官方安装工具\n\n点击链接：https://www.microsoft.com/zh-cn/software-download，根据不同版本选择对应的安装工具，本文示例安装windows10系统。\n\n![1733196392828254616.png](https://micefind.com:8080/static/image/1733196392828254616.png)\n\n下载地址：https://www.microsoft.com/zh-cn/software-download/windows10，进入页面点击 `立即下载`。\n\n![1733195212644660542.png](https://micefind.com:8080/static/images/1733195212644660542.png)\n\n### 2 通过安装工具制作U盘\n\n打开安装工具，点击 `接受。`\n\n![1733195449612393193.png](https://micefind.com:8080/static/images/1733195449612393193.png)\n\n选择 `为另一台电脑创建安装介质`\n\n![1733195558859983426.png](https://micefind.com:8080/static/images/1733195558859983426.png)\n\n一般使用，选择 `windows10 家庭中文版`就行。\n\n![1733195784103823000.png](https://micefind.com:8080/static/images/1733195784103823000.png)\n\n介质选择 `U盘`，安装时会清空U盘文件，请提前做好备份。\n\n![1733195941937560796.png](https://micefind.com:8080/static/images/1733195941937560796.png)\n\n![1733196115523524662.png](https://micefind.com:8080/static/images/1733196115523524662.png)\n\n等待下载完毕。\n\n![1733196568649043452.png](https://micefind.com:8080/static/images/1733196568649043452.png)\n\n点击完成，安装U盘已经制作完毕。使用这个U盘就可以随时重装系统了。\n\n![1733196686278267911.png](https://micefind.com:8080/static/images/1733196686278267911.png)\n\nU盘目录，此时这个U盘只能用于重装系统。重装系统完成后，可将U盘文件备份，U盘就可以继续使用。后面需要重装系统时将备份文件重新拷回U盘根目录就行。\n\n![1733196936005520379.png](https://micefind.com:8080/static/images/1733196936005520379.png)\n\n## 二、重装系统\n\n### 1 快捷键选择从U盘启动\n\n电脑开机默认从硬盘启动，重装系统需要从U盘启动。插好安装U盘，电脑关机状态下点击电脑开机键，然后快速连续点击快捷键进入U盘启动界面。\n\n不同品牌电脑开机启动对应不同快捷键，选择对应的快捷键就行。总结一下目前主流电脑、笔记本、DIY组装机的启动快捷键，方便使用：\n\n1. 笔记本电脑启动快捷键\n\n![1733198122184766598.jpg](https://micefind.com:8080/static/images/1733198122184766598.jpg)\n\n2. DIY电脑启动快捷键\n\n![1733198155614785402.jpg](https://micefind.com:8080/static/images/1733198155614785402.jpg)\n\n3. 品牌电脑启动快捷键\n\n![1733198176541951934.jpg](https://micefind.com:8080/static/images/1733198176541951934.jpg)\n', '', 0, 1, '2022-11-28 19:13:52', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
