INSERT INTO `article` VALUES (43, '前端导入导出excel', '导出excel', '```\nimport * as XLSX from \"xlsx\"\n\n// 导出\nexport function exportExcel(list, fileName) {\n  const ws = XLSX.utils.json_to_sheet(list)\n  /* 新建空workbook */\n  const wb = XLSX.utils.book_new()\n  /* 添加worksheet，当然你可以添加多个，这里我只添加一个 */\n  XLSX.utils.book_append_sheet(wb, ws, \"result\")\n\n  const wbout = XLSX.write(wb, {\n    bookType: \"xlsx\",\n    bookSST: true,\n    type: \"array\",\n  })\n  let url = window.URL.createObjectURL(new Blob([wbout]))\n  let link = document.createElement(\"a\")\n  link.style.display = \"none\"\n  link.href = url\n  link.setAttribute(\"download\", fileName + \".xlsx\")\n  document.body.appendChild(link)\n  link.click()\n  document.body.removeChild(link) //下载完成移除元素\n  window.URL.revokeObjectURL(url) //释放掉blob对象\n}\n\n// 导入\nexport function importExcel(file) {\n  return new Promise((resolve, reject) => {\n    const reader = new FileReader()\n    reader.onload = (e) => {\n      const data = new Uint8Array(e.target.result)\n      const workbook = XLSX.read(data, { type: \"array\" })\n      const sheetName = workbook.SheetNames[0]\n      const worksheet = workbook.Sheets[sheetName]\n      const jsonData = XLSX.utils.sheet_to_json(worksheet)\n      let list = jsonData.map((item) => {\n        return {\n          title: item[\"题目\"]?.toString(),\n          option_a: item[\"选项A\"]?.toString(),\n          option_b: item[\"选项B\"]?.toString(),\n          option_c: item[\"选项C\"]?.toString(),\n          answer: item[\"答案\"]?.toString(),\n          analysis: item[\"解析\"]?.toString(),\n        }\n      })\n      resolve(list)\n    }\n    reader.onerror = (error) => reject(error)\n    reader.readAsArrayBuffer(file)\n  })\n}\n\n```\n', '', 0, 1, '2025-01-06 13:58:27', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (44, 'vue后台管理：动态路由，解决刷新页面空白或跳404问题', '本文阐述在 Vue3 项目中实现动态路由的关键问题，详细介绍利用 Pinia 和 Vue-Router 的全过程，包括数据请求、状态管理、路由配置与添加，解决刷新跳 404 问题，提升开发效率。', '# vue后台管理：动态路由，解决刷新页面空白或跳404问题\n\n### 前言\n\n开发后台管理系统时，有时后端会根据权限返回不同的菜单列表，前端需要异步获取数据然后实时生成路由配置。\n\n在vue3项目中，我们使用pinia、vue-router实现动态路由，关键步骤如下：\n\n1. 异步请求获取路由接口数据；\n2. pinia状态管理保存路由信息；\n3. vue-router实现路由配置；\n4. 动态添加路由。\n\n### 1 异步请求获取路由接口数据\n\n```\n// /src/api/route.js\nexport const getRouteList = () => {\n  // 模拟异步请求\n  return new Promise((resolve) => {\n    setTimeout(() => {\n      resolve([\n        {\n          name: \"home\",\n          path: \"/home\",\n          meta: { title: \"首页\" },\n        },\n        {\n          name: \"user\",\n          path: \"/user\",\n          meta: { title: \"用户\" },\n        },\n      ])\n    }, 1000)\n  })\n}\n```\n\n### 2 pinia状态管理保存路由信息\n\n```\n// /src/store/route.js\nimport { defineStore } from \"pinia\"\n\nexport const useRouteStore = defineStore(\"route\", {\n  state: () => ({\n    routeList: sessionStorage.getItem(\"routeList\")\n      ? JSON.parse(sessionStorage.getItem(\"routeList\"))\n      : [],\n    isUpdate: false,\n  }),\n  actions: {\n    updateRouteList(routeList) {\n      this.routeList = routeList\n      sessionStorage.setItem(\"routeList\", JSON.stringify(routeList))\n      this.isUpdate = true\n    },\n  },\n  getters: {},\n})\n```\n\n### 3 vue-router实现路由配置\n\n```\nimport { createRouter, createWebHashHistory } from \"vue-router\"\n\n// 定义基本路由配置\nconst routes = [\n  {\n    path: \"/:pathMatch(.*)\",\n    meta: { title: \"404\" },\n    name: \"404\",\n    component: () => import(\"@/views/error/404.vue\"),\n  },\n  {\n    path: \"/login\",\n    name: \"login\",\n    component: () => import(\"@/views/login/Login.vue\"),\n    meta: { title: \"登录\" },\n  },\n  {\n    path: \"/\",\n    name: \"layout\",\n    component: () => import(\"@/views/layout/Layout.vue\"),\n    redirect: \"/home\",\n    children: [], // 初始时没有子路由\n  },\n]\n\nexport const router = createRouter({\n  history: createWebHashHistory(import.meta.env.BASE_URL),\n  routes,\n})\n\n// 路由守卫，用于处理路由跳转前的逻辑\nrouter.beforeEach(async (to, from, next) => {\n  // 判断是否已登录且没有 token，未登录时重定向到登录页\n  const token = localStorage.getItem(\"token\")\n  if (to.path !== \"/login\" && !token) {\n    return next({ name: \"login\" })\n  }\n  next()\n})\n```\n\n### 4 动态添加路由\n\n核心代码\n\n```\nrouter.addRoute(\"layout\", {\n	path: item.path,\n	name: item.name,\n	component: () => import(`@/views/${item.name}/index.vue`),\n})\n```\n\n完整代码\n\n```\n// /src/router/index.js\nimport { createRouter, createWebHashHistory } from \"vue-router\"\nimport { useRouteStore } from \"@/store/route\"\nimport { getRouteList } from \"@/api/route\"\n\n// 定义基本路由配置\nconst routes = [\n  {\n    path: \"/:pathMatch(.*)\",\n    meta: { title: \"404\" },\n    name: \"404\",\n    component: () => import(\"@/views/error/404.vue\"),\n  },\n  {\n    path: \"/login\",\n    name: \"login\",\n    component: () => import(\"@/views/login/Login.vue\"),\n    meta: { title: \"登录\" },\n  },\n  {\n    path: \"/\",\n    name: \"layout\",\n    component: () => import(\"@/views/layout/Layout.vue\"),\n    redirect: \"/home\",\n    children: [], // 初始时没有子路由\n  },\n]\n\nexport const router = createRouter({\n  history: createWebHashHistory(import.meta.env.BASE_URL),\n  routes,\n})\n\n// 添加动态路由\nconst addRoute = () => {\n  const routeStore = useRouteStore()\n  if (routeStore.isUpdate) {\n    routeStore.routeList.forEach((item) => {\n      if (!router.hasRoute(item.name)) {\n        router.addRoute(\"layout\", {\n          path: item.path,\n          name: item.name,\n          component: () => import(`@/views/${item.name}/index.vue`),\n        })\n      }\n    })\n    routeStore.isUpdate = false\n  }\n}\n\n// 初始化路由\nexport const initRouter = async () => {\n  let routeList = sessionStorage.getItem(\"routeList\")\n    ? JSON.parse(sessionStorage.getItem(\"routeList\"))\n    : await getRouteList()\n  const routeStore = useRouteStore()\n  routeStore.updateRouteList(routeList)\n  addRoute()\n}\n\n// 路由守卫，用于处理路由跳转前的逻辑\nrouter.beforeEach(async (to, from, next) => {\n  // 添加动态路由\n  addRoute()\n  // 判断是否已登录且没有 token，未登录时重定向到登录页\n  const token = localStorage.getItem(\"token\")\n  if (to.path !== \"/login\" && !token) {\n    return next({ name: \"login\" })\n  }\n  next()\n})\n```\n\n注意：动态添加路由后刷新页面会跳转404页面，因为在进路由守卫之前，程序已经进行了路由匹配，结果就是没匹配到任何内容。\n\n解决方案：在router注册之前调用initRouter函数初始化路由。\n\n```\n// main.js\nimport \"./assets/css/main.css\"\n\nimport { createApp } from \"vue\"\nimport { createPinia } from \"pinia\"\nimport App from \"./App.vue\"\nimport { initRouter, router } from \"./router\"\n\nconst app = createApp(App)\n\nconst call = async () => {\n  app.use(createPinia())\n  await initRouter()\n  app.use(router)\n\n  app.mount(\"#app\")\n}\ncall()\n\n```\n\ngitee地址：https://gitee.com/micefind/vue3-dynamic-routing\n', '', 0, 1, '2025-01-21 15:24:55', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (45, 'vue后台管理：页面布局切换', '开发后台管理时，有时会根据业务采用不同布局模式，常见的页面布局包括单侧边栏布局、双侧边栏布局、双栏布局和顶栏浮动布局。', '# vue后台管理：页面布局切换\n\n### 前言\n\n开发后台管理时，有时会根据业务采用不同布局模式，常见的页面布局包括单侧边栏布局、双侧边栏布局、双栏布局和顶栏浮动布局。\n\n也可以让用户自行选择切换页面布局，感觉很有趣，实现起来其实也很简单，在vue项目中只需要使用`is`来渲染动态组件。\n\n关键步骤如下：\n\n1. pinia保存布局模式\n2. 页面布局使用is动态渲染组件\n3. 设置切换布局模式\n\n### 1 pinia保存布局模式\n\n```\nimport { defineStore } from \"pinia\"\n\nexport const useSettingStore = defineStore(\"setting\", {\n  state: () => {\n    return {\n      layoutMode: localStorage.getItem(\"layoutMode\") || \"Classic\",\n    }\n  },\n  actions: {\n    setLayoutMode(layoutMode) {\n      this.layoutMode = layoutMode\n      localStorage.setItem(\"layoutMode\", layoutMode)\n    },\n  },\n})\n\n```\n\n### 2 页面布局使用is动态渲染组件\n\n```\n<script setup>\nimport Classic from \"@/views/layout/classic/index.vue\"\nimport Streamline from \"@/views/layout/streamline/index.vue\"\nimport { useSettingStore } from \"@/store/setting.js\"\nconst settingStore = useSettingStore()\nimport { computed } from \"vue\"\n\nconst layoutEnum = {\n  Classic: Classic, //经典布局\n  Streamline: Streamline, //单栏布局\n}\nconst layoutMode = computed(() => layoutEnum[settingStore.layoutMode])\n</script>\n\n<template>\n  <component :is=\"layoutMode\" />\n</template>\n\n<style scoped></style>\n```\n\n### 3 设置切换布局模式\n\n```\n<script setup>\nimport { useSettingStore } from \"@/store/setting\"\n\nconst settingStore = useSettingStore()\nconst changeLayout = (layout) => {\n  settingStore.setLayoutMode(layout)\n}\n</script>\n\n<template>\n  <button @click=\"changeLayout(\'Classic\')\">经典布局</button>\n  <button @click=\"changeLayout(\'Streamline\')\">单栏布局</button>\n</template>\n\n<style scoped lang=\"scss\"></style>\n\n```\n\n代码gitee地址：https://gitee.com/micefind/page-layout-switching\n', '', 0, 1, '2025-01-22 11:03:11', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (46, 'go语言通过SDK连接华为云OBS：创建桶，上传和下载对象', 'obs', '### 创建桶\n\n```\npackage main\n\nimport (\n	\"fmt\"\n\n	obs \"github.com/huaweicloud/huaweicloud-sdk-go-obs/obs\"\n)\n\nfunc main() {\n    ak := \"你的ak\"\n    sk := \"你的sk\"\n  \n    // 填写Bucket对应的Endpoint，以华南-广州为例\n    endPoint := \"https://obs.cn-south-1.myhuaweicloud.com\"\n  \n    // 创建obsClient实例\n    obsClient, err := obs.New(ak, sk, endPoint/*, obs.WithSecurityToken(securityToken)*/)\n    if err != nil {\n        fmt.Printf(\"创建obsClient失败，错误信息: %s\", err.Error())\n    }\n\n    input := &obs.CreateBucketInput{}\n    input.Bucket = \"micefind\" // 指定存储桶名称\n    input.Location = \"cn-south-1\"  // 指定存储桶区域，需与Endpoint一致\n    input.ACL = obs.AclPrivate    // 设置存储桶权限为私有\n    input.AvailableZone = \"3az\"   // 设置存储桶为多AZ类型\n\n    // 检查存储桶是否已存在\n	_, err = obsClient.HeadBucket(input.Bucket)\n	if err == nil {\n		fmt.Printf(\"存储桶 %s 已存在，请使用其他名称\\n\", input.Bucket)\n		return\n	} else if obsError, ok := err.(obs.ObsError); ok && obsError.StatusCode != 404 {\n		// 如果错误不是 404（存储桶不存在），则打印错误信息\n		fmt.Printf(\"检查存储桶 %s 失败，错误信息: %s\\n\", input.Bucket, obsError.Error())\n		return\n	}\n\n    // 创建存储桶\n    output, err := obsClient.CreateBucket(input)\n    if err == nil {\n        fmt.Printf(\"创建存储桶:%s 成功！\\n\", input.Bucket)\n        fmt.Printf(\"请求ID:%s\\n\", output.RequestId)\n        return\n    }\n\n    fmt.Printf(\"创建存储桶:%s 失败！\\n\", input.Bucket)\n    if obsError, ok := err.(obs.ObsError); ok {\n        fmt.Println(\"请求被OBS拒绝，返回错误响应。\")\n        fmt.Println(obsError.Error())\n    } else {\n        fmt.Println(\"客户端遇到内部问题，例如网络无法访问。\")\n        fmt.Println(err)\n    }\n}\n```\n\n### 上传对象\n\n```\npackage main\n\nimport (\n	\"fmt\"\n	\"os\"\n\n	obs \"github.com/huaweicloud/huaweicloud-sdk-go-obs/obs\"\n)\n\nfunc main() {\n	ak := \"你的ak\"\n    sk := \"你的sk\"\n\n	// 填写 Bucket 对应的 Endpoint，以华南-广州为例\n	endPoint := \"https://obs.cn-south-1.myhuaweicloud.com\"\n\n	// 创建 obsClient 实例\n	obsClient, err := obs.New(ak, sk, endPoint)\n	if err != nil {\n		fmt.Printf(\"创建 obsClient 失败，错误信息: %s\\n\", err.Error())\n		return\n	}\n\n	// 指定存储桶名称\n	bucketName := \"micefind\"\n\n	// 检查存储桶是否已存在\n	_, err = obsClient.HeadBucket(bucketName)\n	if err != nil {\n		if obsError, ok := err.(obs.ObsError); ok {\n			fmt.Printf(\"检查存储桶 %s 失败，错误信息: %s\\n\", bucketName, obsError.Error())\n		} else {\n			fmt.Printf(\"检查存储桶 %s 失败，错误信息: %s\\n\", bucketName, err.Error())\n		}\n		return\n	}\n\n	// 指定对象名称（即文件在 OBS 中的路径）\n	objectKey := \"gif.gif\"\n\n	// 指定本地文件路径（需要上传的文件）\n	localFilePath := \"gif.gif\"\n\n	// 打开本地文件\n	file, err := os.Open(localFilePath)\n	if err != nil {\n		fmt.Printf(\"打开本地文件 %s 失败，错误信息: %s\\n\", localFilePath, err.Error())\n		return\n	}\n	defer file.Close()\n\n	// 创建 PutObjectInput 实例\n	input := &obs.PutObjectInput{}\n	input.Bucket = bucketName\n	input.Key = objectKey\n	input.Body = file // 设置文件内容\n	input.ContentType = \"image/gif\"\n\n	// 上传对象\n	output, err := obsClient.PutObject(input)\n	if err != nil {\n		fmt.Printf(\"上传对象 %s 到存储桶 %s 失败，错误信息: %s\\n\", objectKey, bucketName, err.Error())\n		return\n	}\n\n	// 打印上传结果\n	fmt.Printf(\"上传对象 %s 到存储桶 %s 成功！\\n\", objectKey, bucketName)\n	fmt.Printf(\"请求ID: %s\\n\", output.RequestId)\n	fmt.Printf(\"ETag: %s\\n\", output.ETag)\n}\n```\n\n### 下载对象\n\n```\npackage main\n\nimport (\n	\"fmt\"\n	\"io\"\n	\"net/http\"\n	\"strings\"\n\n	obs \"github.com/huaweicloud/huaweicloud-sdk-go-obs/obs\"\n)\n\nfunc getImageFromOBS(w http.ResponseWriter, r *http.Request) {\n	// 从 URL 中获取文件名（Key）\n	key := strings.TrimPrefix(r.URL.Path, \"/image/\")\n\n	if key == \"\" {\n		http.Error(w, \"缺少文件名\", http.StatusBadRequest)\n		return\n	}\n\n	// OBS 配置\n	ak := \"你的ak\"\n    sk := \"你的sk\"\n	endPoint := \"https://obs.cn-south-1.myhuaweicloud.com\"\n\n	// 创建 OBS 客户端\n	obsClient, err := obs.New(ak, sk, endPoint)\n	if err != nil {\n		http.Error(w, fmt.Sprintf(\"创建 obsClient 失败: %s\", err.Error()), http.StatusInternalServerError)\n		return\n	}\n\n	// 获取图片的配置\n	input := &obs.GetObjectInput{\n		\n	}\n	input.Bucket = \"micefind\"\n	input.Key = key\n\n	// 获取图片\n	output, err := obsClient.GetObject(input)\n	if err != nil {\n		http.Error(w, fmt.Sprintf(\"获取图片失败: %s\", err.Error()), http.StatusInternalServerError)\n		return\n	}\n	defer output.Body.Close()\n\n	// 根据文件扩展名设置响应的 Content-Type\n	contentType := \"application/octet-stream\" // 默认类型\n	if strings.HasSuffix(key, \".gif\") {\n		contentType = \"image/gif\"\n	} else if strings.HasSuffix(key, \".jpg\") || strings.HasSuffix(key, \".jpeg\") {\n		contentType = \"image/jpeg\"\n	} else if strings.HasSuffix(key, \".png\") {\n		contentType = \"image/png\"\n	}\n\n	// 设置响应头为图片类型\n	w.Header().Set(\"Content-Type\", contentType)\n	w.WriteHeader(http.StatusOK)\n\n	// 将图片内容写入响应\n	_, err = io.Copy(w, output.Body)\n	if err != nil {\n		http.Error(w, fmt.Sprintf(\"写入响应失败: %s\", err.Error()), http.StatusInternalServerError)\n		return\n	}\n\n	// 成功提供图片\n	fmt.Printf(\"图片 %s 已成功提供给客户端\\n\", key)\n}\n\nfunc main() {\n	// 设置路由和处理函数\n	http.HandleFunc(\"/image/\", getImageFromOBS)\n\n	// 启动 HTTP 服务\n	port := \":8080\"\n	fmt.Printf(\"服务启动在 %s\\n\", port)\n	if err := http.ListenAndServe(port, nil); err != nil {\n		fmt.Printf(\"服务启动失败: %s\\n\", err.Error())\n	}\n}\n```\n\n\n\n', '', 0, 1, '2025-02-28 15:16:21', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (47, 'go语言sdk实现微信支付', 'nn', '# 文章标题\n\n![923758.gif](static\\image\\1749535086108501500.gif)\n\n## title1\n\n### 1、二级标题\n\n![公众号【猪猪宝库】 (121).jpg](static\\image\\1749544497164646500.jpg)\n\n\n1. 32222\n2. 3333\n\n### 2、二级标题\n\n## title2\n\n### 1、二级标题\n\n### 2、二级标题\n\n1. 111222\n2. 333\n\n- 22222\n- 3333\n- 444\n- 222\n\n```\nfdsnkjnkjansjknjkanjk njkan2133223\n333\n444444444\n3\n3\n33\n33\n```\n\n## title3\n\n### 1、二级标题\n\n1. 1111\n2. 222\n3. 333\n4. 3\n\n```\n\naeakenjnjk\nenjnjk\nenwknjk\n\n```\n\n挖到\n\n44\n\n4\n\n444\n\n4\n\n44\n\n4\n\n4\n\n4\n\n4\n\n4\n\n4\n\n4\n\n4\n\n4\n\n44\n\n4\n\n4\n\n44\n\n4\n\n44\n\n44\n\n4\n\n44\n\n4\n\n4\n\n4\n\n4\n\n4\n\n4\n\n44\n\n4\n\n## title4\n\n`jj`\n\nbb\n', '', 0, 1, '2025-03-05 17:59:35', 1, '2025-06-10 17:43:32', 1, 0, 1, 1);
INSERT INTO `article` VALUES (48, '个计点在农晶科科技那就是低年级困哪刷3333333333333333333333卡机到哪打卡机你金卡', '要使用Go编译不同操作系统下的可执行文件，可以通过设置环境变量 `GOOS` 和 `GOARCH` 来实现（用于指定编译时的目标操作系统和目标架构）。\n\n在Windows上使用PowerShell或CMD时，环境变量的设置方式与Unix系统不同。\n\n使用 `set` 命令在CMD中设置环境变量：', '# Go语言基础\n\n参考文档：https://www.topgoer.com/\n\n![923758.gif](static\\image\\1748238129007085700.gif)\n\n\n# 开发环境\n\n## Go安装\n\nGo官网下载地址：https://golang.org/dl/\n\n## 编辑器\n\nvscode\n\n1. 安装插件\n\n   Go for Visual Studio Code\n2. 安装Go语言开发工具包\n\n   Windows平台按下`Ctrl+Shift+P`，输入框中输入>`go:install`，全选工具下载\n\n   下载失败解决方案：复制`Go语言基础\\go_windows`文件夹下的可执行文件，拷贝到 GO安装目录下的bin文件夹`go/bin`\n\n## 第一个go程序\n\n1. 创建`hello_world`文件夹\n2. 初始化Go模块`go mod init hello_world`\n\n   在当前目录下创建一个名为 `go.mod` 的文件，这个文件用来管理模块的依赖关系和版本信息\n3. 在hello_world目录中创建一个`main.go`文件\n\n   ```\n   package main\n\n   import \"fmt\"\n\n   func main() {\n   	fmt.Println(\"Hello World\")\n   }\n   ```\n4. 在hello_world目录下执行`go run main.go`\n5. 在hello_world目录下执行`go build`，生成`hello_world.exe`文件\n6. 执行`hello_world.exe`文件`.\\hello_world.exe`\n\n# Go基础\n\n## Go常用命令\n\nGo语言提供了一系列命令来管理和开发Go项目。以下是Go命令行工具中常用的命令及其功能：\n\n### 模块管理\n\n```\ngo mod init: 初始化一个新的Go模块，并创建 go.mod 文件。\ngo mod tidy: 移除未使用的依赖，并下载缺失的依赖。\ngo mod download: 下载 go.mod 中列出的所有模块依赖。\ngo mod vendor: 将依赖复制到 vendor 目录中。\ngo mod verify: 校验本地模块缓存是否与 go.sum 文件一致。\ngo mod graph: 输出模块的依赖图。\ngo mod why: 解释为什么需要依赖某个模块。\n```\n\n### 构建与测试\n\n```\ngo build: 编译当前模块或包，但不运行。\ngo run: 编译并运行Go程序，通常用于快速测试和开发。\ngo test: 自动化测试工具，运行项目中的测试函数。\ngo clean: 移除编译过程中生成的文件。\ngo install: 编译并安装包和命令到GOPATH或模块的 bin 目录中。\ngo get: 下载并安装远程包，同时更新 go.mod 文件。\n```\n\n### 文档与工具\n\n```\ngo doc: 显示Go包或符号的文档。\ngo fmt: 格式化Go代码，符合Go语言规范。\ngo vet: 静态代码分析工具，检查代码中的潜在问题。\ngo generate: 通过执行源代码中的注释命令生成代码。\ngo tool: 运行指定的Go工具。\ngo list: 列出包的元数据。\ngo version: 显示Go编译器的版本信息。\ngo env: 打印Go环境变量信息。\n```\n\n### 其他命令\n\n```\ngo fix: 更新代码以使用Go语言的最新语法和API。\ngo bug: 打开浏览器并进入Go的错误报告页面。\n```\n\n## 跨平台编译\n\n要使用Go编译不同操作系统下的可执行文件，可以通过设置环境变量 `GOOS` 和 `GOARCH` 来实现（用于指定编译时的目标操作系统和目标架构）。\n\n在Windows上使用PowerShell或CMD时，环境变量的设置方式与Unix系统不同。\n\n使用 `set` 命令在CMD中设置环境变量：\n\n```cmd\nset GOOS=linux\nset GOARCH=amd64\ngo build -o hello_world\n```\n\n使用 `$env` 在PowerShell中设置环境变量：\n\n```powershell\n$env:GOOS=\"linux\"\n$env:GOARCH=\"amd64\"\ngo build -o hello_world\n```\n\n以下是在**PowerShell**中分别为Windows、macOS和Linux编译可执行文件的命令。\n\n### 编译Windows可执行文件\n\n```\n$env:GOOS=\"windows\"; $env:GOARCH=\"amd64\"; go build -o hello_world\n```\n\n### 编译macOS可执行文件\n\n```\n$env:GOOS=\"darwin\"; $env:GOARCH=\"amd64\"; go build -o hello_world\n```\n\n### 编译Linux可执行文件\n\n```\n$env:GOOS=\"linux\"; $env:GOARCH=\"amd64\"; go build -o hello_world\n```\n\n## Go语言特征\n\n### 命名\n\n1. Go的函数、变量、常量、自定义类型、包`(package)`的命名方式遵循以下规则\n\n   ```\n   1）首字符可以是任意的Unicode字符或者下划线\n   2）剩余字符可以是Unicode字符、下划线、数字\n   3）字符长度不限\n   ```\n2. Go只有25个关键字\n\n   ```\n    break        default      func         interface    select\n    case         defer        go           map          struct\n    chan         else         goto         package      switch\n    const        fallthrough  if           range        type\n    continue     for          import       return       var\n   ```\n3. Go有37个保留字\n\n   ```\n   Constants:    true  false  iota  nil\n\n   Types:    int  int8  int16  int32  int64  \n             uint  uint8  uint16  uint32  uint64  uintptr\n             float32  float64  complex128  complex64\n             bool  byte  rune  string  error\n\n   Functions:   make  len  cap  new  append  copy  close  delete\n                complex  real  imag\n                panic  recover\n   ```\n4. 可见性\n\n   ```\n    1）声明在函数内部，是函数的本地值，类似private\n    2）声明在函数外部，是对当前包可见(包内所有.go文件都可见)的全局值，类似protect\n    3）声明在函数外部且首字母大写是所有包可见的全局值,类似public\n   ```\n\n### 声明\n\n有四种主要声明方式\n\n```\n var（声明变量）, const（声明常量）, type（声明类型） ,func（声明函数）\n```\n\n## 内置类型和函数\n\n### 内置类型\n\n#### 值类型\n\n基本类型（布尔型、数字型）、字符串、数组、结构体。\n\n```\n基本类型：\n    布尔类型型：bool\n    数字类型：\n        整型：int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, uintptr\n        浮点型：float32, float64\n        复数类型：complex64, complex128\n    字符类型(golang中没有专门的字符类型,存放单个ascii字符,一般用byte保存,单个汉字一般用int来保存)：\n    	byte（uint8 的别名）\n    	rune（int32 的别名，用于表示 Unicode 码点）\n字符串：string\n数组：array，如 [5]int 表示长度为5的整数数组。\n结构体：struct，如 type Person struct { Name string; Age int }。\n接口类型：interface{}\n```\n\n#### 引用类型\n\n切片、映射、通道、指针、函数类型。\n\n```\n切片：slice\n[]int：表示一个整数切片。切片实际上是对底层数组的一种引用。\n映射：map\nmap[string]int：表示键为字符串、值为整数的映射。\n通道(管道)：chan\nchan int：表示一个传输整数类型的通道，用于Goroutine之间的通信。\n指针：*\n*int：表示指向整数类型的指针。指针是直接引用内存地址的类型。\n函数类型：func\nfunc(int, int) int：表示一个函数类型，函数在Go中也是一种引用类型。\n```\n\n#### 类型默认值\n\n在Go语言中，各个类型都有默认的零值，当变量声明但未显式初始化时，会自动赋予这个默认值。下面是各个常见类型的默认值：\n\n```\n基本类型：\n    布尔类型型：false\n    数字类型：\n        整型：0\n        浮点型：0.0\n        复数类型：0\n    字符类型：\n    	byte：0\n    	rune：0\n  \n派生类型：\n	字符串：\"\"\n	指针类型：默认值是 nil（表示空指针）。\n	数组：默认值是数组元素全为零值的数组，例如 [3]int 的默认值是 [0, 0, 0]。\n	切片：默认值是 nil（表示空切片），而不是空数组。\n	映射：默认值是 nil（表示空映射）\n	管道：默认值是 nil（表示空通道）\n	结构体：结构体的每个字段都被初始化为相应类型的零值，因此结构体的默认值是所有字段都为零值的结构体。\n	接口类型：默认值是 nil（表示空接口）\n```\n\n\n| 类型          | 长度(字节) | 默认值 | 说明                                      |\n| ------------- | ---------- | ------ | ----------------------------------------- |\n| bool          | 1          | false  |                                           |\n| byte          | 1          | 0      | uint8                                     |\n| rune          | 4          | 0      | Unicode Code Point, int32                 |\n| int, uint     | 4或8       | 0      | 32 或 64 位                               |\n| int8, uint8   | 1          | 0      | -128 ~ 127, 0 ~ 255，byte是uint8 的别名   |\n| int16, uint16 | 2          | 0      | -32768 ~ 32767, 0 ~ 65535                 |\n| int32, uint32 | 4          | 0      | -21亿~ 21亿, 0 ~ 42亿，rune是int32 的别名 |\n| int64, uint64 | 8          | 0      |                                           |\n| float32       | 4          | 0.0    |                                           |\n| float64       | 8          | 0.0    |                                           |\n| complex64     | 8          |        |                                           |\n| complex128    | 16         |        |                                           |\n| uintptr       | 4或8       |        | 以存储指针的 uint32 或 uint64 整数        |\n| array         |            |        | 值类型                                    |\n| struct        |            |        | 值类型                                    |\n| string        |            | \"\"     | UTF-8 字符串                              |\n| slice         |            | nil    | 引用类型                                  |\n| map           |            | nil    | 引用类型                                  |\n| channel       |            | nil    | 引用类型                                  |\n| interface     |            | nil    | 接口                                      |\n| function      |            | nil    | 函数                                      |\n\n### 内置函数\n\nGo语言提供了一些方便的内置函数，这些函数不需要导入任何包即可使用：\n\n```\n- **类型相关**：\n  - `new(T)`：创建一个类型为`T`的指针，并将分配的内存初始化为零值。\n  - `make(T, args)`：分配和初始化切片、映射或通道类型的实例。\n- **长度和容量**：\n  - `len(v)`：返回数组、切片、映射、字符串、通道的长度。\n  - `cap(v)`：返回数组、切片或通道的容量。\n- **内存管理**：\n  - `copy(dst, src)`：将`src`切片的元素复制到`dst`切片，返回复制的元素个数。\n  - `append(slice, elems...)`：将元素追加到切片后，返回新的切片。\n- **类型转换**：\n  - `complex(r, i)`：创建一个复数，实部为`r`，虚部为`i`。\n  - `real(c)`：返回复数`c`的实部。\n  - `imag(c)`：返回复数`c`的虚部。\n- **数学计算**：\n  - `close(c)`：关闭通道`c`，用于发送方不再发送数据的场景。\n- **反射和类型断言**：\n  - `panic(v)`：引发一个运行时错误，并终止程序的执行。\n  - `recover()`：用于从`panic`中恢复，通常与`defer`语句一起使用。\n```\n\n## 流程控制\n\n### 条件语句：if\n\n```\nif n := 0; n >0  {\n	println(\"正数\")\n} else if n < 0 {\n	println(\"负数\")\n} else {\n	println(\"零\")\n}\n```\n\n在Go语言中，`if n := 0; n >0` 这种写法是一种在`if`语句中声明和初始化变量的方式，n的作用域仅限于该 `if` 语句的范围内。\n\n*注意：go语言不支持三元操作符(三目运算符) \"a > b ? a : b\"*\n\n### 条件语句：switch\n\n```\nswitch var1 {\n    case val1:\n        ...\n    case val2:\n        ...\n    default:\n        ...\n}\n```\n\n### 条件语句：select\n\nselect 语句类似于 switch 语句，但是select会随机执行一个可运行的case。如果没有case可运行，它将阻塞，直到有case可运行。\n\n```\nselect {\n    case communication clause  :\n       statement(s);  \n    case communication clause  :\n       statement(s);\n    /* 你可以定义任意数量的 case */\n    default : /* 可选 */\n       statement(s);\n}\n```\n\n### 循环语句：for\n\nGolang for支持三种循环方式，包括类似 while 的语法\n\n```\ns := \"abc\"\n\n1.\nfor i, n := 0, len(s); i < n; i++ { // 常见的 for 循环，支持初始化语句。\n    println(s[i])\n}\n\n2.\nn := len(s)\nfor n > 0 {                // 替代 while (n > 0) {}\n    println(s[n])        // 替代 for (; n > 0;) {}\n    n-- \n}\n\n3.\nfor {                    // 替代 while (true) {}\n    println(s)            // 替代 for (;;) {}\n}\n```\n\n### 循环语句：for...range\n\nGolang range类似迭代器操作，返回 (索引, 值) 或 (键, 值)。\n\nfor 循环的 range 格式可以对 slice、map、数组、字符串等进行迭代循环。格式如下：\n\n```\nfor key, value := range oldMap {\n    newMap[key] = value\n}\n```\n\n### 循环控制goto、break、continue\n\n**goto：**`goto` 语句用于跳转到代码中的指定标签。它可以用来在任意位置转到特定标签，但使用时需要谨慎，因为不当使用 `goto` 可能会导致代码的可读性差和难以维护。\n\n```\npackage main\n\nimport \"fmt\"\n\nfunc main() {\n    i := 0\nloop:\n    if i >= 5 {\n        goto end // 跳转到 end 标签\n    }\n    fmt.Println(i)\n    i++\n    goto loop // 跳转回 loop 标签\nend:\n    fmt.Println(\"Done\")\n}\n```\n\n**break：**`break` 语句用于退出当前循环（`for`、`switch` 或 `select`）。当 `break` 被执行时，循环立即终止，不会继续执行循环体内的后续代码。\n\n**continue：**`continue` 语句用于跳过当前循环的剩余部分，直接开始下一次迭代。`continue` 只会影响包含它的最近的循环。\n\n## 函数\n\n## 方法\n\n# 面向对象\n\n# 网络编程\n\n# 并发编程\n\n# 数据操作\n\n# gin框架\n', 'static\\image\\1748705255607615900.jpg', 1, 1, '2025-05-16 17:06:33', 1, '2025-06-10 17:56:37', 1, 0, 1, 1);

-- ----------------------------
-- Table structure for article_cate
-- ----------------------------
DROP TABLE IF EXISTS `article_cate`;
CREATE TABLE `article_cate`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '分类名称',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `creator_id` int NOT NULL COMMENT '创建人id',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `updater_id` int NOT NULL DEFAULT 0 COMMENT '更新人id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_bin ROW_FORMAT = DYNAMIC;

